function norm(v){return String(v||'').trim().toLowerCase()}
function slug(v){return norm(v).replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
function db(){return JSON.parse(localStorage.getItem('shakuntalam_db')||'null')}
function saveDB(d){try{localStorage.setItem('shakuntalam_db',JSON.stringify(d));return true}catch(error){if(error?.name!=='QuotaExceededError')throw error;compactDatabaseImages(d);toast('Storage is full. Compressing saved photos to free space…');return false}}
async function compactDatabaseImages(data){if(window._dbImageCompaction)return window._dbImageCompaction;window._dbImageCompaction=(async()=>{const cache=new Map();async function walk(value){if(typeof value==='string'&&value.startsWith('data:image/')&&value.length>48000){if(cache.has(value))return cache.get(value);const compressed=await new Promise(resolve=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,960/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/webp',.66);resolve(result.length<value.length?result:value)};image.onerror=()=>resolve(value);image.src=value});cache.set(value,compressed);return compressed}if(Array.isArray(value)){for(let i=0;i<value.length;i++)value[i]=await walk(value[i]);return value}if(value&&typeof value==='object'){for(const key of Object.keys(value))value[key]=await walk(value[key])}return value}try{await walk(data);localStorage.setItem('shakuntalam_db',JSON.stringify(data));toast('Saved photos were compressed and browser storage is available again.');route();return true}catch(_){toast('Browser storage is still full. Remove older photos from the gallery or homepage carousels, then retry.');return false}finally{window._dbImageCompaction=null}})();return window._dbImageCompaction}
