function toast(t){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el)}el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function header(){return `<div class="topbar admission-ticker" aria-label="Admission Open for Session 2026-27 | BBA &amp; BCA"><div class="admission-track"><span>Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span><span aria-hidden="true">Admission Open for Session 2026-27 <b>|</b> BBA &amp; BCA</span></div></div><header class="nav"><div class="container navin"><a class="brand" href="#/"><span class="logo-mark">S</span><span>SHAKUNTALAM<small>COLLEGE</small></span></a><nav class="links"><a href="#/about">About</a><a href="#/departments">Departments</a><a href="#/notices">Notices</a><a href="#/facilities">Facilities</a><a href="#/gallery">Gallery</a><a href="#/contact">Contact</a></nav><div class="nav-actions"><a class="btn btn-ghost" href="#/admissions">Apply Now</a><button class="btn btn-primary" onclick="openLogin()">Portal Login</button><button class="hamb" onclick="toggleMobile()">☰</button></div></div><div class="mobile-menu" id="mobileMenu"><a href="#/about">About</a><a href="#/departments">Departments</a><a href="#/notices">Notices</a><a href="#/facilities">Facilities</a><a href="#/gallery">Gallery</a><a href="#/contact">Contact</a><a href="#/admissions">Apply Now</a></div></header>`}
