function home(){const campuses=[{name:'Main Campus',year:'EST. 2015',icon:'⌂',copy:'Shakuntalam Institute of Teachers Education. Our founding academic campus for teacher education and management studies.',courses:['B.Ed','D.El.Ed','BBA','BCA'],dept:'Teacher Education · Management',map:'https://www.google.com/maps?cid=7703227135613750179&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzEAMYASAF&hl=en&gl=IN&source=embed'},{name:'City Campus',year:'EST. 2026',icon:'⌖',copy:'Our dedicated home for management education, designed for collaboration, digital learning and tomorrow’s business leaders.',courses:['BBA','BCA'],dept:'Department of Management',map:'https://www.google.com/maps/place/Shakuntalam+College+(BBA+%26+BCA+Department)/@24.9538418,84.0241586,17z/data=!3m1!4b1!4m6!3m5!1s0x398db1ec042ccb39:0xecab3cf3c5d33aa8!8m2!3d24.9538418!4d84.0241586!16s%2Fg%2F11z6jp40pk?hl=en&entry=ttu&g_ep=EgoyMDI2MDkyMy4wIKXMDSoASAFQAw%3D%3D'},{name:'Industrial Campus',year:'EST. 2009',icon:'⚒',copy:'Shakuntalam Industrial Training Institute builds technical confidence through hands-on training and workshop practice.',courses:['Electrician','Fitter'],dept:'Department of Industrial Training',map:'https://www.google.com/maps/place/Shakuntalam+ITI/@24.9525114,84.0663153,17.22z/data=!4m14!1m7!3m6!1s0x398db1ec042ccb39:0xecab3cf3c5d33aa8!2sShakuntalam+College+(BBA+%26+BCA+Department)!8m2!3d24.9538418!4d84.0241586!16s%2Fg%2F11z6jp40pk!3m5!1s0x398db05d6f95f23b:0xf453f8b6c2883efd!8m2!3d24.9517731!4d84.0678075!16s%2Fg%2F11c70hl99d?hl=en&entry=ttu&g_ep=EgoyMDI2MDkyMy4wIKXMDSoASAFQAw%3D%3D'}];const departments=[{name:'Department of Teachers Education',tag:'NCTE · VKSU',copy:'Prepare to inspire the next generation through thoughtful, practice-based teacher education.',courses:'B.Ed · D.El.Ed',href:'#/course/B.Ed.'},{name:'Department of Management',tag:'AICTE · VKSU',copy:'Build business acumen, digital confidence and the communication skills employers value.',courses:'BBA · BCA',href:'#/course/BBA'},{name:'Department of Industrial Training',tag:'NCVT',copy:'Learn in-demand technical skills through workshop practice and career-oriented training.',courses:'Electrician · Fitter',href:'#/course/Electrician'},{name:'Department of Nursing Education',tag:'UPCOMING',copy:'A new pathway in compassionate, practical nursing education is on the horizon.',courses:'ANM · Coming soon',href:'#/academics'}];return layout(`<main><section class="hero"><div class="container hero-grid"><div><span class="eyebrow">✦ SHAKUNTALAM COLLEGE • 2026–27</span><h1>Shape your future with <span>purpose.</span></h1><p>A modern college experience combining teacher education, management, computing and industrial training with a connected student portal.</p><div class="hero-actions"><a class="btn btn-primary" href="#/admissions">Start Admission →</a><a class="btn btn-outline" href="#/departments">Explore Programs</a></div></div><div class="hero-card"><img src="${img.hero}" alt="Students learning together"><div style="display:flex;justify-content:space-between;padding:13px 4px 0;font-size:12px"><span>Student-first learning</span><b>2026–27</b></div></div></div></section><div class="container floating"><div class="stats"><div class="stat"><b>06</b><span>Career-focused courses</span></div><div class="stat"><b>${students().length}</b><span>Student records</span></div><div class="stat"><b>03</b><span>Academic departments</span></div><div class="stat"><b>24×7</b><span>College portal access</span></div></div></div><section class="section story-section"><div class="container"><span class="kicker">Our foundation</span><h2>Rooted in values.<br>Ready for tomorrow.</h2><p>Founded by Devi Shakuntalam Pratisthan in 2009, Shakuntalam College is a growing educational community committed to opportunity, practical learning and personal growth. Across our three campuses, students are encouraged to think boldly and contribute meaningfully.</p><p>From teacher education and management to skilled technical training, our programs connect classroom learning with the world beyond it.</p><div class="story-values"><b>✓ &nbsp; Experienced faculty</b><b>✓ &nbsp; Practical learning</b><b>✓ &nbsp; Supportive community</b><b>✓ &nbsp; Industry-focused skills</b></div></div></section><section class="section campus-section" id="campuses"><div class="container"><div class="section-head centered-head"><div><span class="kicker">Find your campus</span><h2>One college. Three places to grow.</h2><p>Each campus has its own character, community and learning environment. Find the home for your next chapter.</p></div></div><div class="campus-grid-ref">${campuses.map(c=>`<article class="campus-card-ref"><div class="campus-card-top"><span class="campus-icon-ref">${c.icon}</span><span class="campus-year-ref">${c.year}</span></div><h3>${c.name}</h3><p>${c.copy}</p><div class="campus-tags-ref">${c.courses.map(x=>`<span>${x}</span>`).join('')}</div><div class="campus-card-bottom"><b>${c.dept}</b><a href="${c.map}" target="_blank" rel="noopener">Get directions ↗</a></div></article>`).join('')}</div></div></section><section class="section programs-section" id="programs"><div class="container"><div class="section-head centered-head"><div><span class="kicker">Study at Shakuntalam</span><h2>Find the course that moves you forward.</h2><p>Explore our departments and programs. Course progression is organized by department, course and semester.</p></div></div><div class="program-grid-ref">${departments.map(d=>`<article class="program-card-ref"><span class="program-badge-ref ${d.tag==='UPCOMING'?'upcoming':''}">${d.tag}</span><h3>${d.name}</h3><p>${d.copy}</p><small>${d.courses}</small><a href="${d.href}">${d.tag==='UPCOMING'?'Stay informed':'Explore department'} →</a></article>`).join('')}</div><p class="recognition-note">BBA &amp; BCA recognized by AICTE &amp; NCTE, New Delhi and affiliated by VKSU, Ara. B.Ed affiliated by VKSU, Ara and D.El.Ed affiliated by Bihar Board, Patna; both recognized by NCTE, ERC Bhubaneswar. Electrician &amp; Fitter recognized by NCVT, New Delhi.</p></div></section><section class="section authority-section"><div class="container"><div class="section-head centered-head"><div><span class="kicker">Official education authorities</span><h2>Education Authorities &amp; Affiliations</h2><p>Explore the universities, regulatory councils and education boards that recognize, regulate or affiliate our programmes.</p></div></div><div class="authority-grid"><a class="authority-card" href="https://ncte.gov.in/Website/Index.aspx" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>NCTE</span>NCTE</span><strong>National Council for Teacher Education</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://biharboardonline.bihar.gov.in/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>BSEB</span>BSEB</span><strong>Bihar School Examination Board</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://www.vksu.ac.in/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>VKSU</span>VKSU</span><strong>Veer Kunwar Singh University</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://ugc.gov.in/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>UGC</span>UGC</span><strong>University Grants Commission</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://www.aicte-india.org/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>AICTE</span>AICTE</span><strong>All India Council for Technical Education</strong><small>Visit official website ↗</small></a></div></div></section><section class="section dark-section"><div class="container mission"><div><span class="kicker">Why Shakuntalam</span><h2>Learning that connects knowledge with opportunity.</h2><p class="muted" style="line-height:1.8">The public college information describes a focus on academic excellence, practical exposure, internships, modern facilities and continuous professional development. This demo turns that philosophy into a connected digital experience.</p><a class="btn btn-primary" href="#/mission">Our vision &amp; values</a></div><div class="card"><div class="quote">“Education is most powerful when it becomes confidence, skill and responsible action.”</div><p class="muted">A college-portal interpretation for the website demo.</p></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Latest updates</span><h2>Notice board</h2></div><a class="btn btn-outline" href="#/notices">All notices</a></div><div class="notice-list">${noticesData().slice(0,4).map(notice).join('')}</div></div></section></main>`)}
function courseCard(c){return `<article class="card course-card"><img src="${c[0]==='BCA'?img.class:c[0].includes('Electric')?img.lab:img.campus}" alt="${c[0]}"><div class="course-body"><span class="pill">${c[3]}</span><h3>${c[0]}</h3><small class="muted">${c[1]}</small><p>${c[2]}</p><a href="#/course/${encodeURIComponent(c[0])}" class="btn btn-ghost">View course →</a></div></article>`}
function subjectsForCourse(course){const map={
  'B.Ed.':['Child Development & Learning','Pedagogy of School Subject','Assessment & Evaluation','Educational Technology'],
  'D.El.Ed.':['Child Development','Pedagogy & Teaching Methods','School Management','Assessment'],
  'BBA':['Principles of Management','Business Economics','Financial Accounting','Business Communication'],
  'BCA':['Programming Fundamentals','Database Management','Computer Networks','Web Technology'],
  'Electrician':['Electrical Fundamentals','Wiring & Installation','Electrical Machines','Workshop Practice'],
  'Fitter':['Engineering Drawing','Fitting Practice','Workshop Technology','Measurement & Metrology']
};return map[course]||['Core Subject','Practical','Assessment'];}
function noticeCard(n,i){return notice(n);}
function notice(n){return `<div class="notice"><div><strong>${n[1]}</strong><small>${n[2]}</small></div><div class="date">${n[0].split(' ')[0]}<small>${n[0].split(' ').slice(1).join(' ')}</small></div></div>`}
function page(title,sub,body){return layout(`<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / ${title}</div><h1>${title}</h1><p>${sub}</p></div></section>${body}`)}
function about(){return page('About Shakuntalam','A growing learning community, founded on opportunity, practical preparation and the belief that education shapes the future.',`<section class="section about-opening"><div class="container about-feature-grid"><article class="card about-story-card"><img src="${siteConfig().aboutPageImage||img.campus}" alt="A welcoming college campus" class="about-campus-image"><span class="kicker">Our story</span><h2>Rooted in education. Preparing for what comes next.</h2><p>Shakuntalam Group of Institutions is a learning community dedicated to helping students build knowledge, confidence and practical skills. The story began with Devi Shakuntalam Pratishthan in 2009, followed by the establishment of Shakuntalam Institute of Teachers Education in 2015.</p><p>Located at Kumhau Station Road in Sasaram, Rohtas, Bihar, the institute focuses on preparing thoughtful and capable educators. Its work brings academic study together with practice, mentorship and a supportive campus experience.</p></article><aside class="card about-facts-card"><span class="kicker">Our journey · 2009—2026</span><div class="about-years-highlight"><strong>17</strong><span><b>Years of excellence</b><small>Growing with purpose since 2009</small></span></div><div class="about-fact"><strong>2009</strong><span><b>Devi Shakuntalam Pratishthan founded</b><small>Shakuntalam Industrial Training Institute established</small></span></div><div class="about-fact"><strong>2015</strong><span><b>Shakuntalam Institute of Teachers Education established</b><small>A dedicated home for aspiring educators</small></span></div><div class="about-fact"><strong>2026</strong><span><b>Shakuntalam City Campus opens its doors</b><small>Expanding learning opportunities in Sasaram</small></span></div><div class="about-fact"><strong>06</strong><span><b>Courses across the group</b><small>Six pathways, with more opportunities on the horizon</small></span></div><div class="about-fact"><strong>03</strong><span><b>Connected fields. One shared purpose.</b><small>Teacher education · Management · Industrial training</small></span></div></aside></div></section><section class="section about-section"><div class="container about-two-col"><div><span class="kicker">A purpose that lasts</span><h2>Education with care, curiosity and responsibility.</h2></div><div><p class="lead">Teacher education is about more than a qualification. It is preparation to guide learners, encourage questions and make a lasting contribution to the community.</p><p class="muted">The institute aims to nurture educators who combine a sound academic foundation with empathy, clear communication and a commitment to continual learning. Students are encouraged to grow as individuals while preparing for the responsibilities of the teaching profession.</p><a class="btn btn-primary" href="#/leadership">Meet our leadership →</a></div></div></section><section class="section about-section about-tint"><div class="container"><div class="section-head"><div><span class="kicker">Learning by doing</span><h2>Build understanding in the classroom and beyond.</h2></div><p>Academic study becomes more meaningful when students can connect ideas to real situations.</p></div><div class="about-pillar-grid"><article class="card about-pillar"><span class="about-pillar-number">01</span><h3>Strong foundations</h3><p>Coursework supports understanding of educational ideas, learners and the responsibilities of teaching.</p></article><article class="card about-pillar"><span class="about-pillar-number">02</span><h3>Practice and reflection</h3><p>Teaching practice and internship experiences help students apply learning in real classroom settings and reflect on their growth.</p></article><article class="card about-pillar"><span class="about-pillar-number">03</span><h3>Guidance and mentorship</h3><p>Experienced educators share knowledge, offer guidance and help aspiring teachers connect theory with professional practice.</p></article></div></div></section><section class="section about-section"><div class="container about-two-col about-facilities"><div><span class="kicker">The learning environment</span><h2>Space to learn, practice and collaborate.</h2></div><div><p class="muted">The college describes a campus designed to support focused study and hands-on learning. Classrooms, laboratories and a resource-rich library contribute to an environment where students can explore ideas, work together and build practical understanding.</p><p class="muted">Learning also extends through workshops, teaching internships and professional development. These experiences help students become familiar with classroom responsibilities and stay engaged with evolving approaches to education and technology.</p><a class="btn btn-outline" href="#/infrastructure">Explore campus facilities →</a></div></div></section><section class="section about-section about-tint about-community-section"><div class="container about-community"><span class="kicker">A community beyond graduation</span><h2>Grow with people who support your journey.</h2><p class="lead">A positive college experience depends on encouragement, shared effort and a sense of belonging.</p><p class="muted">Students learn alongside peers, receive guidance from faculty and build relationships that can continue well beyond their studies. The institution values a welcoming environment where learners can develop confidence, support one another and prepare to serve their communities as educators.</p><div class="about-values"><span>Supportive learning</span><span>Practical preparation</span><span>Professional growth</span><span>Community connection</span></div></div></section><section class="section about-section about-next-section"><div class="container about-next"><div><span class="kicker">Your next chapter</span><h2>Find the path that fits your ambitions.</h2><p class="muted">Explore teacher education programs, learn about the wider group of institutions or contact the college for guidance about admissions and student support.</p></div><div class="about-next-actions"><a class="btn btn-primary" href="#/departments">Explore departments →</a><a class="btn btn-outline" href="#/contact">Contact the college →</a></div></div></section>`)}
function mission(){return page('Vision, Mission & Core Values','A clear institutional framework for learning, character, skills and community impact.',`<section class="section"><div class="container"><div class="mission"><div class="card"><span class="kicker">Vision</span><h2 style="font:800 31px Manrope">Empower learners to create meaningful impact.</h2><p class="muted" style="line-height:1.8">Build an inclusive academic environment where knowledge, practical skills, technology and responsible citizenship grow together.</p></div><div class="card"><span class="kicker">Mission</span><h2 style="font:800 31px Manrope">Teach. Practice. Lead.</h2><p class="muted" style="line-height:1.8">Deliver relevant education, practical exposure, mentorship and digital access while encouraging curiosity, discipline and continuous improvement.</p></div></div><div class="cards" style="margin-top:20px">${[['01','Integrity','Act with honesty, fairness and accountability.'],['02','Excellence','Pursue high standards in learning and service.'],['03','Innovation','Use technology and creativity to solve real problems.'],['04','Inclusion','Respect diverse learners, ideas and experiences.'],['05','Practice','Connect classroom knowledge to hands-on work.'],['06','Service','Contribute positively to campus and community.']].map(x=>`<div class="card"><div class="icon">${x[0]}</div><h3 style="font:800 19px Manrope">${x[1]}</h3><p class="muted">${x[2]}</p></div>`).join('')}</div></div></section>`)}
function departments(){
 const items=[
  {name:'Department of Teachers Education',courses:['B.Ed.','D.El.Ed.'],copy:'Prepare to support confident, curious learners through the study of child development and effective teaching. Connect educational ideas with lesson planning, classroom practice and reflection. Build the skills to make learning inclusive, engaging and purposeful.',slug:'teachers-education',badge:'NCTE · VKSU'},
  {name:'Department of Management',courses:['BBA','BCA'],copy:'Explore business, management and computing through a practical, career-focused learning experience. Strengthen communication, teamwork and problem-solving alongside core academic knowledge. Develop the confidence to contribute to organisations, technology and new ideas.',slug:'management',badge:'AICTE · VKSU'},
  {name:'Department of Industrial Training',courses:['Electrician','Fitter'],copy:'Build technical ability through trade instruction, hands-on workshop practice and safe tool use. Learn to approach practical tasks with accuracy, discipline and confidence. Prepare with foundational skills for technical and industrial workplaces.',slug:'industrial-training',badge:'NCVT'},
  {name:'Department of Nursing Education',courses:['ANM · Coming soon'],copy:'A planned pathway centred on compassionate care, practical preparation and community wellbeing. The proposed program will introduce learners to essential nursing knowledge and patient-focused practice. Contact the college for updates as plans progress.',upcoming:true,badge:'UPCOMING'}
 ];
 return page('Departments & Programs','Explore focused pathways in teacher education, management, computing and industrial training.',`<section class="section"><div class="container"><div class="department-list-grid">${items.map((d,i)=>`<article class="card department-list-card"><div class="department-card-top"><span class="pill ${d.upcoming?'upcoming':''}">${d.badge}</span><span class="department-card-number">0${i+1}</span></div><h2>${d.name}</h2><p class="muted">${d.copy}</p><div class="department-course-tags">${d.courses.map(c=>`<span>${c}</span>`).join('')}</div><a class="btn ${d.upcoming?'btn-outline':'btn-primary'}" href="#/${d.upcoming?'contact':'department/'+d.slug}">${d.upcoming?'Contact us for updates':'Explore department'} →</a></article>`).join('')}</div></div></section>`)
}
function course(name){const c=courses.find(x=>x[0]===name)||courses[0];return page(c[0],`${c[1]} • ${c[3]}`,`<section class="section"><div class="container feature-grid"><div class="card"><img src="${c[0]==='BCA'?img.class:c[0].includes('Electric')?img.lab:img.campus}" style="width:100%;height:330px;object-fit:cover;border-radius:16px"><h2 style="font:800 30px Manrope;margin-top:22px">${c[0]} program</h2><p class="muted" style="line-height:1.8">${c[2]} The demo curriculum page includes course highlights, eligibility, learning outcomes, practical exposure and an admission call-to-action.</p><a class="btn btn-primary" href="#/admissions">Apply for ${c[0]}</a></div><div class="card"><span class="kicker">Program snapshot</span>${[['Duration',c[3]],['Department',c[1]],['Mode','Campus + digital support'],['Assessment','Internal + semester / practical'],['Portal','Student ERP enabled']].map(x=>`<div style="padding:17px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px"><span class="muted">${x[0]}</span><b>${x[1]}</b></div>`).join('')}<div style="margin-top:20px;padding:15px;background:#edf4ff;border-radius:14px;color:#174b9a"><b>Demo note:</b> Replace curriculum, seat count and fee details with the approved institutional data before production.</div></div></div></section>`)}
function notices(){return page('Notice Board','Admissions, examinations, academic schedules and campus announcements.',`<section class="section"><div class="container"><div class="notice-list">${noticesData().map(notice).join('')}</div><div class="card" style="margin-top:20px"><b>Need a notice?</b><p class="muted">Administrators can publish new notices from the admin portal in this demo.</p><a class="btn btn-primary" href="#/portal/admin">Open Admin Portal</a></div></div></section>`)}
function facilities(){return page('Facilities','A practical, student-friendly campus ecosystem.',`<section class="section"><div class="container grid-4">${facilitiesSeed.map(x=>`<div class="facility"><div class="icon">${x[0]}</div><h3>${x[1]}</h3><p class="muted">${x[2]}</p></div>`).join('')}</div></section>`)}
function gallery(){return page('Campus Gallery','A visual showcase section ready for real campus photography.',`<section class="section"><div class="container gallery">${[img.campus,img.class,img.library,img.lab,img.students,img.hero].map((x,i)=>`<img src="${x}" alt="Campus gallery ${i+1}">`).join('')}</div></section>`)}
function contact(){return page('Contact & Locations','Connect with admissions, academics or the administration office.',`<section class="section contact-locations"><div class="container"><div class="locations-grid"><article class="card location-card"><span class="kicker">Teacher Education</span><h2>Shakuntalam Institute of Teachers Education</h2><p><b>Address</b><br>Kirhindih Road, Sasaram, Rohtas-821111</p><p><b>Contact</b><br><a href="tel:9470014145">9470014145</a>, <a href="tel:8789036195">8789036195</a></p></article><article class="card location-card"><span class="kicker">BBA &amp; BCA Department</span><h2>Shakuntalam College (City Campus)</h2><p><b>Address</b><br>Bauliya More, Jagdev Path, Sasaram, Rohtas-821115</p><p><b>Contact</b><br><a href="tel:9470014145">9470014145</a>, <a href="tel:8789036195">8789036195</a></p></article><article class="card location-card"><span class="kicker">Industrial Training</span><h2>Shakuntalam Industrial Training Institute</h2><p><b>Address</b><br>Admapur, Karawandiya, Sasaram, Rohtas-821115</p><p><b>Contact</b><br><a href="tel:9939205777">9939205777</a>, <a href="tel:7050001226">7050001226</a></p></article><article class="card location-card"><span class="kicker">Upcoming</span><h2>Shakuntalam Institute of Nursing</h2><p class="location-upcoming">Upcoming</p><p><b>Contact</b><br><a href="tel:9470014145">9470014145</a>, <a href="tel:8789036195">8789036195</a></p></article></div><div class="card contact-enquiry"><div><span class="kicker">Get in touch</span><h2>Send an enquiry</h2><p class="muted">Our team can help with admissions, courses and campus information.</p></div><form class="form" onsubmit="event.preventDefault();toast('Enquiry submitted in demo mode.');this.reset()"><div class="form-grid"><input placeholder="Your name" required><input type="email" placeholder="Email" required></div><textarea rows="3" placeholder="How can we help?"></textarea><button class="btn btn-primary">Send enquiry</button></form></div></div></section>`)}
function admissions(){return page('Admissions 2026–27','Apply online, select a program and continue to the fee/payment stage.',`<section class="section"><div class="container feature-grid"><div class="card"><span class="kicker">Step 01</span><h2 style="font:800 29px Manrope">Application form</h2><form class="form" onsubmit="submitAdmission(event)"><div class="form-grid"><input id="adName" placeholder="Full name" required><input id="adPhone" placeholder="Mobile number" required></div><input id="adEmail" type="email" placeholder="Email address" required><select id="adCourse"><option>B.Ed.</option><option>D.El.Ed.</option><option>BBA</option><option>BCA</option><option>Electrician</option><option>Fitter</option></select><textarea id="adAddress" rows="3" placeholder="Address"></textarea><button class="btn btn-primary">Submit application →</button></form></div><div class="card"><span class="kicker">Step 02</span><h2 style="font:800 29px Manrope">Pay application / fees</h2><p class="muted" style="line-height:1.7">The demo payment portal supports UPI, cards and net banking selection with a simulated success receipt.</p><a class="btn btn-dark" href="#/payment">Open payment gateway</a><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><b>Production setup</b><p class="muted">Connect Razorpay/PayU/Cashfree on the server, verify signatures server-side, and store transaction IDs in the ERP database.</p></div></div></section>`)}
function submitAdmission(e){e.preventDefault();const id='APP-'+Date.now().toString().slice(-7);toast(`Application ${id} submitted successfully (demo).`);e.target.reset()}
function payment(){return page('Secure Fee Payment','Demo checkout with UPI, credit/debit card and net-banking modes.',`<section class="section"><div class="container" style="max-width:850px"><div class="card"><div class="tabs" id="payTabs"><button class="active" onclick="payMode('upi',this)">UPI</button><button onclick="payMode('card',this)">Card</button><button onclick="payMode('netbanking',this)">Net Banking</button></div><div id="payForm"></div></div></div></section>`)}
function payMode(mode,btn){document.querySelectorAll('#payTabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const fields=mode==='upi'?'<input id="payRef" placeholder="UPI ID (e.g. demo@upi)" required>':mode==='card'?'<div class="form-grid"><input placeholder="Card number" required><input placeholder="MM/YY" required></div><input placeholder="Cardholder name" required><input placeholder="CVV" required>':'<select required><option>State Bank of India</option><option>HDFC Bank</option><option>ICICI Bank</option><option>Punjab National Bank</option></select><input placeholder="Net banking customer ID" required>';document.getElementById('payForm').innerHTML=`<form class="form" onsubmit="demoPay(event)"><div class="form-grid"><input placeholder="Student ID" required value="STU-2026001"><input type="number" placeholder="Amount" value="5000" required></div>${fields}<button class="btn btn-primary">Pay ₹5,000 securely →</button><small class="muted">Demo mode — no real money is transferred.</small></form>`}
function demoPay(e){e.preventDefault();const tx='TXN'+Date.now().toString().slice(-9);e.target.innerHTML=`<div style="text-align:center;padding:25px"><div class="icon" style="margin:auto;background:#eaf8f2;color:#11865e">✓</div><h2 style="font:800 28px Manrope">Payment successful</h2><p class="muted">Demo receipt generated for transaction <b>${tx}</b>.</p><button class="btn btn-outline" onclick="window.print()">Print receipt</button></div>`;toast('Payment completed in demo mode.')}
function loginModal(){return `<div class="modal" id="loginModal"><div class="modal-box"><div class="modal-head"><div><span class="kicker">SHAKUNTALAM COLLEGE</span><h2 style="font:800 27px Manrope;margin:4px 0">Portal Login</h2></div><button class="close" onclick="closeLogin()">×</button></div><div class="tabs"><button class="active" onclick="setRole('student',this)">Student</button><button onclick="setRole('teacher',this)">Teacher</button><button onclick="setRole('admin',this)">Admin</button></div><form class="form" onsubmit="portalLogin(event)"><div id="loginError" class="login-error" role="alert" aria-live="polite" hidden></div><input id="loginUser" autocomplete="username" oninput="clearLoginError()" placeholder="Student name / username / ID" required><input id="loginPass" autocomplete="current-password" oninput="clearLoginError()" type="password" placeholder="Password / number" required><button class="btn btn-primary">Sign in</button><small class="muted" id="loginHint">Student username is your full name. Initial password is the number supplied by the college.</small></form></div></div>`}
let role='student';function clearLoginError(){const e=document.getElementById('loginError');if(e){e.textContent='';e.hidden=true}}function showLoginError(message){const e=document.getElementById('loginError');if(e){e.textContent=message;e.hidden=false}else toast(message)}function openLogin(){clearLoginError();const modal=document.getElementById('loginModal'),studentTab=modal?.querySelector('.tabs button');role='student';if(studentTab)setRole('student',studentTab);const user=document.getElementById('loginUser'),password=document.getElementById('loginPass');if(user)user.value='';if(password)password.value='';modal?.classList.add('show')}function closeLogin(){document.getElementById('loginModal').classList.remove('show')}function setRole(r,b){role=r;clearLoginError();b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const u=document.getElementById('loginUser'),p=document.getElementById('loginPass'),h=document.getElementById('loginHint');if(u)u.placeholder=r==='student'?'Student name / username / ID':r==='teacher'?'Teacher username / ID':'Administrator username / ID';if(p)p.placeholder=r==='student'?'Password / number':'Password';if(h)h.textContent=r==='student'?'Student username is your full name. Password is your assigned number.':r==='teacher'?'Use your teacher username and password.':'Use the administrator credentials.'}
function portalLogin(e){e.preventDefault();const u=document.getElementById('loginUser').value.trim(),pw=document.getElementById('loginPass').value;let who=null;if(role==='student')who=students().find(x=>(norm(x.username)===norm(u)||norm(x.id)===norm(u)||norm(x.name)===norm(u))&&String(x.password)===String(pw));if(role==='teacher')who=teachers().find(x=>norm(x.username)===norm(u)&&String(x.password)===String(pw));if(role==='admin'){const a=db().admin;if(norm(a.username)===norm(u)&&String(a.password)===String(pw))who={...a,name:'Administrator',role:'admin'}}if(!who){toast('Invalid username or password.');return}if(who.status==='Inactive'){toast('This account is inactive. Contact the administrator.');return}setSession({role,...who});location.hash=`/portal/${role}`;closeLogin()}
function side(role,active){const items=role==='admin'?['dashboard','students','teachers','notices','payments','settings']:role==='teacher'?['dashboard','attendance','assignments','results']:['dashboard','profile','attendance','fees','results','notices'];return `<aside class="side portal-sidebar-${role}"><a class="brand" href="#/"><span class="logo-mark">S</span><span>SHAKUNTALAM<small>COLLEGE</small></span></a><nav>${items.map(i=>`<a class="${i===active?'active':''}" href="#/portal/${role}/${i}">${icon(i)} ${titleCase(i)}</a>`).join('')}</nav><button class="btn btn-ghost" style="width:100%;margin-top:20px" onclick="clearSession();location.hash='/'">Sign out</button></aside>`}function icon(x){return ({dashboard:'◈',students:'♙',teachers:'♙',attendance:'✓',assignments:'▤',results:'▥',fees:'₹',notices:'!',payments:'◫',profile:'◎',settings:'⚙'})[x]||'•'}function titleCase(x){return x.replace(/(^|_)/g,' ').replace(/\b\w/g,m=>m.toUpperCase())}
function portal(role,section='dashboard'){return `<div class="portal">${side(role,section)}<main class="portal-main"><div class="topline"><div><div class="kicker">${role} portal</div><h1>${titleCase(section)}</h1></div><div class="avatar">${role[0].toUpperCase()}</div></div>${role==='admin'?adminContent(section):role==='teacher'?teacherContent(section):studentContent(section)}</main></div>`}
function side(role,active){const items=role==='admin'?['dashboard','students','teachers','admissions','notices','payments','settings']:role==='teacher'?['dashboard','attendance','assignments','results']:['dashboard','profile','attendance','fees','results','notices'];return `<aside class="side portal-sidebar-${role}"><a class="brand" href="#/"><img class="brand-logo" src="${_logo}" alt="Shakuntalam College logo"><span>SHAKUNTALAM<small>COLLEGE</small></span></a><nav>${items.map(i=>`<a class="${i===active?'active':''}" href="#/portal/${role}/${i}">${icon(i)} ${titleCase(i)}</a>`).join('')}</nav><button class="btn btn-ghost" style="width:100%;margin-top:20px" onclick="clearSession();location.hash='/'">Sign out</button></aside>`}
function adminContent(s){if(s==='students')return adminStudents();if(s==='teachers')return adminTeachers();if(s==='notices')return adminNotices();if(s==='payments')return adminPayments();if(s==='settings')return adminSettings();return adminDashboard()}
function adminDashboard(){const s=students();return `<div class="dash-grid"><div class="metric"><b>${s.length}</b><small>Total students</small></div><div class="metric"><b>${s.filter(x=>x.status==='Active').length}</b><small>Active students</small></div><div class="metric"><b>${s.filter(x=>x.fees==='Due').length}</b><small>Fee dues</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div></div><div class="admin-grid"><div class="card"><span class="kicker">Control centre</span><h2>College administration</h2><p class="muted">Manage student records, credentials, attendance, notices, fees, teachers and website content from one place.</p><div class="quick-grid"><a class="btn btn-primary" href="#/portal/admin/students">Manage students</a><a class="btn btn-ghost" href="#/portal/admin/teachers">Manage teachers</a><a class="btn btn-ghost" href="#/portal/admin/notices">Manage notices</a><a class="btn btn-ghost" href="#/portal/admin/settings">College settings</a></div></div><div class="card"><span class="kicker">Live demo data</span><h3>Everything is stored in the browser database</h3><p class="muted">Changes made here are immediately used by the public pages and portal login until browser storage is cleared.</p><button class="btn btn-outline" onclick="exportDB()">Export demo database</button></div></div>`}
function adminStudents(){return `<div class="toolbar"><input id="studentSearch" placeholder="Search name, ID, username or course" oninput="renderStudentTable()"><button class="btn btn-primary" onclick="openAddStudent()">＋ Add student</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Student</th><th>Login</th><th>Course</th><th>Attendance</th><th>Fees</th><th>Status</th><th>Actions</th></tr></thead><tbody id="studentRows"></tbody></table></div><div class="modal" id="studentModal"><div class="modal-box"><div class="modal-head"><h2 id="studentModalTitle" style="font:800 25px Manrope">Add new student</h2><button class="close" onclick="closeStudentModal()">×</button></div><form class="form" onsubmit="saveStudentFromForm(event)"><input type="hidden" id="editStudentId"><div class="form-grid"><input id="newName" placeholder="Full name" required><select id="newCourse">${depts.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-grid"><input id="newUsername" placeholder="Username (defaults to name)" required><input id="newPassword" placeholder="Password / number" required></div><div class="form-grid"><input id="newEmail" type="email" placeholder="Email" required><input id="newPhone" placeholder="Phone" required></div><div class="form-grid"><input id="newSemester" type="number" min="1" max="8" placeholder="Semester" required><input id="newAttendance" type="number" min="0" max="100" placeholder="Attendance %" required></div><div class="form-grid"><select id="newFees"><option>Paid</option><option>Due</option></select><select id="newStatus"><option>Active</option><option>Inactive</option></select></div><input id="newCampus" placeholder="Campus"><button class="btn btn-primary">Save student record</button></form></div></div>`}
function renderStudentTable(){const q=norm(document.getElementById('studentSearch')?.value);const rows=students().filter(x=>`${x.id} ${x.name} ${x.username} ${x.course}`.toLowerCase().includes(q)).map(x=>`<tr><td>${x.id}</td><td><b>${x.name}</b><br><small class="muted">${x.email}</small></td><td><b>${x.username}</b><br><small class="muted">••••••</small></td><td>${x.course}</td><td>${x.attendance}%</td><td><span class="tag ${x.fees==='Paid'?'green':'orange'}">${x.fees}</span></td><td><span class="tag ${x.status==='Active'?'green':'red'}">${x.status}</span></td><td><div class="row-actions"><button class="btn btn-ghost" onclick="openEditStudent('${x.id}')">Edit</button><button class="btn btn-ghost" onclick="toggleStudent('${x.id}')">${x.status==='Active'?'Deactivate':'Activate'}</button></div></td></tr>`).join('');const el=document.getElementById('studentRows');if(el)el.innerHTML=rows||'<tr><td colspan="8" class="empty">No students found.</td></tr>'}
function openAddStudent(){document.getElementById('studentModalTitle').textContent='Add new student';document.getElementById('editStudentId').value='';document.querySelector('#studentModal form').reset();document.getElementById('newUsername').value='';document.getElementById('newPassword').value='1001';document.getElementById('newSemester').value='1';document.getElementById('newAttendance').value='100';document.getElementById('newStatus').value='Active';document.getElementById('studentModal').classList.add('show')}
function openEditStudent(id){const x=students().find(a=>a.id===id);if(!x)return;document.getElementById('studentModalTitle').textContent='Edit student';document.getElementById('editStudentId').value=x.id;for(const [id,v] of [['newName',x.name],['newUsername',x.username],['newPassword',x.password],['newEmail',x.email],['newPhone',x.phone],['newSemester',x.semester],['newAttendance',x.attendance],['newCampus',x.campus||''],['newCourse',x.course],['newFees',x.fees],['newStatus',x.status]]){const el=document.getElementById(id);if(el)el.value=v}document.getElementById('studentModal').classList.add('show')}
function closeStudentModal(){document.getElementById('studentModal')?.classList.remove('show')}
function saveStudentFromForm(e){e.preventDefault();const id=document.getElementById('editStudentId').value,s=students();const record={id:id||`STU-${Date.now().toString().slice(-7)}`,name:document.getElementById('newName').value.trim(),username:document.getElementById('newUsername').value.trim()||document.getElementById('newName').value.trim(),password:document.getElementById('newPassword').value,course:document.getElementById('newCourse').value,semester:+document.getElementById('newSemester').value,email:document.getElementById('newEmail').value.trim(),phone:document.getElementById('newPhone').value.trim(),attendance:+document.getElementById('newAttendance').value,fees:document.getElementById('newFees').value,status:document.getElementById('newStatus').value,campus:document.getElementById('newCampus').value.trim()||'Kirhindih Campus',address:'Sasaram, Rohtas, Bihar'};const idx=s.findIndex(x=>x.id===id);if(idx>=0)s[idx]=record;else s.push(record);saveStudents(s);closeStudentModal();renderStudentTable();toast(idx>=0?'Student updated everywhere.':'Student added — the new login is active now.')}
function toggleStudent(id){const s=students(),x=s.find(a=>a.id===id);if(!x)return;x.status=x.status==='Active'?'Inactive':'Active';saveStudents(s);renderStudentTable();toast(`${x.name} is now ${x.status}.`)}
function adminTeachers(){return `<div class="toolbar"><button class="btn btn-primary" onclick="openTeacherModal()">＋ Add teacher</button></div><div class="cards">${teachers().map(x=>`<div class="card"><b>${x.id}</b><h3>${x.name}</h3><p class="muted">${x.department}</p><p><b>Username:</b> ${x.username}</p><span class="tag ${x.status==='Active'?'green':'red'}">${x.status}</span><div style="margin-top:15px"><button class="btn btn-ghost" onclick="toggleTeacher('${x.id}')">${x.status==='Active'?'Deactivate':'Activate'}</button></div></div>`).join('')}</div><div class="modal" id="teacherModal"><div class="modal-box"><div class="modal-head"><h2>Add teacher</h2><button class="close" onclick="document.getElementById('teacherModal').classList.remove('show')">×</button></div><form class="form" onsubmit="addTeacher(event)"><input id="teacherName" placeholder="Teacher name" required><div class="form-grid"><input id="teacherUser" placeholder="Username" required><input id="teacherPass" placeholder="Password" required></div><input id="teacherDept" placeholder="Department" required><button class="btn btn-primary">Create teacher account</button></form></div></div>`}
function openTeacherModal(){document.getElementById('teacherModal').classList.add('show')}function addTeacher(e){e.preventDefault();const t=teachers();t.push({id:`TEA-${String(Date.now()).slice(-4)}`,name:teacherName.value.trim(),username:teacherUser.value.trim(),password:teacherPass.value,department:teacherDept.value.trim(),status:'Active'});saveTeachers(t);document.getElementById('teacherModal').classList.remove('show');route();toast('Teacher account created.')}function toggleTeacher(id){const t=teachers(),x=t.find(a=>a.id===id);x.status=x.status==='Active'?'Inactive':'Active';saveTeachers(t);route();toast('Teacher status updated.')}
function adminNotices(){return `<div class="feature-grid"><div class="card"><h2>Publish notice</h2><form class="form" onsubmit="addNotice(event)"><input id="noticeTitle" placeholder="Notice title" required><input id="noticeDate" placeholder="Date e.g. 26 Sep 2026" required><textarea id="noticeDesc" rows="4" placeholder="Description" required></textarea><button class="btn btn-primary">Publish notice</button></form></div><div class="card"><h2>Current notices</h2><div class="notice-list">${noticesData().map((n,i)=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><b>${n[1]}</b><br><small class="muted">${n[0]}</small><button class="btn btn-ghost" style="float:right" onclick="deleteNotice(${i})">Delete</button></div>`).join('')}</div></div></div>`}
function addNotice(e){e.preventDefault();const n=noticesData();n.unshift([document.getElementById('noticeDate').value,document.getElementById('noticeTitle').value,document.getElementById('noticeDesc').value]);saveNotices(n);e.target.reset();toast('Notice published and visible on the website.');setTimeout(()=>route(),250)}function deleteNotice(i){const n=noticesData();n.splice(i,1);saveNotices(n);route();toast('Notice deleted.')}
function adminPayments(){return `<div class="dash-grid"><div class="metric"><b>₹2.84L</b><small>Demo collections</small></div><div class="metric"><b>17</b><small>Transactions today</small></div><div class="metric"><b>UPI</b><small>Most selected mode</small></div><div class="metric"><b>100%</b><small>Demo verification</small></div></div><div class="card"><h2>Payment configuration</h2><p class="muted">The checkout supports UPI, cards and net banking in demonstration mode. Live gateway credentials should be configured only on a secure backend.</p><button class="btn btn-primary" onclick="toast('Gateway configuration saved in demo mode.')">Save payment settings</button></div>`}
function adminSettings(){return `<div class="feature-grid"><div class="card"><h2>College settings</h2><form class="form" onsubmit="saveSettings(event)"><label>College name<input id="collegeName" value="${db().settings.name}"></label><label>Academic session<input id="collegeSession" value="${db().settings.session}"></label><button class="btn btn-primary">Save settings</button></form></div><div class="card"><h2>Database tools</h2><p class="muted">Export the current temporary database before clearing or moving the demo.</p><button class="btn btn-outline" onclick="exportDB()">Export JSON</button> <button class="btn btn-ghost" onclick="resetDemo()">Reset demo data</button></div></div>`}
function saveSettings(e){e.preventDefault();const d=db();d.settings.name=collegeName.value.trim()||'Shakuntalam College';d.settings.session=collegeSession.value.trim()||'2026–27';saveDB(d);toast('College settings updated across the demo.');route()}function exportDB(){const a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(db(),null,2));a.download='shakuntalam-demo-database.json';a.click()}function resetDemo(){if(confirm('Reset all demo data?')){localStorage.removeItem('shakuntalam_db');seed();route();toast('Demo database reset.')}}
function teacherContent(s){if(s==='attendance')return teacherAttendance();if(s==='students')return `<div class="card"><h2 style="font:800 23px Manrope">Assigned students</h2><p class="muted">${students().length} demo records are available for classroom management.</p>${students().slice(0,12).map(x=>`<div style="display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line)"><span><b>${x.name}</b><small class="muted"> • ${x.course}</small></span><span>${x.attendance}%</span></div>`).join('')}</div>`;return `<div class="dash-grid"><div class="metric"><b>8</b><small>Classes today</small></div><div class="metric"><b>91%</b><small>Class attendance</small></div><div class="metric"><b>12</b><small>Assignments pending</small></div><div class="metric"><b>6</b><small>Courses assigned</small></div></div><div class="feature-grid"><div class="card"><h2 style="font:800 22px Manrope">Today's classes</h2><p>09:00 • B.Ed. Pedagogy</p><p>11:00 • BCA Programming</p><p>14:00 • BBA Principles of Management</p></div><div class="card"><h2 style="font:800 22px Manrope">Quick action</h2><a class="btn btn-primary" href="#/portal/teacher/attendance">Mark attendance →</a></div></div>`}
function teacherAttendance(){const s=students().slice(0,18);return `<div class="toolbar"><select><option>Today's Class</option><option>B.Ed. • Pedagogy</option><option>BCA • Programming</option></select><button class="btn btn-primary" onclick="markAllAttendance()">Mark all present</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Student</th><th>Course</th><th>Attendance</th><th>Today</th></tr></thead><tbody>${s.map(x=>`<tr><td>${x.id}</td><td>${x.name}</td><td>${x.course}</td><td>${x.attendance}%</td><td><button class="btn btn-ghost att-btn" onclick="toggleAtt(this)">Present</button></td></tr>`).join('')}</tbody></table></div>`}function toggleAtt(b){b.textContent=b.textContent==='Present'?'Absent':'Present';b.style.background=b.textContent==='Absent'?'#ffecee':'#edf4ff';toast('Attendance updated in demo mode.')}function markAllAttendance(){document.querySelectorAll('.att-btn').forEach(b=>b.textContent='Present');toast('All students marked present.')}
function studentContent(s){const me=currentUser();const x=students().find(a=>a.id===me?.id)||me;if(s==='profile')return `<div class="card"><h2>${x.name}</h2><p class="muted">Student ID: ${x.id} • ${x.course} • Semester ${x.semester}</p><form class="form" onsubmit="saveStudentSelf(event)"><div class="form-grid"><input id="selfEmail" value="${x.email}"><input id="selfPhone" value="${x.phone}"></div><input id="selfCampus" value="${x.campus||''}"><button class="btn btn-primary">Save profile</button></form></div><div class="card" style="margin-top:18px"><h2>Change password</h2><form class="form" onsubmit="changeStudentPassword(event)"><input id="oldPass" type="password" placeholder="Current password" required><input id="newPass" type="password" placeholder="New password / number" required><button class="btn btn-primary">Update password</button></form></div>`;if(s==='fees')return `<div class="dash-grid"><div class="metric"><b>₹5,000</b><small>Current due</small></div><div class="metric"><b>₹45,000</b><small>Paid this session</small></div></div><div class="card"><h2>Fee ledger</h2><div class="notice"><div><b>Tuition Fee — Semester ${x.semester}</b><small>Demo student fee ledger</small></div><div><b>₹5,000</b><a class="btn btn-primary" href="#/payment">Pay now</a></div></div></div>`;if(s==='attendance')return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>${x.attendance>=75?'Eligible':'Review required'}</b><small>Attendance status</small></div></div><div class="card"><h2>Attendance summary</h2><p class="muted">Your current attendance is managed by teachers and reflected here automatically.</p></div>`;return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>7.8</b><small>Current CGPA</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div><div class="metric"><b>${x.fees==='Due'?'₹5K':'Paid'}</b><small>Fees</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Welcome back</span><h2>${x.name}</h2><p class="muted">${x.course} • Semester ${x.semester} • ${x.campus||'Campus'}</p><a class="btn btn-primary" href="#/portal/student/profile">Edit profile</a></div><div class="card"><span class="kicker">Fee action</span><h2>${x.fees==='Due'?'Semester fee due':'Fees up to date'}</h2><a class="btn btn-primary" href="#/payment">${x.fees==='Due'?'Pay fee →':'View payment portal →'}</a></div></div>`}
function saveStudentSelf(e){e.preventDefault();const me=currentUser(),s=students(),x=s.find(a=>a.id===me.id);x.email=selfEmail.value.trim();x.phone=selfPhone.value.trim();x.campus=selfCampus.value.trim();saveStudents(s);setSession({...me,...x});toast('Profile updated. Changes are reflected in the admin and student portal.');route()}function changeStudentPassword(e){e.preventDefault();const me=currentUser(),s=students(),x=s.find(a=>a.id===me.id);if(String(x.password)!==String(oldPass.value)){toast('Current password is incorrect.');return}x.password=newPass.value;saveStudents(s);setSession({...me,password:x.password});e.target.reset();toast('Password changed successfully.')}
function route(){const path=location.hash.replace(/^#/,'')||'/';let content='';if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/mission')content=mission();else if(path==='/departments')content=departments();else if(path.startsWith('/course/'))content=course(decodeURIComponent(path.split('/')[2]));else if(path==='/notices')content=notices();else if(path==='/facilities')content=facilities();else if(path==='/gallery')content=gallery();else if(path==='/contact')content=contact();else if(path==='/admissions')content=admissions();else if(path==='/payment')content=payment();else if(path.startsWith('/portal/')){const p=path.split('/').filter(Boolean);const sess=currentUser();const wanted=p[1]||'student';if(!sess||sess.role!==wanted){content=page('Portal login required','Please sign in with your Shakuntalam College account.',`<section class="section"><div class="container card"><h2>Secure portal</h2><p class="muted">Sign in to access this area.</p><button class="btn btn-primary" onclick="openLogin()">Open Portal Login</button></div></section>`)}else content=portal(wanted,p[2]||'dashboard')}else content=home();app.innerHTML=content+loginModal();if(path.includes('/portal/admin/students'))renderStudentTable();if(path==='/payment')payMode('upi',document.querySelector('#payTabs button'));window.scrollTo(0,0)}
function toggleMobile(){document.getElementById('mobileMenu').classList.toggle('open')}
