const _logo='shakuntalam-logo.png';
function migrateDB(){const d=db(); if(!d)return; d.applications=d.applications||[]; d.students=(d.students||[]).map((x,i)=>({...x,results:x.results||{Sem1:{Internal:60+(i%25),Theory:65+(i%20),Practical:70+(i%18),Grade:i%5===0?'A+':'A'}}})); saveDB(d)}
migrateDB();
function applications(){return db().applications||[]}
function saveApplications(x){const d=db();d.applications=x;saveDB(d)}
function teacherDepartment(t){return norm(t?.department).replace('department of ','').replace('department for ','')}
function allowedCourses(t){const d=teacherDepartment(t);if(d.includes('teacher'))return ['B.Ed.','D.El.Ed.'];if(d.includes('management'))return ['BBA','BCA'];if(d.includes('industrial'))return ['Electrician','Fitter'];return depts.slice()}
function currentTeacher(){const u=currentUser();return teachers().find(t=>t.id===u?.id)||null}

function header(){return `<div class="topbar"><div class="container"><span>Admissions 2026–27 • Shakuntalam College</span><span>📞 +91-8789036195 &nbsp; ✉️ shakuntalamteacherseducation@gmail.com</span></div></div><header class="nav"><div class="container navin"><a class="brand" href="#/"><img class="brand-logo" src="${_logo}" alt="Shakuntalam College logo"><span>SHAKUNTALAM<small>COLLEGE</small></span></a><nav class="links"><a href="#/about">About</a><div class="nav-drop"><a href="#/academics">Academics</a><div class="drop-menu"><a href="#/departments">Departments</a><a href="#/examination">Examination</a><a href="#/course/B.Ed.">B.Ed.</a><a href="#/course/D.El.Ed.">D.El.Ed.</a><a href="#/course/BBA">BBA</a><a href="#/course/BCA">BCA</a><a href="#/course/Electrician">Electrician</a><a href="#/course/Fitter">Fitter</a></div></div><div class="nav-drop"><a href="#/administration">Administration</a><div class="drop-menu"><a href="#/leadership">Leadership</a><a href="#/administration">Administration</a><a href="#/centre-cell">Centre & Cells</a></div></div><div class="nav-drop"><a href="#/admissions">Admission</a><div class="drop-menu"><a href="#/admissions">Apply Online</a><a href="#/admission-status">Admission Status</a><a href="#/payment">Fee Payment</a></div></div><div class="nav-drop"><a href="#/students-zone">Students Zone</a><div class="drop-menu"><a href="#/notices">Notice</a><a href="#/examination">Examination</a><a href="#/student-welfare">Student Welfare</a><a href="#/portal/student">Student Portal</a></div></div><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/contact">Contact</a></nav><div class="nav-actions"><a class="btn btn-ghost" href="#/admissions">Apply Now</a><button class="btn btn-primary" onclick="openLogin()">Portal Login</button><button class="hamb" onclick="toggleMobile()">☰</button></div></div><div class="mobile-menu" id="mobileMenu"><a href="#/about">About</a><a href="#/admissions">Admission</a><a href="#/administration">Administration</a><a href="#/academics">Academics</a><a href="#/departments">Departments</a><a href="#/centre-cell">Centre & Cells</a><a href="#/examination">Examination</a><a href="#/notices">Notice</a><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/students-zone">Students Zone</a><a href="#/contact">Contact</a></div></header>`}
function footer(){return `<footer class="footer"><div class="container footer-grid"><div><div class="brand"><img class="brand-logo" src="${_logo}" alt="Shakuntalam College logo"><span>SHAKUNTALAM<small>COLLEGE</small></span></div><p>Meaningful learning, professional preparation and student development across teacher education, management and industrial training.</p><div class="socials"><a href="https://www.facebook.com/" target="_blank">Facebook</a><a href="https://www.instagram.com/" target="_blank">Instagram</a><a href="https://www.youtube.com/" target="_blank">YouTube</a></div></div><div><h3>Useful Links</h3><a href="#/about">About College</a><br><a href="#/mission">Vision, Mission & Values</a><br><a href="#/leadership">Leadership</a><br><a href="#/faculty">Faculty</a><br><a href="#/student-welfare">Student Welfare</a><br><a href="#/notices">Notices</a></div><div><h3>Academic & Student</h3><a href="#/admissions">Admission</a><br><a href="#/academics">Academics</a><br><a href="#/departments">Departments</a><br><a href="#/examination">Examination</a><br><a href="#/portal/student">Student Portal</a><br><a href="#/portal/teacher">Faculty Portal</a></div><div><h3>Contact</h3><p>Kirhindih, Kumhau Station Road<br>Sheosagar, Sasaram, Rohtas, Bihar 821115</p><p>City Campus, Bouliya More<br>Jagdeo Path, Sasaram</p><p><b>+91-9470014145</b><br><b>+91-8789036195</b></p></div></div><div class="container map-wrap"><div><h3>Find Shakuntalam College</h3><p class="muted">Kirhindih Campus • Sheosagar, Sasaram, Rohtas, Bihar</p></div><iframe title="Shakuntalam College location" src="https://www.google.com/maps?q=Shakuntalam%20Institute%20of%20Teachers%20Education%20Sasaram%20Bihar&output=embed" loading="lazy"></iframe></div><div class="container copy"><span>© 2026 Shakuntalam College. Website demo.</span><span>Admission • Academics • Administration • Student Services</span></div></footer>`}
function home(){return layout(`<main><section class="hero hero-brand"><div class="container hero-grid"><div><span class="eyebrow">✦ SHAKUNTALAM COLLEGE • 2026–27</span><h1>Education with <span>purpose.</span></h1><p>Explore academic programs, admissions, campus life, student services and a connected college administration experience.</p><div class="hero-actions"><a class="btn btn-primary" href="#/admissions">Apply for Admission →</a><a class="btn btn-outline" href="#/academics">Explore Academics</a></div><div class="hero-links"><a href="#/notices">Latest Notices</a><a href="#/examination">Examination</a><a href="#/students-zone">Students Zone</a></div></div><div class="hero-card"><img src="${img.campus}" alt="Shakuntalam College campus"><div style="display:flex;justify-content:space-between;padding:13px 4px 0;font-size:12px"><span>Learning • Practice • Progress</span><b>ESTD 2009</b></div></div></div></section><div class="container floating"><div class="stats"><div class="stat"><b>06</b><span>Academic programs</span></div><div class="stat"><b>03</b><span>Departments</span></div><div class="stat"><b>${students().length}</b><span>Student records</span></div><div class="stat"><b>02</b><span>Major campus locations</span></div></div></div><section class="section menu-section"><div class="container"><div class="section-head"><div><span class="kicker">Explore Shakuntalam</span><h2>Everything you need, in one place.</h2></div><p>Quick access to academic, administrative, student and campus information.</p></div><div class="mega-links">${[['Admission','Apply online, admission status and fee payment.','/admissions'],['Administration','Leadership, administration and institutional information.','/administration'],['Academics','Programs, departments, examination and faculty.','/academics'],['Department','Explore all academic departments and courses.','/departments'],['Centre & Cell','Student welfare, grievance, anti-ragging and support cells.','/centre-cell'],['Examination','Schedules, results, academic assessment and notices.','/examination'],['Notice','Latest admission, academic and examination announcements.','/notices'],['Infrastructure','Library, labs, ICT, sports, seminar hall and campus facilities.','/infrastructure'],['Events','College events, workshops, seminars and activities.','/events'],['Students Zone','Student welfare, portal, fees, results and resources.','/students-zone']].map((x,i)=>`<a class="mega-link" href="#${x[2]}"><span class="mega-no">${String(i+1).padStart(2,'0')}</span><div><b>${x[0]}</b><small>${x[1]}</small></div><span>↗</span></a>`).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Academic portfolio</span><h2>Programs built for the next step.</h2></div><a class="btn btn-outline" href="#/departments">View all programs →</a></div><div class="cards">${courses.map(courseCard).join('')}</div></div></section><section class="section dark-section"><div class="container mission"><div><span class="kicker">Vision • Mission • Values</span><h2>Knowledge, practical skills and responsible citizenship.</h2><p class="muted" style="line-height:1.8">The institution's public materials highlight teacher education, practical learning, modern facilities, professional development and student support. This website brings those areas together in one information architecture.</p><a class="btn btn-primary" href="#/mission">Read our values →</a></div><div class="card"><div class="quote">“Education is most powerful when learning becomes confidence, skill and responsible action.”</div><p class="muted">A website presentation statement for the demo.</p></div></div></section><section class="section"><div class="container feature-grid"><div><span class="kicker">Latest updates</span><h2>Notice board</h2><div class="notice-list">${noticesData().slice(0,5).map(notice).join('')}</div><a class="btn btn-outline" href="#/notices" style="margin-top:16px">View all notices</a></div><div class="card admission-card"><span class="kicker">Admissions 2026–27</span><h2>Start your application.</h2><p class="muted">Submit an online application and it will appear in the administration portal for review in this demo.</p><a class="btn btn-primary" href="#/admissions">Apply online →</a><hr><p><b>Need help?</b><br><span class="muted">+91-9470014145 • +91-8789036195</span></p></div></div></section><section class="section social-section"><div class="container"><div class="section-head"><div><span class="kicker">Stay connected</span><h2>Follow campus updates.</h2></div><p>Use these social links for admissions updates, events, announcements and student activities.</p></div><div class="social-grid"><a href="https://www.facebook.com/" target="_blank"><b>Facebook</b><span>College updates & announcements →</span></a><a href="https://www.instagram.com/" target="_blank"><b>Instagram</b><span>Campus life & events →</span></a><a href="https://www.youtube.com/" target="_blank"><b>YouTube</b><span>Lectures, events & media →</span></a></div></div></section></main>`)}
function submitAdmission(e){e.preventDefault();const id='APP-'+Date.now().toString().slice(-7);const a=applications();a.unshift({id,name:adName.value.trim(),phone:adPhone.value.trim(),email:adEmail.value.trim(),course:adCourse.value,address:adAddress.value.trim(),date:new Date().toLocaleString('en-IN'),status:'New'});saveApplications(a);toast(`Application ${id} submitted. It is now visible in Admin → Admissions.`);e.target.reset();location.hash='/admission-status'}
function admissionStatus(){return page('Admission Status','Track the application submitted from this browser in the demo.',`<section class="section"><div class="container"><div class="card"><h2>Application tracking</h2><p class="muted">In this demo, applications are stored in the browser's temporary database and can be reviewed by the administrator.</p>${applications().slice(0,1).map(a=>`<div class="notice"><div><b>${a.id} • ${a.name}</b><small>${a.course} • ${a.date}</small></div><span class="tag orange">${a.status}</span></div>`).join('')||'<div class="empty">No application submitted in this browser yet.</div>'}</div></div></section>`)}
function academics(){const items=[['Academic Programs','B.Ed., D.El.Ed., BBA, BCA, Electrician and Fitter provide pathways across teacher education, management, computing and industrial training.','Explore departments →','/departments'],['Teaching & Learning','Classroom teaching is complemented by practical work, workshops, internships, projects, seminars and guided study.'],['Assessment','Students can follow internal assessment, theory, practical and semester result information through the portal demo.'],['Academic Support','Notices, faculty information, student welfare resources, examination updates and digital student services are available through the website.','Contact Us →','/contact']];return page('Academics','Programs, teaching, assessment and academic support across the college.',`<section class="section"><div class="container academic-info-grid">${items.map((x,i)=>`<article class="card academic-info-card numbered-card"><span class="leader-number">0${i+1}</span><h2>${x[0]}</h2><p class="muted">${x[1]}</p>${x[2]?`<a class="btn btn-primary" href="#${x[3]}">${x[2]}</a>`:''}</article>`).join('')}</div></section>`)}
function administration(){return page('Administration','Institutional leadership, offices and administrative services.',`<section class="section"><div class="container leadership-admin-grid"><article class="card leadership-admin-card numbered-card"><span class="leader-number">01</span><span class="kicker">Institutional leadership</span><h2>Leadership</h2><p class="muted">Read messages from the Secretary and Principal, and learn about the Governing Body guiding the institution.</p><a class="btn btn-primary" href="#/leadership">Explore leadership →</a></article><article class="card leadership-admin-card numbered-card"><span class="leader-number">02</span><span class="kicker">College services</span><h2>Office Services</h2><p class="muted">Admissions, student records, fees, notices, faculty records and portal access are coordinated through administrative workflows.</p></article><article class="card leadership-admin-card numbered-card"><span class="leader-number">03</span><span class="kicker">Institutional information</span><h2>Transparency</h2><p class="muted">Policies, notices and student-support information can be published from the administration area.</p></article></div></section>`)}
function leadership(){return page('Leadership','Messages and information from the leaders of Shakuntalam College.',`<section class="section leadership-hub"><div class="container"><div class="section-head leadership-section-head"><div><span class="kicker">Institutional leadership</span><h2>Guidance, purpose and shared responsibility.</h2></div><p>Read leadership messages and learn about the society that supports the college.</p></div><div class="leadership-hub-grid"><a class="card leader-card" href="#/leadership/governing-body"><span class="leader-number">01</span><span class="kicker">Devi Shakuntalam Pratisthan</span><h3>Governing Body</h3><p>Learn about the society’s history, institutions and commitment to education.</p><span class="leader-action">Explore Governing Body →</span></a><a class="card leader-card" href="#/leadership/founder"><span class="leader-number">02</span><span class="kicker">Message from the Founder</span><h3>Founder Desk</h3><p>Read a message from the Society and Institute Founder.</p><span class="leader-action">Visit Founder Desk →</span></a><a class="card leader-card" href="#/leadership/secretary"><span class="leader-number">03</span><span class="kicker">Message from the Secretary</span><h3>Secretary Desk</h3><p>Read the Secretary’s message to students, faculty and the college community.</p><span class="leader-action">Visit Secretary Desk →</span></a><a class="card leader-card" href="#/leadership/principal"><span class="leader-number">04</span><span class="kicker">Academic leadership</span><h3>Principal Desk</h3><p>Explore the Principal’s welcome and the college’s approach to teaching and learning.</p><span class="leader-action">Visit Principal Desk →</span></a></div></div></section>`)}
function leadershipDesk(which){const desks={founder:{title:'Founder Desk',kicker:'Message from the Founder',greeting:'Dear Students, Faculty and Well-wishers,',paragraphs:[`It gives me great pleasure to welcome every student, faculty member, staff member and well-wisher to the Shakuntalam community. Since Devi Shakuntalam Pratisthan was founded in 2009, our purpose has been to make meaningful education and practical preparation accessible to learners.`,`With this purpose, we established institutions that support teacher education, management, computing and industrial training. Each institution reflects the same belief: knowledge grows stronger when it is joined with practice, discipline and care.`,`Our faculty members guide students with dedication and help them develop confidence, responsibility and respect for others. I encourage every student to approach learning with curiosity, make full use of each opportunity and remain committed to personal growth.`,`Education calls upon us to work together, share ideas and prepare thoughtfully for the changing needs of society. The progress of our institutions is made possible by the efforts of our teachers, staff, students, families and partners.`,`I extend my sincere appreciation to all who contribute to this shared journey and support the college community. May Shakuntalam continue to serve learners with integrity, compassion and a lasting commitment to opportunity.`],name:'Siyaram Singh',role:'Society and Institute Founder'},secretary:{title:'Secretary Desk',kicker:'A message from the Secretary',greeting:'Dear Esteemed Faculty, Staff and Students,',paragraphs:[`It is with great pleasure and pride that I address you as Secretary of our college. As we begin another academic year, I look forward to the opportunities ahead. Shakuntalam College is committed to nurturing future educators who will shape the minds and futures of generations to come. Education is a calling and a responsibility, and we strive for excellence in every part of this work.`,`Our faculty are the backbone of the institution. Their experience, dedication and passion create an environment where knowledge flourishes and future educators are inspired as well as prepared.`,`To our students, welcome. Your journey here is about more than acquiring knowledge: it is also a time for personal growth, character building and developing the skills to become exceptional educators. Make the most of every opportunity to learn and serve.`,`As a college community, let us continue to foster collaboration, innovation and inclusion. To our stakeholders and partners, thank you for your continued support of our mission to provide quality education and prepare educators who are both competent and compassionate.`,`I am confident that, together, we will uphold our commitment to educational innovation and create a positive learning environment. I wish you all a successful and enriching academic year.`],name:'Anil Kumar Singh',role:'Secretary, Devi Shakuntalam Pratisthan'},principal:{title:'Principal Desk',kicker:'A welcome from the Principal',greeting:'Dear Students, Faculty, Staff and Esteemed Guests,',paragraphs:[`It is my pleasure to welcome you to another academic year at Shakuntalam Institute of Teachers Education. Our shared commitment is to foster excellence in education and prepare thoughtful, capable and compassionate educators.`,`Our mission goes beyond traditional academic study. We work to create a learning environment that builds knowledge, a passion for teaching and a strong sense of social responsibility. We want our students to become innovative and effective educators who contribute meaningfully to society.`,`Our experienced faculty bring academic knowledge and practical insight into the classroom. Through theory, practice and guided learning, we aim to help every student develop the skills needed for a changing educational landscape.`,`I encourage you to take an active part in your studies, collaborate with peers and make use of the learning resources and activities available to you. The college community is strengthened by curiosity, mutual support and the lifelong connections formed here.`,`I look forward to seeing each of you grow during your time at Shakuntalam Institute of Teachers Education. May the year ahead be fulfilling and enriching.`],name:'Principal',role:'Shakuntalam Institute of Teachers Education'},'governing-body':{title:'Governing Body',kicker:'Devi Shakuntalam Pratisthan',greeting:'A commitment to educational opportunity since 2009',paragraphs:[`Devi Shakuntalam Pratisthan was founded in 2009 and registered under the Societies Registration Act XXI of 1860 (registration number 2037/2009–10). The society works to expand access to quality education and encourage innovation in learning.`,`The society established Shakuntalam Industrial Training Institute in 2009. Its Electrician and Fitter trades provide practical, technical training and are affiliated with NCVT, Government of India (registration number 6/4/98/2010-TC).`,`In 2015, the society established Shakuntalam Institute of Teachers Education at Kirhindih, Sasaram. The institute’s teacher-education programs include B.Ed., affiliated with VKSU, Ara, and D.El.Ed., affiliated with Bihar School Examination Board, Patna. The institute is recognized by NCTE, ERC Bhubaneswar.`,`The society is committed to well-equipped classrooms, a multipurpose hall, indoor and outdoor activities, and the balanced development of students’ intellectual, personal and social capacities. Its broader aim is to support quality education and create a positive learning environment for the community.`],name:'Devi Shakuntalam Pratisthan',role:'Founded 2009 · Registration No. 2037/2009–10'}};const d=desks[which];if(!d)return leadership();const uploaded=(siteConfig().leadershipImages||{})[which]||'';const portrait=uploaded||(which==='founder'?'assets/founder-portrait-default.png':which==='secretary'?'assets/secretary-portrait-default.png':'');const portraitBlock=['founder','secretary'].includes(which)?portrait?`<figure class="leadership-portrait"><img src="${portrait}" alt="${d.name}"></figure>`:`<figure class="leadership-portrait is-placeholder" aria-label="${d.name} portrait will appear here"><span>AS</span></figure>`:'';const logoBlock=which==='governing-body'?`<img class="leadership-institution-logo" src="${_finalLogo}" alt="Shakuntalam College official logo">`:'';return page(d.title,d.kicker,`<section class="section leadership-message-section"><div class="container"><a class="back-link" href="#/leadership">← Leadership</a><article class="leadership-message card"><span class="kicker">${d.kicker}</span><h2>${d.greeting}</h2>${d.paragraphs.map(p=>`<p>${p}</p>`).join('')}<div class="leader-signoff"><span>Warm regards,</span>${logoBlock}${portraitBlock}<strong>${d.name}</strong><small>${d.role}</small></div></article></div></section>`)}
function centreCell(){return infoPage('Centre & Cells','Student support, safety, grievance and campus committees.',[['Anti-Ragging Cell','The college promotes a safe, respectful environment for every learner.<br>This cell shares awareness about ragging and how to seek support.<br>Students can approach a trusted faculty member or the college office.<br>Ask the administration for current contacts and reporting guidance.'],['Grievance Redressal Cell','A channel for student and staff concerns about college life.<br>Raise questions about academics, facilities, services or support.<br>Share relevant details so the college can understand the matter.<br>Contact the office for current submission and response information.'],['Internal Complaints Committee','The committee supports an inclusive and respectful campus environment.<br>Students and staff can seek information about concerns within its remit.<br>The college office can guide you to the appropriate institutional process.<br>Ask the administration for current committee contacts and procedures.'],['Anti-Sexual Harassment Cell','The college promotes dignity, safety and respectful conduct for all.<br>This cell shares awareness and support information for harassment concerns.<br>Students and staff can seek guidance through the college administration.<br>Contact the office for current support resources and reporting steps.'],['Student Welfare','Student welfare connects learners with scholarships, notices and support.<br>Students can ask about counselling and available campus resources.<br>Faculty and staff can help direct students to the right service.<br>Contact the college office for current details and eligibility.']])}
function examination(){return infoPage('Examination','Schedules, assessment, results and examination resources.',[['Examination Notices','Publish internal and semester examination schedules from the notice system.'],['Results','Students can view published results in the student portal while teachers can enter department-specific marks.'],['Academic Records','A future production ERP can connect marks, attendance, admit cards, certificates and transcripts to a secure database.']])}
function infrastructure(){return infoPage('Infrastructure','Facilities that support classroom, practical and student life.',facilitiesSeed.map(x=>[x[1],x[2]]))}
function events(){return infoPage('Events','College activities, workshops, seminars and student engagement.',[['Orientation','Academic-year orientation and induction programs.'],['Workshops','Skill development, teaching practice, entrepreneurship and technology workshops.'],['Seminars & Guest Lectures','Academic and professional sessions for students and faculty.'],['Cultural & Sports','Student activities that build teamwork, creativity and wellbeing.']])}
function studentsZone(){const items=[['Student Portal','Access profile, attendance, fees, results and notices.',`<button type="button" class="btn btn-primary" onclick="openLogin()">Student Portal Login →</button>`],['Student Welfare','Anti-ragging, grievance, ICC and student-support resources.',`<a class="btn btn-primary" href="#/student-welfare">Explore Student Welfare →</a>`],['Examination','Schedules and published results.',`<a class="btn btn-primary" href="#/examination">Open Examination Page →</a>`],['Fee Payment','Demo UPI, card and net-banking payment interface.']];return page('Students Zone','Everything students need during their academic journey.',`<section class="section students-zone-section"><div class="container academic-info-grid">${items.map((x,i)=>`<article class="card academic-info-card numbered-card"><span class="leader-number">0${i+1}</span><h2>${x[0]}</h2><p class="muted">${x[1]}</p>${x[2]||''}</article>`).join('')}</div></section>`)}
function faculty(){return infoPage('Faculty','Faculty and teaching resources.',[['B.Ed. & D.El.Ed.','Faculty listings can be maintained by administration for teacher education programs.'],['BBA & BCA','Management and computing faculty can be organized by course and department.'],['Industrial Training','Trade instructors can be organized under Electrician and Fitter.']])}
function studentWelfare(){return centreCell()}
function infoPage(title,sub,sections){return page(title,sub,`<section class="section"><div class="container info-long">${sections.map((x,i)=>`<article class="card info-block numbered-card"><span class="leader-number">${String(i+1).padStart(2,'0')}</span><h2>${x[0]}</h2><p class="muted">${x[1]}</p></article>`).join('')}</div></section>`)}

function adminContent(s){if(s==='students')return adminStudents();if(s==='teachers')return adminTeachers();if(s==='notices')return adminNotices();if(s==='payments')return adminPayments();if(s==='admissions')return adminAdmissions();if(s==='settings')return adminSettings();return adminDashboard()}
function adminDashboard(){const s=students();return `<div class="dash-grid"><div class="metric"><b>${s.length}</b><small>Total students</small></div><div class="metric"><b>${s.filter(x=>x.status==='Active').length}</b><small>Active students</small></div><div class="metric"><b>${applications().filter(x=>x.status==='New').length}</b><small>New admissions</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div></div><div class="admin-grid"><div class="card"><span class="kicker">Control centre</span><h2>College administration</h2><p class="muted">Manage students, teachers, admissions, attendance, results, notices, fees and website settings from one place.</p><div class="quick-grid"><a class="btn btn-primary" href="#/portal/admin/students">Manage students</a><a class="btn btn-ghost" href="#/portal/admin/admissions">Admission applications (${applications().filter(x=>x.status==='New').length})</a><a class="btn btn-ghost" href="#/portal/admin/teachers">Manage teachers</a><a class="btn btn-ghost" href="#/portal/admin/notices">Manage notices</a><a class="btn btn-ghost" href="#/portal/admin/settings">College settings</a></div></div><div class="card"><span class="kicker">Temporary database</span><h3>All demo changes use the same browser database</h3><p class="muted">Applications, students, teachers, notices and results stay synchronized across the public pages and portals until browser storage is cleared.</p><button class="btn btn-outline" onclick="exportDB()">Export database</button></div></div>`}
function adminAdmissions(){return `<div class="toolbar"><button class="btn btn-outline" onclick="exportApplications()">Export applications</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Application</th><th>Applicant</th><th>Course</th><th>Contact</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody>${applications().map(a=>`<tr><td><b>${a.id}</b></td><td>${a.name}<br><small class="muted">${a.address||''}</small></td><td>${a.course}</td><td>${a.phone}<br>${a.email}</td><td>${a.date}</td><td><span class="tag ${a.status==='New'?'orange':'green'}">${a.status}</span></td><td><button class="btn btn-primary" ${a.status==='Converted'?'disabled':''} onclick="convertApplication('${a.id}')">${a.status==='Converted'?'Converted':'Create student'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No applications yet.</td></tr>'}</tbody></table></div>`}
function convertApplication(id){const a=applications().find(x=>x.id===id);if(!a||a.status==='Converted')return;const s=students();const password=String(1000+s.length+1);s.push({id:`STU-${Date.now().toString().slice(-7)}`,name:a.name,username:a.name,password,course:a.course,semester:1,email:a.email,phone:a.phone,attendance:0,fees:'Due',status:'Active',campus:(a.course==='BBA'||a.course==='BCA')?'City Campus':'Kirhindih Campus',address:a.address||'Sasaram, Rohtas, Bihar',results:{Sem1:{Internal:0,Theory:0,Practical:0,Grade:'Pending'}}});saveStudents(s);const arr=applications();const x=arr.find(z=>z.id===id);if(x)x.status='Converted';saveApplications(arr);toast(`Student account created. Username: ${a.name} • Password: ${password}`);route()}
function exportApplications(){const a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(applications(),null,2));a.download='shakuntalam-admission-applications.json';a.click()}
function teacherContent(s){const t=currentTeacher(),allowed=allowedCourses(t),mine=students().filter(x=>allowed.includes(x.course));if(s==='attendance')return teacherAttendance();if(s==='students')return `<div class="card"><h2>My department students</h2><p class="muted">Only students from <b>${t?.department||'your department'}</b> are visible.</p><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Course</th><th>Semester</th><th>Attendance</th><th>Status</th></tr></thead><tbody>${mine.map(x=>`<tr><td>${x.name}</td><td>${x.course}</td><td>${x.semester}</td><td>${x.attendance}%</td><td>${x.status}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No students assigned.</td></tr>'}</tbody></table></div></div>`;if(s==='results')return teacherResults(mine);return `<div class="dash-grid"><div class="metric"><b>${mine.length}</b><small>Department students</small></div><div class="metric"><b>${allowed.length}</b><small>Assigned courses</small></div><div class="metric"><b>${Math.round(mine.reduce((a,x)=>a+x.attendance,0)/(mine.length||1))}%</b><small>Department attendance</small></div><div class="metric"><b>${applications().filter(a=>allowed.includes(a.course)&&a.status==='New').length}</b><small>New applicants</small></div></div><div class="feature-grid"><div class="card"><h2>Department work</h2><p>Review attendance and student progress only for your assigned department.</p><a class="btn btn-primary" href="#/portal/teacher/attendance">Manage attendance →</a></div><div class="card"><h2>Results</h2><p>Enter internal, theory and practical marks for your department students.</p><a class="btn btn-outline" href="#/portal/teacher/results">Manage results →</a></div></div>`}
function teacherAttendance(){const t=currentTeacher(),allowed=allowedCourses(t),s=students().filter(x=>allowed.includes(x.course));return `<div class="toolbar"><span class="pill">${t?.department||'Department'}</span><button class="btn btn-primary" onclick="markAllAttendance()">Mark all present</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Student</th><th>Course</th><th>Attendance</th><th>Today</th></tr></thead><tbody>${s.map(x=>`<tr><td>${x.id}</td><td>${x.name}</td><td>${x.course}</td><td>${x.attendance}%</td><td><button class="btn btn-ghost att-btn" onclick="toggleAtt(this,'${x.id}')">Present</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No students in your department.</td></tr>'}</tbody></table></div>`}
function toggleAtt(b,id){const s=students(),x=s.find(a=>a.id===id);if(x){x.attendance=Math.min(100,Math.round(x.attendance+1));saveStudents(s)}b.textContent=b.textContent==='Present'?'Absent':'Present';b.style.background=b.textContent==='Absent'?'#ffecee':'#edf4ff';toast('Attendance saved to the temporary database.')}
function markAllAttendance(){const t=currentTeacher(),allowed=allowedCourses(t),s=students();s.filter(x=>allowed.includes(x.course)).forEach(x=>x.attendance=Math.min(100,Math.round(x.attendance+1)));saveStudents(s);route();toast('Department attendance updated.')}
function teacherResults(mine){return `<div class="card"><h2>Result management</h2><p class="muted">Only students from your department are listed. Enter demo marks and publish them to the student portal.</p><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Course</th><th>Internal</th><th>Theory</th><th>Practical</th><th>Grade</th><th></th></tr></thead><tbody>${mine.map(x=>{const r=x.results?.Sem1||{Internal:0,Theory:0,Practical:0,Grade:'Pending'};return `<tr><td>${x.name}</td><td>${x.course}</td><td><input class="mini-input" id="ri_${x.id}" value="${r.Internal}"></td><td><input class="mini-input" id="rt_${x.id}" value="${r.Theory}"></td><td><input class="mini-input" id="rp_${x.id}" value="${r.Practical}"></td><td>${r.Grade}</td><td><button class="btn btn-primary" onclick="saveResult('${x.id}')">Save</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No students in your department.</td></tr>'}</tbody></table></div></div>`}
function saveResult(id){const t=currentTeacher(),allowed=allowedCourses(t),s=students(),x=s.find(a=>a.id===id);if(!x||!allowed.includes(x.course)){toast('You can only edit results for your department.');return}const r={Internal:+document.getElementById('ri_'+id).value,Theory:+document.getElementById('rt_'+id).value,Practical:+document.getElementById('rp_'+id).value};const avg=(r.Internal+r.Theory+r.Practical)/3;r.Grade=avg>=90?'A+':avg>=80?'A':avg>=70?'B+':avg>=60?'B':avg>=50?'C':'Needs Improvement';x.results=x.results||{};x.results.Sem1=r;saveStudents(s);toast('Result published to the student portal.');route()}
function studentContent(s){const me=currentUser();const x=students().find(a=>a.id===me?.id)||me;if(s==='profile')return `<div class="card"><h2>${x.name}</h2><p class="muted">Student ID: ${x.id} • ${x.course} • Semester ${x.semester}</p><form class="form" onsubmit="saveStudentSelf(event)"><div class="form-grid"><input id="selfEmail" value="${x.email}"><input id="selfPhone" value="${x.phone}"></div><input id="selfCampus" value="${x.campus||''}"><button class="btn btn-primary">Save profile</button></form></div><div class="card" style="margin-top:18px"><h2>Change password</h2><form class="form" onsubmit="changeStudentPassword(event)"><input id="oldPass" type="password" placeholder="Current password" required><input id="newPass" type="password" placeholder="New password / number" required><button class="btn btn-primary">Update password</button></form></div>`;if(s==='fees')return `<div class="dash-grid"><div class="metric"><b>₹5,000</b><small>Current due</small></div><div class="metric"><b>₹45,000</b><small>Paid this session</small></div></div><div class="card"><h2>Fee ledger</h2><div class="notice"><div><b>Tuition Fee — Semester ${x.semester}</b><small>Demo student fee ledger</small></div><div><b>₹5,000</b><a class="btn btn-primary" href="#/payment">Pay now</a></div></div></div>`;if(s==='attendance')return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>${x.attendance>=75?'Eligible':'Review required'}</b><small>Attendance status</small></div></div><div class="card"><h2>Attendance summary</h2><p class="muted">Your current attendance is managed by teachers and reflected here automatically.</p></div>`;if(s==='results'){const r=x.results?.Sem1||{Internal:0,Theory:0,Practical:0,Grade:'Pending'};return `<div class="dash-grid"><div class="metric"><b>${r.Internal}</b><small>Internal</small></div><div class="metric"><b>${r.Theory}</b><small>Theory</small></div><div class="metric"><b>${r.Practical}</b><small>Practical</small></div><div class="metric"><b>${r.Grade}</b><small>Grade</small></div></div><div class="card"><h2>Semester 1 Result</h2><p class="muted">Published results are updated by your department teacher.</p></div>`}return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>7.8</b><small>Current CGPA</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div><div class="metric"><b>${x.fees==='Due'?'₹5K':'Paid'}</b><small>Fees</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Welcome back</span><h2>${x.name}</h2><p class="muted">${x.course} • Semester ${x.semester} • ${x.campus||'Campus'}</p><a class="btn btn-primary" href="#/portal/student/profile">Edit profile</a></div><div class="card"><span class="kicker">Result</span><h2>View your result</h2><a class="btn btn-outline" href="#/portal/student/results">Open result →</a></div></div>`}
function infoPage(title,sub,sections){return page(title,sub,`<section class="section"><div class="container info-long">${sections.map((x,i)=>`<article class="card info-block numbered-card"><span class="leader-number">${String(i+1).padStart(2,'0')}</span><h2>${x[0]}</h2><p class="muted">${x[1]}</p></article>`).join('')}</div></section>`)}
function route(){const path=location.hash.replace(/^#/,'')||'/';let content='';if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/mission')content=mission();else if(path==='/departments')content=departments();else if(path==='/academics')content=academics();else if(path==='/administration')content=administration();else if(path==='/leadership')content=leadership();else if(path==='/centre-cell')content=centreCell();else if(path==='/examination')content=examination();else if(path==='/infrastructure')content=infrastructure();else if(path==='/events')content=events();else if(path==='/students-zone')content=studentsZone();else if(path==='/faculty')content=faculty();else if(path==='/student-welfare')content=studentWelfare();else if(path==='/admission-status')content=admissionStatus();else if(path.startsWith('/course/'))content=course(decodeURIComponent(path.split('/')[2]));else if(path==='/notices')content=notices();else if(path==='/facilities')content=facilities();else if(path==='/gallery')content=gallery();else if(path==='/contact')content=contact();else if(path==='/admissions')content=admissions();else if(path==='/payment')content=payment();else if(path.startsWith('/portal/')){const p=path.split('/').filter(Boolean);const sess=currentUser();const wanted=p[1]||'student';if(!sess||sess.role!==wanted){content=page('Portal login required','Please sign in with your Shakuntalam College account.',`<section class="section"><div class="container card"><h2>Secure portal</h2><p class="muted">Sign in to access this area.</p><button class="btn btn-primary" onclick="openLogin()">Open Portal Login</button></div></section>`)}else content=portal(wanted,p[2]||'dashboard')}else content=home();app.innerHTML=content+loginModal();if(path.includes('/portal/admin/students'))renderStudentTable();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);route();


/* ===== SHAKUNTALAM COLLEGE FINAL VISUAL + ADMIN EXTENSIONS ===== */
function ensureFinalSchema(){
  const d=db()||{};
  if(!d.admins){d.admins=[{id:'ADM-001',name:'Super Administrator',username:'admin',password:'admin123',status:'Active',permissions:['all']}];}
  if(d.admin && d.admins.length===1 && d.admin.username && d.admin.username!=='admin') d.admins[0]={id:'ADM-001',name:'Super Administrator',username:d.admin.username,password:d.admin.password,status:'Active',permissions:['all']};
  delete d.admin;
  if(!d.events){d.events=[
    {id:'EVT-001',title:'Freshers & Orientation Programme',date:'2026-07-15',location:'College Campus',description:'Welcome and orientation programme for new students.',image:img.campus},
    {id:'EVT-002',title:'Teacher Education Seminar',date:'2026-09-12',location:'Seminar Hall',description:'Academic seminar and professional development session.',image:img.class}
  ];}
  saveDB(d);
}
ensureFinalSchema();
function admins(){return db().admins||[]}
function saveAdmins(x){const d=db();d.admins=x;saveDB(d)}
function eventsData(){return db().events||[]}
function saveEvents(x){const d=db();d.events=x;saveDB(d)}
function activeAdmin(){const u=currentUser();return admins().find(a=>a.id===u?.id)||null}
function header(){return `<div class="topbar"><div class="container topbar-inner"><span>ADMISSIONS 2026–27</span><span>+91 9470014145 · +91 8789036195 · shakuntalamteacherseducation@gmail.com</span></div></div><header class="nav"><div class="container navin"><a class="brand brand-lockup" href="#/"><img class="brand-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><span class="brand-copy"><strong>SHAKUNTALAM COLLEGE</strong><small>DEVI SHAKUNTALAM PRATHISTHAN</small><em>ESTD 2009</em></span></a><nav class="links"><a href="#/admissions">Admission</a><a href="#/administration">Administration</a><a href="#/academics">Academics</a><a href="#/departments">Department</a><a href="#/centre-cell">Centre &amp; Cell</a><a href="#/examination">Examination</a><a href="#/notices">Notice</a><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/students-zone">Students Zone</a></nav><div class="nav-actions"><button class="btn btn-primary" onclick="openLogin()">Portal Login</button><button class="hamb" onclick="toggleMobile()">☰</button></div></div><div class="mobile-menu" id="mobileMenu"><a href="#/admissions">Admission</a><a href="#/administration">Administration</a><a href="#/academics">Academics</a><a href="#/departments">Department</a><a href="#/centre-cell">Centre &amp; Cell</a><a href="#/examination">Examination</a><a href="#/notices">Notice</a><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/students-zone">Students Zone</a></div></header>`}
function footer(){return `<footer class="footer"><div class="container footer-top"><div class="footer-brand"><img class="footer-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><div><div class="footer-title">SHAKUNTALAM COLLEGE</div><div class="footer-sub">DEVI SHAKUNTALAM PRATHISTHAN</div><div class="footer-estd">ESTD 2009</div></div><p>Education, professional development and student opportunity under one academic community.</p><div class="socials"><a href="#">Facebook</a><a href="#">Instagram</a><a href="#">YouTube</a><a href="#">WhatsApp</a></div></div><div><h3>Quick Links</h3><a href="#/about">About College</a><a href="#/mission">Mission &amp; Values</a><a href="#/faculty">Faculty</a><a href="#/notices">Notice Board</a><a href="#/events">Events</a></div><div><h3>Student Services</h3><a href="#/admissions">Admissions</a><a href="#/payment">Fee Payment</a><a href="#/students-zone">Students Zone</a><a href="#/portal/student">Student Portal</a><a href="#/portal/teacher">Teacher Portal</a></div><div><h3>Contact</h3><p>Kirhindih, Kumhau Station Road<br>Sheosagar, Sasaram, Rohtas, Bihar 821115</p><p>City Campus, Bauliya More<br>Sasaram, Rohtas, Bihar 821115</p><p>+91 9470014145<br>+91 8789036195</p></div></div><div class="container footer-map"><div><h3>Find Shakuntalam College</h3><p class="muted">Use the map for the City Campus area and contact the college for the exact office location.</p><a class="btn btn-outline" href="#/contact">Contact &amp; Locations</a></div><iframe src="https://www.google.com/maps?q=Bauliya%20More%2C%20Sasaram%2C%20Bihar&output=embed" loading="lazy" title="Shakuntalam College map"></iframe></div><div class="container copy"><span>© 2026 Shakuntalam College · Devi Shakuntalam Prathisthan · ESTD 2009</span><span>Academic · Admissions · Student Services</span></div></footer>`}
function brandBlock(){return `<div class="brand-lockup inline-brand"><img class="brand-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><span class="brand-copy"><strong>SHAKUNTALAM COLLEGE</strong><small>DEVI SHAKUNTALAM PRATHISTHAN</small><em>ESTD 2009</em></span></div>`}
function home(){const ev=eventsData().slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,3);return layout(`<main><section class="hero hero-brand"><div class="container hero-grid"><div class="hero-copy"><h1>Knowledge. Character. <span>Opportunity.</span></h1><p>Shakuntalam College brings teacher education, management, computing and industrial training together with a student-centred academic environment.</p><div class="hero-actions"><a class="btn btn-gold" href="#/admissions">Apply for Admission →</a><a class="btn btn-light-outline" href="#/departments">Explore Departments</a></div></div><div class="hero-card"><img src="${img.hero}" alt="Students learning together"><div class="hero-card-caption"><b>SHakuntalam College</b><span>Academic Session 2026–27</span></div></div></div></section><section class="section menu-section"><div class="container"><div class="section-head"><div><span class="kicker">College information</span><h2>Explore every part of Shakuntalam College.</h2></div><p>Admissions, administration, academics, examination, infrastructure, events and student services are organised here for quick access.</p></div><div class="mega-links">${[['Admission','Admissions, eligibility and online application.','01','/admissions'],['Administration','Leadership, offices and institutional services.','02','/administration'],['Academics','Programs, assessment and academic support.','03','/academics'],['Department','Teachers Education, Management and Industrial Training.','04','/departments'],['Centre & Cell','Student welfare, grievance, anti-ragging and support cells.','05','/centre-cell'],['Examination','Schedules, assessment and published results.','06','/examination'],['Notice','Latest admission and academic announcements.','07','/notices'],['Infrastructure','Library, laboratories, workshops, sports and facilities.','08','/infrastructure'],['Events','Seminars, orientation, workshops and campus activities.','09','/events'],['Students Zone','Portal, fees, attendance, results and student support.','10','/students-zone']].map(x=>`<a class="mega-link" href="#${x[3]}"><span class="mega-no">${x[2]}</span><span><b>${x[0]}</b><small>${x[1]}</small></span><span>→</span></a>`).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Academic portfolio</span><h2>Programs for learning and livelihood.</h2></div><p>Teacher education, management and industrial training pathways with practical exposure and student services.</p></div><div class="cards">${courses.map(courseCard).join('')}</div></div></section><section class="section dark-section"><div class="container mission"><div class="section-head"><div><span class="kicker">Our purpose</span><h2>Knowledge that becomes capability.</h2></div></div><div class="feature-grid"><div class="card"><h3>Mission</h3><p>Provide accessible, disciplined and practical education that helps students develop knowledge, professional skills and confidence.</p></div><div class="card"><h3>Values</h3><p>Integrity, inclusion, academic responsibility, respect, service, practical learning and continuous improvement.</p></div></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Latest activities</span><h2>Events &amp; campus life.</h2></div><a class="btn btn-outline" href="#/events">View all events</a></div><div class="cards">${ev.map(eventCard).join('')||'<div class="card"><h3>Events will appear here</h3><p class="muted">Administrators can add events and photographs from the admin portal.</p></div>'}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Stay connected</span><h2>Follow Shakuntalam College.</h2></div></div><div class="social-grid"><a href="#"><b>Facebook</b><span>College updates and announcements</span></a><a href="#"><b>Instagram</b><span>Campus moments and events</span></a><a href="#"><b>YouTube</b><span>Lectures, events and academic videos</span></a><a href="#"><b>WhatsApp</b><span>Admissions and student communication</span></a></div></div></section></main>`)}
function eventCard(e){return `<article class="card event-card"><img src="${e.image||img.campus}" alt="${e.title}"><div class="event-body"><span class="pill">${e.date}</span><h3>${e.title}</h3><p class="muted">${e.description||''}</p><small>${e.location||'Shakuntalam College'}</small></div></article>`}
function events(){return page('Events','Seminars, orientation, workshops, cultural activities and campus programmes.',`<section class="section"><div class="container"><div class="cards">${eventsData().slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(eventCard).join('')||'<div class="card"><h2>No events yet</h2><p class="muted">Events published by the administrator will appear here.</p></div>'}</div></div></section>`) }
function side(role,active){const items=role==='admin'?['dashboard','students','teachers','admins','admissions','events','notices','payments','settings']:role==='teacher'?['dashboard','attendance','assignments','results']:['dashboard','profile','attendance','fees','results','notices'];return `<aside class="side portal-sidebar-${role}"><a class="brand" href="#/"><img class="brand-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><span class="brand-copy"><strong>SHAKUNTALAM COLLEGE</strong><small>DEVI SHAKUNTALAM PRATHISTHAN</small><em>ESTD 2009</em></span></a><nav>${items.map(i=>`<a class="${i===active?'active':''}" href="#/portal/${role}/${i}">${icon(i)} ${titleCase(i)}</a>`).join('')}</nav><button class="btn btn-ghost" style="width:100%;margin-top:20px" onclick="clearSession();location.hash='/'">Sign out</button></aside>`}
function portalLogin(e){e.preventDefault();const u=document.getElementById('loginUser').value.trim(),pw=document.getElementById('loginPass').value;let who=null;if(role==='student')who=students().find(x=>(norm(x.username)===norm(u)||norm(x.id)===norm(u)||norm(x.name)===norm(u))&&String(x.password)===String(pw));if(role==='teacher')who=teachers().find(x=>norm(x.username)===norm(u)&&String(x.password)===String(pw));if(role==='admin')who=admins().find(x=>norm(x.username)===norm(u)&&String(x.password)===String(pw));if(!who){toast('Invalid username or password.');return}if(who.status==='Inactive'){toast('This account is inactive. Contact the administrator.');return}setSession({role,...who});location.hash=`/portal/${role}`;closeLogin()}
function adminContent(s){if(s==='students')return adminStudents();if(s==='teachers')return adminTeachers();if(s==='admins')return adminAdmins();if(s==='notices')return adminNotices();if(s==='payments')return adminPayments();if(s==='admissions')return adminAdmissions();if(s==='events')return adminEvents();if(s==='settings')return adminSettings();return adminDashboard()}
function adminDashboard(){const s=students(),a=applications(),e=eventsData();return `<div class="dash-grid"><div class="metric"><b>${s.length}</b><small>Total students</small></div><div class="metric"><b>${teachers().length}</b><small>Teachers</small></div><div class="metric"><b>${a.filter(x=>x.status==='New').length}</b><small>New admissions</small></div><div class="metric"><b>${e.length}</b><small>Events</small></div></div><div class="admin-grid"><div class="card"><span class="kicker">Administration</span><h2>College control centre</h2><p class="muted">Manage accounts, admissions, events, notices, payments and academic records.</p><div class="quick-grid"><a class="btn btn-primary" href="#/portal/admin/students">Students</a><a class="btn btn-ghost" href="#/portal/admin/teachers">Teachers</a><a class="btn btn-ghost" href="#/portal/admin/admins">Administrators</a><a class="btn btn-ghost" href="#/portal/admin/events">Events</a><a class="btn btn-ghost" href="#/portal/admin/admissions">Applications</a><a class="btn btn-ghost" href="#/portal/admin/notices">Notices</a></div></div><div class="card"><span class="kicker">Demo database</span><h3>Credentials and records</h3><p class="muted">This demo intentionally keeps passwords visible to administrators. Do not use this storage model for a production deployment; production passwords should be securely hashed server-side.</p><button class="btn btn-outline" onclick="exportDB()">Export database</button></div></div>`}
function adminStudents(){return `<div class="toolbar"><input id="studentSearch" placeholder="Search name, ID, username or course" oninput="renderStudentTable()"><button class="btn btn-primary" onclick="openAddStudent()">＋ Add student</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Student</th><th>Username</th><th>Password</th><th>Course</th><th>Attendance</th><th>Status</th><th>Actions</th></tr></thead><tbody id="studentRows"></tbody></table></div><div class="modal" id="studentModal"><div class="modal-box"><div class="modal-head"><h2 id="studentModalTitle">Add new student</h2><button class="close" onclick="closeStudentModal()">×</button></div><form class="form" onsubmit="saveStudentFromForm(event)"><input type="hidden" id="editStudentId"><div class="form-grid"><input id="newName" placeholder="Full name" required><select id="newCourse">${depts.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-grid"><input id="newUsername" placeholder="Username" required><input id="newPassword" placeholder="Password" required></div><div class="form-grid"><input id="newEmail" type="email" placeholder="Email" required><input id="newPhone" placeholder="Phone" required></div><div class="form-grid"><input id="newSemester" type="number" min="1" max="8" required><input id="newAttendance" type="number" min="0" max="100" required></div><div class="form-grid"><select id="newFees"><option>Paid</option><option>Due</option></select><select id="newStatus"><option>Active</option><option>Inactive</option></select></div><input id="newCampus" placeholder="Campus"><button class="btn btn-primary">Save student record</button></form></div></div>`}
function renderStudentTable(){const q=norm(document.getElementById('studentSearch')?.value);const rows=students().filter(x=>`${x.id} ${x.name} ${x.username} ${x.course}`.toLowerCase().includes(q)).map(x=>`<tr><td>${x.id}</td><td><b>${x.name}</b><br><small>${x.email}</small></td><td>${x.username}</td><td><code>${x.password}</code></td><td>${x.course}</td><td>${x.attendance}%</td><td><span class="tag ${x.status==='Active'?'green':'red'}">${x.status}</span></td><td><div class="row-actions"><button class="btn btn-ghost" onclick="openEditStudent('${x.id}')">Edit</button><button class="btn btn-ghost" onclick="toggleStudent('${x.id}')">${x.status==='Active'?'Deactivate':'Activate'}</button></div></td></tr>`).join('');const el=document.getElementById('studentRows');if(el)el.innerHTML=rows||'<tr><td colspan="8" class="empty">No students found.</td></tr>'}
function adminTeachers(){return `<div class="toolbar"><button class="btn btn-primary" onclick="openTeacherModal()">＋ Add teacher</button></div><div class="cards">${teachers().map(x=>`<div class="card"><span class="pill">${x.department}</span><h3>${x.name}</h3><p><b>Username:</b> ${x.username}</p><p><b>Password:</b> <code>${x.password}</code></p><span class="tag ${x.status==='Active'?'green':'red'}">${x.status}</span><div style="margin-top:15px"><button class="btn btn-ghost" onclick="toggleTeacher('${x.id}')">${x.status==='Active'?'Deactivate':'Activate'}</button></div></div>`).join('')}</div><div class="modal" id="teacherModal"><div class="modal-box"><div class="modal-head"><h2>Add teacher</h2><button class="close" onclick="document.getElementById('teacherModal').classList.remove('show')">×</button></div><form class="form" onsubmit="addTeacher(event)"><input id="teacherName" placeholder="Teacher name" required><div class="form-grid"><input id="teacherUser" placeholder="Username" required><input id="teacherPass" placeholder="Password" required></div><select id="teacherDept" required><option>Teachers Education</option><option>Management</option><option>Industrial Training</option></select><button class="btn btn-primary">Create teacher account</button></form></div></div>`}
function adminAdmins(){return `<div class="toolbar"><button class="btn btn-primary" onclick="openAdminModal()">＋ Add administrator</button></div><div class="cards">${admins().map(x=>`<div class="card"><span class="pill">ADMIN</span><h3>${x.name}</h3><p><b>Username:</b> ${x.username}</p><p><b>Password:</b> <code>${x.password}</code></p><span class="tag ${x.status==='Active'?'green':'red'}">${x.status}</span><div style="margin-top:15px"><button class="btn btn-ghost" onclick="toggleAdmin('${x.id}')">${x.status==='Active'?'Deactivate':'Activate'}</button></div></div>`).join('')}</div><div class="modal" id="adminModal"><div class="modal-box"><div class="modal-head"><h2>Create administrator</h2><button class="close" onclick="document.getElementById('adminModal').classList.remove('show')">×</button></div><form class="form" onsubmit="addAdmin(event)"><input id="adminName" placeholder="Administrator name" required><input id="adminUser" placeholder="Username" required><input id="adminPass" placeholder="Password" required><button class="btn btn-primary">Create admin account</button></form></div></div>`}
function openAdminModal(){document.getElementById('adminModal').classList.add('show')}
function addAdmin(e){e.preventDefault();const a=admins();const username=adminUser.value.trim();if(a.some(x=>norm(x.username)===norm(username))){toast('That administrator username already exists.');return}a.push({id:'ADM-'+Date.now().toString().slice(-6),name:adminName.value.trim(),username,password:adminPass.value,status:'Active',permissions:['all']});saveAdmins(a);document.getElementById('adminModal').classList.remove('show');route();toast('Administrator account created.')}
function toggleAdmin(id){const a=admins(),x=a.find(z=>z.id===id);if(!x)return;if(x.id===activeAdmin()?.id){toast('You cannot deactivate the account currently in use.');return}x.status=x.status==='Active'?'Inactive':'Active';saveAdmins(a);route()}
function adminEvents(){return `<div class="toolbar"><button class="btn btn-primary" onclick="openEventModal()">＋ Add event</button></div><div class="cards">${eventsData().map(e=>`<article class="card event-card"><img src="${e.image||img.campus}" alt="${e.title}"><div class="event-body"><span class="pill">${e.date}</span><h3>${e.title}</h3><p class="muted">${e.description||''}</p><small>${e.location||''}</small><div class="row-actions" style="margin-top:15px"><button class="btn btn-ghost" onclick="editEvent('${e.id}')">Edit</button><button class="btn btn-ghost" onclick="deleteEvent('${e.id}')">Delete</button></div></div></article>`).join('')||'<div class="card"><h3>No events yet.</h3></div>'}</div><div class="modal" id="eventModal"><div class="modal-box"><div class="modal-head"><h2 id="eventModalTitle">Add event</h2><button class="close" onclick="document.getElementById('eventModal').classList.remove('show')">×</button></div><form class="form" onsubmit="saveEventFromForm(event)"><input type="hidden" id="editEventId"><input id="eventTitle" placeholder="Event title" required><div class="form-grid"><input id="eventDate" type="date" required><input id="eventLocation" placeholder="Location" required></div><textarea id="eventDescription" rows="4" placeholder="Description" required></textarea><label class="upload-box">Event picture<input id="eventImage" type="file" accept="image/*"></label><img id="eventPreview" class="event-preview" style="display:none"><button class="btn btn-primary">Save event</button></form></div></div>`}
function openEventModal(){document.getElementById('eventModalTitle').textContent='Add event';document.getElementById('editEventId').value='';document.getElementById('eventTitle').value='';document.getElementById('eventDate').value='';document.getElementById('eventLocation').value='';document.getElementById('eventDescription').value='';document.getElementById('eventImage').value='';document.getElementById('eventPreview').style.display='none';document.getElementById('eventModal').classList.add('show')}
function editEvent(id){const e=eventsData().find(x=>x.id===id);if(!e)return;document.getElementById('eventModalTitle').textContent='Edit event';document.getElementById('editEventId').value=e.id;document.getElementById('eventTitle').value=e.title;document.getElementById('eventDate').value=e.date;document.getElementById('eventLocation').value=e.location||'';document.getElementById('eventDescription').value=e.description||'';document.getElementById('eventImage').value='';const p=document.getElementById('eventPreview');p.src=e.image||img.campus;p.style.display='block';document.getElementById('eventModal').classList.add('show')}
function saveEventFromForm(e){e.preventDefault();const file=document.getElementById('eventImage').files[0];const finish=(image)=>{const arr=eventsData();const id=document.getElementById('editEventId').value;const old=arr.find(x=>x.id===id);const rec={id:id||'EVT-'+Date.now().toString().slice(-6),title:document.getElementById('eventTitle').value.trim(),date:document.getElementById('eventDate').value,location:document.getElementById('eventLocation').value.trim(),description:document.getElementById('eventDescription').value.trim(),image:image||old?.image||img.campus};const idx=arr.findIndex(x=>x.id===id);if(idx>=0)arr[idx]=rec;else arr.unshift(rec);saveEvents(arr);document.getElementById('eventModal').classList.remove('show');route();toast(idx>=0?'Event updated everywhere.':'Event added with picture.');};if(file){const r=new FileReader();r.onload=()=>finish(r.result);r.readAsDataURL(file)}else finish(null)}
function deleteEvent(id){const arr=eventsData().filter(x=>x.id!==id);saveEvents(arr);route();toast('Event deleted.')}
route();
/* Enhanced Shakuntalam College demo layer */
function siteDefaults(){return {heroTitle:'KNOWLEDGE. CHARACTER. OPPORTUNITY.',heroText:'Shakuntalam College brings teacher education, management, computing and industrial training together with a student-centred academic environment.',heroImage:'assets/hero-campus-main.png',heroSlides:[{image:'assets/hero-campus-main.png',title:'Shakuntalam College · Main Campus'},{image:'assets/hero-campus-iti.png',title:'Shakuntalam ITI Campus'},{image:'assets/hero-campus-event.png',title:'Campus Inauguration'}],primary:'#063a82',accent:'#f3c316',sections:['about','programs','mission','facilities','events','social','map'],homeImages:{campusSlides:[{image:'assets/purpose-campus-main.png',title:'Shakuntalam College Campus'},{image:'assets/hero-campus-iti.png',title:'Shakuntalam ITI Campus'}],classroomSlides:[{image:'assets/learning-clean-campus.png',title:'Campus Cleanliness Drive'},{image:'assets/learning-seminar.png',title:'Academic Seminar'},{image:'assets/learning-holi-celebration.png',title:'Campus Celebration'}]},socials:[['Facebook','#','f'],['Instagram','#','ig'],['YouTube','#','yt'],['WhatsApp','#','wa']]};}
function siteConfig(){const d=db()||{};if(!d.site)d.site=siteDefaults();if(!Array.isArray(d.site.socials))d.site.socials=siteDefaults().socials;if(!Array.isArray(d.site.sections))d.site.sections=['about','programs','mission','facilities','events','social','map'];return d.site}
function saveSite(s){const d=db();d.site=s;return saveDB(d)}
function ensureEnhancedSchema(){const d=db()||{};d.attendanceLogs=d.attendanceLogs||{};d.payments=d.payments||[];d.site=d.site||siteDefaults();d.site.heroSlides=Array.isArray(d.site.heroSlides)?d.site.heroSlides.filter(x=>x&&x.image):[];if(!d.site.heroSlides.length){d.site.heroSlides=[{image:d.site.heroImage||'assets/hero-campus-main.png',title:'Shakuntalam College · Main Campus'},{image:'assets/hero-campus-iti.png',title:'Shakuntalam ITI Campus'},{image:'assets/hero-campus-event.png',title:'Campus Inauguration'}];}d.site.heroSlides.forEach(x=>{if(/^Academic Session 2026[–-]27$/.test(String(x.title||'')))x.title='Shakuntalam College'});d.site.heroImage=d.site.heroSlides[0].image;saveDB(d)}
ensureEnhancedSchema();
function todayKey(){const d=new Date();return d.toISOString().slice(0,10)}
function nowLabel(){return new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'medium'}).format(new Date())}
function startClock(){const el=document.getElementById('liveDateTime');if(!el)return;const tick=()=>{el.textContent=nowLabel()};tick();clearInterval(window._collegeClock);window._collegeClock=setInterval(tick,1000)}
function socialIcon(kind){const paths={f:'<path d="M14 8h-3V6.2c0-1 .7-1.7 1.8-1.7H14V1.1L11.7 1C8.8 1 7 2.8 7 5.8V8H4v4h3v8h4v-8h2.7L14 8z"/>',ig:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1"/>',yt:'<path d="M21.6 7.2a2.7 2.7 0 0 0-1.9-1.9C18 4.8 12 4.8 12 4.8s-6 0-7.7.5a2.7 2.7 0 0 0-1.9 1.9A28 28 0 0 0 2 12a28 28 0 0 0 .4 4.8 2.7 2.7 0 0 0 1.9 1.9c1.7.5 7.7.5 7.7.5s6 0 7.7-.5a2.7 2.7 0 0 0 1.9-1.9A28 28 0 0 0 22 12a28 28 0 0 0-.4-4.8z"/><path d="m10 15 5-3-5-3z" fill="currentColor" stroke="none"/>',wa:'<path d="M20.5 3.5A11.9 11.9 0 0 0 12 0C5.4 0 .1 5.3.1 11.9c0 2.1.5 4.1 1.6 5.9L0 24l6.3-1.6a12 12 0 0 0 5.7 1.4h.1c6.5 0 11.8-5.3 11.8-11.9 0-3.2-1.2-6.2-3.4-8.4zM12 21.8c-1.8 0-3.5-.5-5-1.4l-.4-.2-3.7.9 1-3.6-.2-.4a9.8 9.8 0 0 1-1.5-5.2C2.2 6.7 6.6 2.3 12 2.3s9.8 4.4 9.8 9.8-4.4 9.7-9.8 9.7z"/><path d="M17.7 14.7c-.3-.2-1.8-.9-2-.9-.3-.1-.5-.2-.7.2-.2.3-.7.9-.8 1.1-.2.2-.3.2-.6.1-1.7-.8-2.8-1.4-3.9-3.2-.3-.5.3-.4.8-1.3.1-.2.1-.4 0-.6-.1-.2-.7-1.7-.9-2.3-.2-.6-.5-.5-.7-.5h-.6c-.2 0-.6.1-.9.4-.3.3-1.2 1.1-1.2 2.6s1.2 3 1.4 3.2c.2.2 2.4 3.7 5.8 5 .8.3 1.5.5 2 .6.8.3 1.6.2 2.2.1.7-.1 1.8-.7 2.1-1.4.3-.7.3-1.3.2-1.4-.1-.2-.3-.3-.6-.4z" fill="currentColor" stroke="none"/>' };return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[kind]||paths.f}</svg>`}
function header(){return `<div class="topbar"><div class="container topbar-inner"><span>ADMISSIONS 2026–27</span><span id="liveDateTime">${nowLabel()}</span><span>+91 9470014145 · +91 8789036195</span></div></div><header class="nav"><div class="container navin"><a class="brand brand-lockup" href="#/"><img class="brand-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><span class="brand-copy"><strong>SHAKUNTALAM COLLEGE</strong><small>DEVI SHAKUNTALAM PRATHISTHAN</small><em>ESTD 2009</em></span></a><nav class="links"><div class="nav-drop"><a href="#/admissions">Admission</a><div class="drop-menu"><a href="#/admissions">Apply Online</a><a href="#/admission-status">Application Status</a></div></div><div class="nav-drop"><a href="#/administration">Administration</a><div class="drop-menu"><a href="#/leadership">Leadership</a><a href="#/faculty">Faculty</a></div></div><div class="nav-drop"><a href="#/academics">Academics</a><div class="drop-menu"><a href="#/departments">Departments</a><a href="#/examination">Examination</a></div></div><div class="nav-drop"><a href="#/departments">Department</a><div class="drop-menu"><a href="#/course/B.Ed.">Teachers Education</a><a href="#/course/BBA">Management</a><a href="#/course/Electrician">Industrial Training</a></div></div><div class="nav-drop"><a href="#/centre-cell">Centre &amp; Cell</a><div class="drop-menu"><a href="#/student-welfare">Student Welfare</a><a href="#/centre-cell">Grievance &amp; Support</a></div></div><a href="#/examination">Examination</a><a href="#/notices">Notice</a><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/students-zone">Students Zone</a></nav><div class="nav-actions"><button class="btn btn-primary" onclick="openLogin()">Portal Login</button><button class="hamb" onclick="toggleMobile()">☰</button></div></div><div class="mobile-menu" id="mobileMenu"><a href="#/admissions">Admission</a><a href="#/administration">Administration</a><a href="#/academics">Academics</a><a href="#/departments">Department</a><a href="#/centre-cell">Centre &amp; Cell</a><a href="#/examination">Examination</a><a href="#/notices">Notice</a><a href="#/infrastructure">Infrastructure</a><a href="#/events">Events</a><a href="#/students-zone">Students Zone</a></div></header>`}
function footer(){const s=siteConfig();return `<footer class="footer"><div class="container footer-top"><div class="footer-brand"><img class="footer-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><div class="footer-title">SHAKUNTALAM COLLEGE</div><div class="footer-sub">DEVI SHAKUNTALAM PRATHISTHAN</div><div class="footer-estd">ESTD 2009</div><p>Quality education, professional development and student opportunity under one academic community.</p><div class="socials">${s.socials.map(x=>`<a href="${x[1]}" aria-label="${x[0]}">${socialIcon(x[2])}<span>${x[0]}</span></a>`).join('')}</div></div><div><h3>Quick Links</h3><a href="#/about">About College</a><a href="#/mission">Mission &amp; Values</a><a href="#/faculty">Faculty</a><a href="#/notices">Notice Board</a><a href="#/events">Events</a></div><div><h3>Student Services</h3><a href="#/admissions">Admissions</a><a href="#/students-zone">Students Zone</a><a href="#/portal/student">Student Portal</a><a href="#/portal/teacher">Teacher Portal</a></div><div><h3>Contact</h3><p>Kirhindih, Kumhau Station Road<br>Sheosagar, Sasaram, Rohtas, Bihar 821115</p><p>City Campus, Bauliya More<br>Sasaram, Rohtas, Bihar 821115</p><p>+91 9470014145<br>+91 8789036195</p></div></div><div class="container footer-map"><div><h3>Find Shakuntalam College</h3><p class="muted">City Campus · Bauliya More, Sasaram</p><a class="btn btn-outline" href="#/contact">Contact &amp; Locations</a></div><iframe src="https://www.google.com/maps?q=Bauliya%20More%2C%20Sasaram%2C%20Bihar&output=embed" loading="lazy" title="Shakuntalam College map"></iframe></div><div class="container copy"><span>© 2026 Shakuntalam College · Devi Shakuntalam Prathisthan · ESTD 2009</span><span>Academic · Admissions · Student Services</span></div></footer>`}
function home(){const s=siteConfig(),slides=(s.heroSlides||[]).filter(x=>x&&x.image);const safeSlides=slides.length?slides:[{image:s.heroImage||img.hero,title:'Academic Session 2026–27'}];return layout(`<main><section class="hero hero-brand hero-slider-wrap"><div class="container hero-grid"><div class="hero-copy"><h1>${escapeHtml(s.heroTitle||'KNOWLEDGE. CHARACTER. OPPORTUNITY.')}</h1><p>${escapeHtml(s.heroText||'')}</p><div class="hero-actions"><a class="btn btn-gold" href="#/admissions">Apply for Admission →</a><a class="btn btn-light-outline" href="#/departments">Explore Departments</a></div></div><div class="hero-carousel" id="homeHeroCarousel" data-index="0" data-interval="5000"><div class="hero-slides">${safeSlides.map((x,i)=>`<figure class="hero-slide ${i===0?'is-active':''}" data-slide="${i}"><img src="${x.image}" alt="${escapeHtml(x.title||'College highlight')}"><figcaption><b>${escapeHtml(x.title||'Campus highlight')}</b><span>Academic Session 2026–27</span></figcaption></figure>`).join('')}</div>${safeSlides.length>1?`<button class="hero-arrow hero-prev" onclick="heroSlideV5(-1)" aria-label="Previous image">‹</button><button class="hero-arrow hero-next" onclick="heroSlideV5(1)" aria-label="Next image">›</button><div class="hero-dots">${safeSlides.map((_,i)=>`<button class="hero-dot ${i===0?'active':''}" onclick="heroGoV5(${i})" aria-label="Show image ${i+1}"></button>`).join('')}</div>`:''}</div></div></section><section class="section menu-section"><div class="container"><div class="section-head"><div><span class="kicker">College information</span><h2>Explore every part of Shakuntalam College.</h2></div><p>Admissions, academics, departments, examination, infrastructure, events and student services.</p></div><div class="mega-links">${[['Admission','Admissions, eligibility and application.','01','/admissions'],['Administration','Leadership, offices and institutional services.','02','/administration'],['Academics','Programs, assessment and support.','03','/academics'],['Department','Teacher Education, Management and Industrial Training.','04','/departments'],['Centre & Cell','Student welfare and support cells.','05','/centre-cell'],['Examination','Schedules, assessment and results.','06','/examination'],['Infrastructure','Library, labs, workshops and facilities.','07','/infrastructure'],['Events','Seminars, workshops and campus activities.','08','/events'],['Students Zone','Portal, fees, attendance, results and notices.','09','/students-zone']].map(x=>`<a class="mega-link" href="#${x[3]}"><span class="mega-no">${x[2]}</span><span><b>${x[0]}</b><small>${x[1]}</small></span><span>→</span></a>`).join('')}</div></div></section><section class="section"><div class="container two-col"><div><span class="kicker">About Shakuntalam</span><h2>Education with purpose.</h2><p class="lead">A connected academic environment for teacher education, management, computing and industrial skills.</p><a class="btn btn-outline" href="#/about">Read more</a></div><img class="home-image" src="${s.homeImages?.campus||img.campus}" alt="Campus"></div></section><section class="section"><div class="container two-col"><img class="home-image" src="${s.homeImages?.classroom||img.class}" alt="Classroom"><div><span class="kicker">Student experience</span><h2>Learning, practice and progress.</h2><p class="lead">Explore programs, student services, assignments, attendance and semester results through the connected portal.</p><a class="btn btn-primary" href="#/students-zone">Students Zone →</a></div></div></section></main>`)}
function heroGoV5(index){const box=document.getElementById('homeHeroCarousel'),slides=box?[...box.querySelectorAll('.hero-slide')]:[];if(!slides.length)return;const next=((index%slides.length)+slides.length)%slides.length;slides.forEach((x,i)=>x.classList.toggle('is-active',i===next));box.dataset.index=String(next);box.querySelectorAll('.hero-dot').forEach((x,i)=>x.classList.toggle('active',i===next))}
function heroSlideV5(delta){const box=document.getElementById('homeHeroCarousel');if(!box)return;const slides=[...box.querySelectorAll('.hero-slide')];if(slides.length<2)return;heroGoV5(Number(box.dataset.index||0)+delta);startHeroCarouselV5(true)}
function startHeroCarouselV5(reset=false){clearInterval(window._heroCarouselTimer);const box=document.getElementById('homeHeroCarousel');if(!box)return;const slides=[...box.querySelectorAll('.hero-slide')];if(slides.length<2)return;if(reset)box.dataset.index=box.dataset.index||'0';window._heroCarouselTimer=setInterval(()=>heroGoV5(Number(box.dataset.index||0)+1),5000)}

function studentContent(s){const me=currentUser();const x=students().find(a=>a.id===me?.id)||me;if(s==='profile')return `<div class="card"><h2>${x.name}</h2><p class="muted">Student ID: ${x.id} • ${x.course} • Semester ${x.semester}</p><form class="form" onsubmit="saveStudentSelf(event)"><div class="form-grid"><input id="selfEmail" value="${x.email}"><input id="selfPhone" value="${x.phone}"></div><input id="selfCampus" value="${x.campus||''}"><button class="btn btn-primary">Save profile</button></form></div><div class="card" style="margin-top:18px"><h2>Change password</h2><form class="form" onsubmit="changeStudentPassword(event)"><input id="oldPass" type="password" placeholder="Current password" required><input id="newPass" type="password" placeholder="New password / number" required><button class="btn btn-primary">Update password</button></form></div>`;if(s==='fees')return studentFees(x);if(s==='attendance')return studentAttendance(x);if(s==='results'){const r=x.results?.Sem1||{Internal:0,Theory:0,Practical:0,Grade:'Pending'};return `<div class="dash-grid"><div class="metric"><b>${r.Internal}</b><small>Internal</small></div><div class="metric"><b>${r.Theory}</b><small>Theory</small></div><div class="metric"><b>${r.Practical}</b><small>Practical</small></div><div class="metric"><b>${r.Grade}</b><small>Grade</small></div></div><div class="card"><h2>Semester 1 Result</h2><p class="muted">Published results are updated by your department teacher.</p></div>`}return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>7.8</b><small>Current CGPA</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div><div class="metric"><b>${x.fees==='Due'?'₹5K':'Paid'}</b><small>Fees</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Welcome back</span><h2>${x.name}</h2><p class="muted">${x.course} • Semester ${x.semester} • ${x.campus||'Campus'}</p><a class="btn btn-primary" href="#/portal/student/profile">Edit profile</a></div><div class="card"><span class="kicker">Result</span><h2>View your result</h2><a class="btn btn-outline" href="#/portal/student/results">Open result →</a></div></div>`}
function adminContent(s){if(s==='students')return adminStudents();if(s==='teachers')return adminTeachers();if(s==='admins')return adminAdmins();if(s==='admissions')return adminAdmissions();if(s==='events')return adminEvents();if(s==='website')return websiteBuilder();if(s==='notices')return adminNotices();if(s==='payments')return adminPayments();if(s==='settings')return adminSettings();return adminDashboard()}
function adminDashboard(){const s=students(),a=applications(),e=eventsData();return `<div class="dash-grid"><div class="metric"><b>${s.length}</b><small>Total students</small></div><div class="metric"><b>${teachers().length}</b><small>Teachers</small></div><div class="metric"><b>${a.filter(x=>x.status==='New').length}</b><small>New admissions</small></div><div class="metric"><b>${e.length}</b><small>Events</small></div></div><div class="admin-grid"><div class="card"><span class="kicker">Administration</span><h2>College control centre</h2><p class="muted">Manage students, teachers, admissions, events, notices, payments and the public website visually.</p><div class="quick-grid"><a class="btn btn-primary" href="#/portal/admin/students">Students</a><a class="btn btn-ghost" href="#/portal/admin/teachers">Teachers</a><a class="btn btn-ghost" href="#/portal/admin/admissions">Applications</a><a class="btn btn-ghost" href="#/portal/admin/events">Events</a><a class="btn btn-ghost" href="#/portal/admin/website">Website Builder</a><a class="btn btn-ghost" href="#/portal/admin/notices">Notices</a></div></div><div class="card"><span class="kicker">Live demo database</span><h3>Website + ERP changes stay synchronized</h3><p class="muted">Website content, attendance, admissions, events, results and payments use the same temporary browser database.</p><button class="btn btn-outline" onclick="exportDB()">Export database</button></div></div></div>`}
function websiteBuilder(){const s=siteConfig();return `<div class="builder"><div class="builder-panel"><div class="builder-head"><div><span class="kicker">Visual editor</span><h2>Website Builder</h2><p class="muted">Edit the public site without coding. Changes are stored in this demo browser.</p></div><button class="btn btn-primary" onclick="publishSite()">Save &amp; Publish</button></div><div class="builder-section"><h3>Brand &amp; hero</h3><label>Hero heading<input id="wbHeroTitle" value="${escapeHtml(s.heroTitle)}" oninput="liveBuilderPreview()"></label><label>Hero description<textarea id="wbHeroText" rows="4" oninput="liveBuilderPreview()">${escapeHtml(s.heroText)}</textarea></label><label>Hero image<input id="wbHeroImage" type="file" accept="image/*" onchange="builderImage(this)"></label><div class="builder-image"><img id="wbImagePreview" src="${s.heroImage||img.hero}" alt="Hero preview"></div></div><div class="builder-section"><h3>Theme</h3><div class="form-grid"><label>Primary<input id="wbPrimary" type="color" value="${s.primary}" oninput="liveBuilderPreview()"></label><label>Accent<input id="wbAccent" type="color" value="${s.accent}" oninput="liveBuilderPreview()"></label></div></div><div class="builder-section"><div class="builder-section-title"><h3>Homepage sections</h3><button class="btn btn-outline" onclick="addWebsiteSection()">＋ Add section</button></div><div id="builderSections">${(s.sections||[]).map((k,i)=>`<div class="builder-row"><span class="drag-handle">⠿</span><b>${k.toUpperCase()}</b><span class="builder-spacer"></span><button onclick="moveWebsiteSection(${i},-1)">↑</button><button onclick="moveWebsiteSection(${i},1)">↓</button><button class="danger-mini" onclick="removeWebsiteSection(${i})">×</button></div>`).join('')}</div></div><div class="builder-section"><h3>Social links</h3>${s.socials.map((x,i)=>`<div class="social-edit"><span class="social-logo small">${socialIcon(x[2])}</span><input value="${escapeHtml(x[0])}" onchange="editSocial(${i},'name',this.value)"><input value="${escapeHtml(x[1])}" onchange="editSocial(${i},'url',this.value)"></div>`).join('')}</div></div><div class="builder-preview"><div class="preview-bar"><span>LIVE PREVIEW</span><span>Desktop</span></div><div class="preview-frame"><div class="preview-hero" id="builderPreview"><img src="${s.heroImage||img.hero}"><div><small>ADMISSIONS 2026–27</small><h1>${escapeHtml(s.heroTitle)}</h1><p>${escapeHtml(s.heroText)}</p><span class="preview-btn">Apply for Admission</span></div></div><div class="preview-section"><b>Homepage sections</b><div class="preview-chips">${s.sections.map(k=>`<span>${k}</span>`).join('')}</div></div></div></div></div>`}
function escapeHtml(v){return String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function builderDraft(){const s=siteConfig();return {...s,heroTitle:document.getElementById('wbHeroTitle')?.value||s.heroTitle,heroText:document.getElementById('wbHeroText')?.value||s.heroText,primary:document.getElementById('wbPrimary')?.value||s.primary,accent:document.getElementById('wbAccent')?.value||s.accent}}
function liveBuilderPreview(){const s=builderDraft();const p=document.getElementById('builderPreview');if(!p)return;p.querySelector('h1').textContent=s.heroTitle;p.querySelector('p').textContent=s.heroText;p.style.setProperty('--preview-primary',s.primary);p.style.setProperty('--preview-accent',s.accent)}
function builderImage(input){const file=input.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{const p=document.getElementById('wbImagePreview');if(p)p.src=r.result;const bp=document.querySelector('#builderPreview img');if(bp)bp.src=r.result;window._builderImage=r.result};r.readAsDataURL(file)}
function publishSite(){const s=builderDraft();if(window._builderImage)s.heroImage=window._builderImage;saveSite(s);route();toast('Website changes published to the demo site.')}
function addWebsiteSection(){const choices=['about','programs','mission','facilities','notices','events','social','map'];const s=siteConfig();const next=choices.find(x=>!s.sections.includes(x));if(next){s.sections.push(next);saveSite(s);route();}else toast('All available homepage sections are already added.')}
function moveWebsiteSection(i,delta){const s=siteConfig(),j=i+delta;if(j<0||j>=s.sections.length)return;[s.sections[i],s.sections[j]]=[s.sections[j],s.sections[i]];saveSite(s);route()}
function removeWebsiteSection(i){const s=siteConfig();s.sections.splice(i,1);saveSite(s);route()}
function editSocial(i,key,val){const s=siteConfig();s.socials[i][key==='name'?0:1]=val;saveSite(s);toast('Social link updated. Click Save & Publish after other edits.')}
function side(role,active){const items=role==='admin'?['dashboard','students','teachers','admins','admissions','events','website','notices','payments','settings']:role==='teacher'?['dashboard','attendance','assignments','results']:['dashboard','profile','attendance','fees','results','notices'];return `<aside class="side portal-sidebar-${role}"><div class="side-orb orb-a"></div><div class="side-orb orb-b"></div><a class="brand" href="#/"><img class="brand-logo" src="${_finalLogo}" alt="Shakuntalam College logo"><span class="brand-copy"><strong>SHAKUNTALAM</strong><small>COLLEGE</small><em>ESTD 2009</em></span></a><nav>${items.map(i=>`<a class="${i===active?'active':''}" href="#/portal/${role}/${i}"><span class="side-icon">${icon(i)}</span>${titleCase(i)}</a>`).join('')}</nav><button class="btn btn-ghost side-signout" onclick="clearSession();location.hash='/'">↪ Sign out</button></aside>`}
function icon(x){return ({dashboard:'⌂',students:'♙',teachers:'♧',attendance:'✓',assignments:'▤',results:'▥',fees:'₹',notices:'!',payments:'◈',profile:'◎',settings:'⚙',admins:'♛',admissions:'✎',events:'✦',website:'✥'})[x]||'•'}
function route(){const path=location.hash.replace(/^#/,'')||'/';let content='';if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/mission')content=mission();else if(path==='/departments')content=departments();else if(path==='/academics')content=academics();else if(path==='/administration')content=administration();else if(path==='/leadership')content=leadership();else if(path==='/centre-cell')content=centreCell();else if(path==='/examination')content=examination();else if(path==='/infrastructure')content=infrastructure();else if(path==='/events')content=events();else if(path==='/students-zone')content=studentsZone();else if(path==='/faculty')content=faculty();else if(path==='/student-welfare')content=studentWelfare();else if(path==='/admission-status')content=admissionStatus();else if(path.startsWith('/course/'))content=course(decodeURIComponent(path.split('/')[2]));else if(path==='/notices')content=notices();else if(path==='/facilities')content=facilities();else if(path==='/gallery')content=gallery();else if(path==='/contact')content=contact();else if(path==='/admissions')content=admissions();else if(path==='/payment')content=publicPaymentGuard();else if(path.startsWith('/portal/')){const p=path.split('/').filter(Boolean);const sess=currentUser();const wanted=p[1]||'student';if(!sess||sess.role!==wanted){content=page('Portal login required','Please sign in with your Shakuntalam College account.',`<section class="section"><div class="container card"><h2>Secure portal</h2><p class="muted">Sign in to access this area.</p><button class="btn btn-primary" onclick="openLogin()">Open Portal Login</button></div></section>`)}else content=portal(wanted,p[2]||'dashboard')}else content=home();app.innerHTML=content+loginModal();if(path.includes('/portal/admin/students'))renderStudentTable();startClock();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);route();

/* ===== V3 FUNCTIONAL FIXES ===== */
function ensureV3(){
  const d=db()||{};
  d.students=d.students||[];
  d.students.forEach((x,i)=>{x.username=String(x.username||x.name||'').trim()||`student${i+1}`;x.password=String(x.password??(1001+i));x.status=x.status||'Active';x.attendance=Number.isFinite(Number(x.attendance))?Math.max(0,Math.min(100,Number(x.attendance))):0});
  d.teachers=d.teachers||[];
  d.admins=d.admins||[{id:'ADM-001',name:'Super Administrator',username:'admin',password:'admin123',status:'Active',permissions:['all']}];
  if(!d.admins.some(x=>norm(x.username)==='admin')) d.admins.unshift({id:'ADM-001',name:'Super Administrator',username:'admin',password:'admin123',status:'Active',permissions:['all']});
  d.events=d.events||[];
  d.applications=d.applications||[];
  d.payments=d.payments||[];
  d.attendanceLogs=d.attendanceLogs||{};
  d.teacherAttendance=d.teacherAttendance||{};
  d.assignments=d.assignments||[];
  d.paymentConfig=d.paymentConfig||{upi:'shakuntalam@upi',merchant:'Shakuntalam College',qr:'',card:true,netbanking:true,upi:true};
  d.site=d.site||siteDefaults();
  d.site.sections=d.site.sections||['about','programs','mission','facilities','notices','events','social','map'];
  saveDB(d);
  rolloverAttendance();
}
function rolloverAttendance(){
  const d=db(); if(!d)return;
  const today=todayKey();
  d.attendanceMeta=d.attendanceMeta||{activeDate:today,submittedDates:{}};
  d.attendanceMeta.submittedDates=d.attendanceMeta.submittedDates||{};
  if(d.attendanceMeta.activeDate!==today){
    d.attendanceMeta.activeDate=today;
    /* The new day starts empty. Historical records remain read-only in the database. */
  }
  saveDB(d);
}
