 teachers:'<circle cx="9" cy="8" r="3"/><path d="M3.5 19c.6-3.3 2.4-5 5.5-5 2.2 0 3.8.8 4.8 2.5"/><path d="m15 7 1.5 1.5L20 5"/>',
 attendance:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m7.5 12 2.7 2.7 5.8-6"/>',
