 payments:'<rect x="3.5" y="5.5" width="17" height="13" rx="2.5"/><path d="M3.5 9h17M7 14h3"/>',
 profile:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-4 3.1-6 7-6s6.2 2 7 6"/>',
 settings:'<path d="M12 3.5v2M12 18.5v2M3.5 12h2M18.5 12h2M5.9 5.9l1.4 1.4M16.7 16.7l1.4 1.4M18.1 5.9l-1.4 1.4M7.3 16.7l-1.4 1.4"/><circle cx="12" cy="12" r="4"/>',
 admins:'<path d="M12 3 19 6v5c0 4.3-2.8 7.2-7 9-4.2-1.8-7-4.7-7-9V6l7-3Z"/><path d="m9 12 2 2 4-4"/>',
