function startClock(){const a=document.getElementById('liveDateTime'),b=document.getElementById('portalClock');clearInterval(window._collegeClock);const tick=()=>{if(a)a.textContent=nowLabelV3();if(b)b.textContent=new Date().toLocaleTimeString('en-IN')};tick();window._collegeClock=setInterval(tick,1000)}
function attendanceDayStatus(d,today){return d.attendanceMeta?.submittedDates?.[today]||null}
function teacherAttendance(){const t=currentTeacher(),allowed=allowedCourses(t),mine=students().filter(x=>allowed.includes(x.course));const d=db(),today=todayKey(),submitted=!!attendanceDayStatus(d,today),lockedDate=d.attendanceMeta?.activeDate!==today||submitted;const marked=mine.filter(x=>['P','A'].includes(d.attendanceLogs?.[x.id]?.[today])).length;const rows=mine.map(x=>{const st=d.attendanceLogs?.[x.id]?.[today]||'';return `<tr><td>${x.id}</td><td><b>${x.name}</b></td><td>${x.course}</td><td>${x.semester}</td><td><b>${x.attendance}%</b></td><td><span class="att-state ${st==='P'?'present':st==='A'?'absent':''}">${st||'Not marked'}</span></td><td><button class="att-action present" ${lockedDate?'disabled':''} onclick="setDailyAttendance('${x.id}','P')">Present</button><button class="att-action absent" ${lockedDate?'disabled':''} onclick="setDailyAttendance('${x.id}','A')">Absent</button><button class="att-action plus" onclick="adjustAttendance('${x.id}',1)">+1%</button><button class="att-action minus" onclick="adjustAttendance('${x.id}',-1)">−1%</button></td></tr>`}).join('');return `<div class="attendance-toolbar"><div><span class="pill">${t?.department||'Department'}</span><h2>Today's Attendance</h2><p class="muted">${currentDateLabel()} • Only your department students are visible. Past days are locked automatically at midnight.</p></div><div class="attendance-submit-actions"><button class="btn btn-outline" ${lockedDate?'disabled':''} onclick="markAllAttendanceToday()">✓ Mark All Present</button><button class="btn btn-primary" ${lockedDate||marked<mine.length?'disabled':''} onclick="submitTeacherAttendanceToday()">Submit Attendance for Today</button></div></div><div class="attendance-submit-status ${submitted?'submitted':''}">${submitted?'✓ Attendance submitted and locked for today.':`Daily register: <b>${marked}/${mine.length}</b> students marked. Mark every student, then submit the day.`}</div><div class="attendance-summary"><div><b>${mine.length}</b><span>Department students</span></div><div><b>${mine.filter(x=>d.attendanceLogs?.[x.id]?.[today]==='P').length}</b><span>Present today</span></div><div><b>${mine.filter(x=>d.attendanceLogs?.[x.id]?.[today]==='A').length}</b><span>Absent today</span></div><div><b>${mine.length?Math.round(mine.filter(x=>d.attendanceLogs?.[x.id]?.[today]==='P').length/mine.length*100):0}%</b><span>Today's rate</span></div></div><div class="table-wrap"><table class="table attendance-table"><thead><tr><th>ID</th><th>Student</th><th>Course</th><th>Sem</th><th>Overall</th><th>Today</th><th>Controls</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="empty">No students in your department.</td></tr>'}</tbody></table></div>`}
function submitTeacherAttendanceToday(){const d=db(),t=currentTeacher(),today=todayKey(),allowed=allowedCourses(t),mine=d.students.filter(x=>allowed.includes(x.course));if(d.attendanceMeta?.activeDate!==today){toast("Today's attendance is already closed.");return}if(mine.some(x=>!['P','A'].includes(d.attendanceLogs?.[x.id]?.[today]))){toast('Please mark Present or Absent for every student before submitting.');return}d.attendanceMeta=d.attendanceMeta||{};d.attendanceMeta.submittedDates=d.attendanceMeta.submittedDates||{};d.attendanceMeta.submittedDates[today]={submittedBy:t?.name||'Teacher',role:'teacher',at:new Date().toISOString()};saveDB(d);route();toast("Today's attendance submitted and locked.")} 
function setDailyAttendance(id,state){const d=db(),t=currentTeacher(),allowed=allowedCourses(t),x=d.students.find(s=>s.id===id),today=todayKey();if(!x||!allowed.includes(x.course)){toast('You can only manage your department students.');return}if(d.attendanceMeta?.activeDate!==today){toast('Today\'s attendance is already closed.');return}d.attendanceLogs=d.attendanceLogs||{};d.attendanceLogs[id]=d.attendanceLogs[id]||{};d.attendanceLogs[id][today]=state;recalcAttendance(x,d.attendanceLogs[id]);saveDB(d);route();toast(`${x.name}: ${state==='P'?'Present':'Absent'} for today.`)}
function adjustAttendance(id,delta){const d=db(),t=currentTeacher(),allowed=allowedCourses(t),x=d.students.find(s=>s.id===id);if(!x||!allowed.includes(x.course)){toast('You can only manage your department students.');return}x.attendance=Math.max(0,Math.min(100,(Number(x.attendance)||0)+delta));saveDB(d);route();toast(`Attendance adjusted to ${x.attendance}%.`)}
function markAllAttendanceToday(){const d=db(),t=currentTeacher(),allowed=allowedCourses(t),today=todayKey();if(d.attendanceMeta?.activeDate!==today){toast('Today\'s attendance is already closed.');return}d.attendanceLogs=d.attendanceLogs||{};d.students.filter(x=>allowed.includes(x.course)).forEach(x=>{d.attendanceLogs[x.id]=d.attendanceLogs[x.id]||{};d.attendanceLogs[x.id][today]='P';recalcAttendance(x,d.attendanceLogs[x.id])});saveDB(d);route();toast('All students in your department are marked present for today.')}
function recalcAttendance(x,log){const vals=Object.values(log).filter(v=>v==='P'||v==='A');if(vals.length)x.attendance=Math.round(vals.filter(v=>v==='P').length/vals.length*100)}
function studentAttendance(x){const d=db(),today=todayKey(),log=d.attendanceLogs?.[x.id]||{},st=log[today]||'Not marked';const p=Object.values(log).filter(v=>v==='P').length,a=Object.values(log).filter(v=>v==='A').length;return `<div class="attendance-overview"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>${p}</b><small>Present days</small></div><div class="metric"><b>${a}</b><small>Absent days</small></div></div><div class="card today-attendance-card"><span class="kicker">Attendance for today</span><h2>${currentDateLabel()}</h2><div class="today-status ${st==='P'?'present':st==='A'?'absent':''}">${st==='P'?'✓ Present':st==='A'?'✕ Absent':'Not yet marked'}</div><p class="muted">Attendance is entered by your department teacher. The daily register resets automatically at 12:00 AM; previous days remain in the overall calculation but are not editable by teachers.</p></div>`}
function teacherContent(s){const t=currentTeacher(),allowed=allowedCourses(t),mine=students().filter(x=>allowed.includes(x.course));if(s==='attendance')return teacherAttendance();if(s==='students')return `<div class="card"><h2>My Department Students</h2><p class="muted">Only <b>${t?.department||'your department'}</b> students are shown.</p><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Course</th><th>Semester</th><th>Attendance</th></tr></thead><tbody>${mine.map(x=>`<tr><td>${x.name}</td><td>${x.course}</td><td>${x.semester}</td><td>${x.attendance}%</td></tr>`).join('')}</tbody></table></div></div>`;if(s==='assignments')return teacherAssignmentsV3(mine);if(s==='results')return teacherResults(mine);return `<div class="dash-grid"><div class="metric"><b>${mine.length}</b><small>Department students</small></div><div class="metric"><b>${Math.round(mine.reduce((a,x)=>a+x.attendance,0)/(mine.length||1))}%</b><small>Department attendance</small></div><div class="metric"><b>${assignmentsForTeacher(t).length}</b><small>Assignments</small></div><div class="metric"><b>${applications().filter(a=>allowed.includes(a.course)&&a.status==='New').length}</b><small>New applicants</small></div></div><div class="feature-grid"><div class="card"><h2>Today's Attendance</h2><p class="muted">Mark, correct or adjust attendance for your department.</p><a class="btn btn-primary" href="#/portal/teacher/attendance">Open register →</a></div><div class="card"><h2>Assignments</h2><p class="muted">Create assignments, deadlines and instructions for your students.</p><a class="btn btn-outline" href="#/portal/teacher/assignments">Manage assignments →</a></div></div>`}
function assignmentsForTeacher(t){return (db().assignments||[]).filter(a=>a.teacherId===t?.id)}
function teacherAssignmentsV3(mine){const t=currentTeacher(),list=assignmentsForTeacher(t);return `<div class="assignment-head"><div><span class="kicker">Department learning</span><h2>Assignment Manager</h2><p class="muted">Create, edit and track assignments for ${t?.department||'your department'}.</p></div><button class="btn btn-primary" onclick="openAssignmentModal()">＋ New Assignment</button></div><div class="assignment-grid">${list.map(a=>`<article class="assignment-card"><div class="assignment-icon">▤</div><span class="pill">${a.course}</span><h3>${a.title}</h3><p>${a.description}</p><div class="assignment-meta"><span>Due: <b>${a.due}</b></span><span>${mine.filter(x=>x.course===a.course).length} students</span></div><button class="btn btn-ghost" onclick="editAssignment('${a.id}')">Edit</button></article>`).join('')||'<div class="card"><h3>No assignments yet.</h3><p class="muted">Create your first assignment.</p></div>'}</div><div class="modal" id="assignmentModal"><div class="modal-box"><div class="modal-head"><h2 id="assignmentModalTitle">New Assignment</h2><button class="close" onclick="closeAssignmentModal()">×</button></div><form class="form" onsubmit="saveAssignment(event)"><input type="hidden" id="assignmentId"><input id="assignmentTitle" placeholder="Assignment title" required><select id="assignmentCourse">${allowedCourses(t).map(c=>`<option>${c}</option>`).join('')}</select><input id="assignmentDue" type="date" required><textarea id="assignmentDesc" rows="5" placeholder="Instructions / learning outcome" required></textarea><button class="btn btn-primary">Save Assignment</button></form></div></div>`}
function openAssignmentModal(){document.getElementById('assignmentId').value='';document.getElementById('assignmentModalTitle').textContent='New Assignment';document.getElementById('assignmentTitle').value='';document.getElementById('assignmentDesc').value='';document.getElementById('assignmentDue').value=todayKey();document.getElementById('assignmentModal').classList.add('show')}
function editAssignment(id){const a=(db().assignments||[]).find(x=>x.id===id);if(!a)return;document.getElementById('assignmentId').value=a.id;document.getElementById('assignmentModalTitle').textContent='Edit Assignment';document.getElementById('assignmentTitle').value=a.title;document.getElementById('assignmentCourse').value=a.course;document.getElementById('assignmentDue').value=a.due;document.getElementById('assignmentDesc').value=a.description;document.getElementById('assignmentModal').classList.add('show')}
function closeAssignmentModal(){document.getElementById('assignmentModal')?.classList.remove('show')}
function saveAssignment(e){e.preventDefault();const d=db(),t=currentTeacher();d.assignments=d.assignments||[];const id=document.getElementById('assignmentId').value||'ASN-'+Date.now().toString().slice(-8);const rec={id,teacherId:t.id,course:document.getElementById('assignmentCourse').value,title:document.getElementById('assignmentTitle').value.trim(),due:document.getElementById('assignmentDue').value,description:document.getElementById('assignmentDesc').value.trim()};const i=d.assignments.findIndex(x=>x.id===id);if(i>=0)d.assignments[i]=rec;else d.assignments.unshift(rec);saveDB(d);closeAssignmentModal();route();toast('Assignment saved and published to the student portal.')}
function studentAssignments(x){const list=(db().assignments||[]).filter(a=>a.course===x.course);return `<div class="assignment-head"><div><span class="kicker">Learning tasks</span><h2>My Assignments</h2><p class="muted">Assignments from your ${x.course} teachers.</p></div><span class="student-chip">${list.length} active</span></div><div class="assignment-grid">${list.map(a=>`<article class="assignment-card"><div class="assignment-icon">▤</div><span class="pill">${a.course}</span><h3>${a.title}</h3><p>${a.description}</p><div class="assignment-meta"><span>Due: <b>${a.due}</b></span><span>Teacher task</span></div><button class="btn btn-primary" onclick="toast('Demo submission recorded for ${escapeHtml(a.title)}')">Mark as submitted</button></article>`).join('')||'<div class="card"><h3>No assignments published.</h3><p class="muted">Your teachers have not posted any assignments yet.</p></div>'}</div>`}
function studentContent(s){const me=currentUser(),x=students().find(a=>a.id===me?.id)||me;if(s==='profile')return `<div class="card"><h2>${x.name}</h2><p class="muted">Student ID: ${x.id} • ${x.course} • Semester ${x.semester}</p><form class="form" onsubmit="saveStudentSelf(event)"><div class="form-grid"><input id="selfEmail" value="${escapeHtml(x.email)}"><input id="selfPhone" value="${escapeHtml(x.phone)}"></div><input id="selfCampus" value="${escapeHtml(x.campus||'')}"><button class="btn btn-primary">Save profile</button></form></div><div class="card" style="margin-top:18px"><h2>Change password</h2><form class="form" onsubmit="changeStudentPassword(event)"><input id="oldPass" type="password" placeholder="Current password" required><input id="newPass" type="password" placeholder="New password" required><button class="btn btn-primary">Update password</button></form></div>`;if(s==='fees')return studentFeesV3(x);if(s==='attendance')return studentAttendance(x);if(s==='assignments')return studentAssignments(x);if(s==='results'){const r=x.results?.Sem1||{Internal:0,Theory:0,Practical:0,Grade:'Pending'};return `<div class="dash-grid"><div class="metric"><b>${r.Internal}</b><small>Internal</small></div><div class="metric"><b>${r.Theory}</b><small>Theory</small></div><div class="metric"><b>${r.Practical}</b><small>Practical</small></div><div class="metric"><b>${r.Grade}</b><small>Grade</small></div></div><div class="card"><h2>Semester 1 Result</h2><p class="muted">Published results are updated by your department teacher.</p></div>`}return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>7.8</b><small>Current CGPA</small></div><div class="metric"><b>${noticesData().length}</b><small>Published notices</small></div><div class="metric"><b>${paidTotal(x)}</b><small>Paid this session</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Welcome back</span><h2>${x.name}</h2><p class="muted">${x.course} • Semester ${x.semester} • ${x.campus||'Campus'}</p><a class="btn btn-primary" href="#/portal/student/profile">Edit profile</a></div><div class="card"><span class="kicker">Assignments</span><h2>Keep up with coursework</h2><a class="btn btn-outline" href="#/portal/student/assignments">Open assignments →</a></div></div>`}
function semesterFees(x){const base=[{sem:1,amount:12000},{sem:2,amount:11000},{sem:3,amount:12500},{sem:4,amount:11500},{sem:5,amount:13000},{sem:6,amount:12000}];return (x.course==='B.Ed.'||x.course==='D.El.Ed.')?base.map(z=>({...z,amount:z.amount-1000})):base}
function studentFeesV3(x){const d=db(),paid=x.feeLedger||{};return `<div class="fee-shell"><div class="fee-head"><div><span class="kicker">Academic Fee</span><h2>Semester-wise fee payment</h2><p class="muted">Choose the semester you want to pay. Paid semesters remain marked as paid.</p></div><div class="student-chip">${x.course} · Sem ${x.semester}</div></div><div class="fee-table"><div class="fee-row fee-header"><div>Select</div><div>Semester</div><div>Fee BreakUp</div><div>Payable</div><div>Status</div></div>${semesterFees(x).map(f=>{const isPaid=paid[f.sem]==='Paid';return `<div class="fee-row"><div><input class="fee-check" type="checkbox" data-sem="${f.sem}" data-amount="${f.amount}" ${isPaid?'disabled':''} onchange="updateFeeTotal()"></div><div><b>Semester ${f.sem}</b><small>Academic fee 2026–27</small></div><div><button class="breakup-btn" onclick="toggleFeeBreakup(this,${f.sem},${f.amount})">Show Fee BreakUp</button><div class="fee-breakup-dropdown"><div>Tuition Fee <b>₹${Math.round(f.amount*.8).toLocaleString('en-IN')}</b></div><div>Development Fee <b>₹${Math.round(f.amount*.2).toLocaleString('en-IN')}</b></div><div>Library / Student Services <b>Included</b></div></div></div><div>₹${f.amount.toLocaleString('en-IN')}</div><div><span class="tag ${isPaid?'green':'orange'}">${isPaid?'Paid':'Payable'}</span></div></div>`}).join('')}<div class="fee-total"><span>Total selected</span><strong id="feeTotal">₹0</strong></div></div><div class="pay-action-row"><label><input type="checkbox" id="partPayment"> Part Payment</label><div><span>Total</span><strong id="feeTotal2">₹0</strong></div><button class="pay-now-btn" onclick="openStudentGatewayV3()">Pay Now</button></div><div class="card paid-history"><h3>Payment history</h3>${(d.payments||[]).filter(p=>p.studentId===x.id).slice(0,8).map(p=>`<div class="payment-history-row"><span><b>${p.id}</b><small>${new Date(p.date).toLocaleString('en-IN')}</small></span><span>${p.method}</span><strong>₹${Number(p.amount||0).toLocaleString('en-IN')}</strong><span class="tag green">${p.status}</span></div>`).join('')||'<p class="muted">No payments recorded yet.</p>'}</div></div>`}
function toggleFeeBreakup(btn,sem,amount){const box=btn.parentElement.querySelector('.fee-breakup-dropdown');document.querySelectorAll('.fee-breakup-dropdown.open').forEach(x=>{if(x!==box)x.classList.remove('open')});box.classList.toggle('open')}
function updateFeeTotal(){let total=0;document.querySelectorAll('.fee-check:checked').forEach(x=>total+=Number(x.dataset.amount));const v='₹'+total.toLocaleString('en-IN');['feeTotal','feeTotal2'].forEach(id=>{const e=document.getElementById(id);if(e)e.textContent=v})}
function openStudentGatewayV3(){const checks=[...document.querySelectorAll('.fee-check:checked')];if(!checks.length){toast('Select a payable semester first.');return}const total=checks.reduce((a,x)=>a+Number(x.dataset.amount),0);window._selectedFeeSems=checks.map(x=>Number(x.dataset.sem));document.getElementById('gatewayTotal').textContent='₹'+total.toLocaleString('en-IN');document.getElementById('gatewayModal').classList.add('show');gatewayMethodV3('choose')}
function gatewayMethodV3(mode){const total=document.getElementById('gatewayTotal')?.textContent||'₹0',cfg=db().paymentConfig||{},body=document.getElementById('gatewayBody');if(!body)return;if(mode==='choose'){body.innerHTML=`<div class="new-gateway-methods"><button onclick="gatewayMethodV3('upi')"><span class="gicon">⚡</span><div><b>UPI</b><small>Pay with any UPI app</small></div><span>→</span></button><button onclick="gatewayMethodV3('card')"><span class="gicon">▣</span><div><b>Cards</b><small>Credit or debit card</small></div><span>→</span></button><button onclick="gatewayMethodV3('net')"><span class="gicon">▤</span><div><b>NetBanking</b><small>Choose your bank</small></div><span>→</span></button></div>`;return}if(mode==='upi'){body.innerHTML=`<div class="new-upi"><div class="pay-amount"><span>Amount to pay</span><strong>${total}</strong></div><div class="upi-id-box"><span>UPI ID</span><b>${cfg.upi||'shakuntalam@upi'}</b><button onclick="navigator.clipboard?.writeText('${cfg.upi||'shakuntalam@upi'}');toast('UPI ID copied')">Copy</button></div>${cfg.qr?`<img class="payment-qr" src="${cfg.qr}" alt="College QR">`:''}<div class="upi-choice"><button onclick="completeDemoPaymentV3('UPI App')">Open UPI App</button><button onclick="completeDemoPaymentV3('UPI')">I have paid</button></div><small class="muted">Demo mode: no real money is transferred.</small></div>`;return}if(mode==='card'){body.innerHTML=`<form class="new-payment-form" onsubmit="completeDemoPaymentV3('Card',event)"><h3>Card payment</h3><input placeholder="Card number" inputmode="numeric" required><div class="form-grid"><input placeholder="MM / YY" required><input placeholder="CVV" required></div><input placeholder="Cardholder name" required><button class="pay-now-btn">Pay ${total}</button></form>`;return}body.innerHTML=`<form class="new-payment-form" onsubmit="completeDemoPaymentV3('NetBanking',event)"><h3>NetBanking</h3><select required><option value="">Choose your bank</option><option>State Bank of India</option><option>HDFC Bank</option><option>ICICI Bank</option><option>Punjab National Bank</option><option>Bank of Baroda</option></select><button class="pay-now-btn">Continue to bank</button></form>`}
function completeDemoPaymentV3(method,e){if(e)e.preventDefault();const me=currentUser(),d=db(),amount=Number(String(document.getElementById('gatewayTotal')?.textContent||'0').replace(/[^0-9.]/g,'')),id='PAY-'+Date.now().toString().slice(-8);const sems=window._selectedFeeSems||[];d.payments=d.payments||[];d.payments.unshift({id,studentId:me.id,studentName:me.name,amount,method,status:'Success',date:new Date().toISOString(),semesters:sems.slice()});const st=d.students.find(x=>x.id===me.id);st.feeLedger=st.feeLedger||{};sems.forEach(s=>st.feeLedger[s]='Paid');st.fees=semesterFees(st).every(f=>st.feeLedger[f.sem]==='Paid')?'Paid':'Due';saveDB(d);closeGateway();toast(`Payment successful. Receipt ${id} saved.`);route()}
function closeGateway(){document.getElementById('gatewayModal')?.classList.remove('show')}
function paidTotal(x){return '₹'+(db().payments||[]).filter(p=>p.studentId===x.id&&p.status==='Success').reduce((a,p)=>a+Number(p.amount||0),0).toLocaleString('en-IN')}
function adminPaymentsV3(){const d=db(),payments=d.payments||[],total=payments.reduce((a,p)=>a+Number(p.amount||0),0);return `<div class="dash-grid"><div class="metric"><b>₹${total.toLocaleString('en-IN')}</b><small>Total demo collections</small></div><div class="metric"><b>${payments.length}</b><small>Successful payments</small></div><div class="metric"><b>${new Set(payments.map(p=>p.studentId)).size}</b><small>Students paid</small></div><div class="metric"><b>${d.paymentConfig?.upi||'shakuntalam@upi'}</b><small>UPI address</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Gateway configuration</span><h2>Payment settings</h2><form class="form" onsubmit="savePaymentConfig(event)"><label>UPI address<input id="cfgUpi" value="${escapeHtml(d.paymentConfig?.upi||'shakuntalam@upi')}" required></label><label>Merchant / display name<input id="cfgMerchant" value="${escapeHtml(d.paymentConfig?.merchant||'Shakuntalam College')}"></label><label>Upload new QR<input id="cfgQr" type="file" accept="image/*" onchange="previewPaymentQr(this)"></label>${d.paymentConfig?.qr?`<img id="cfgQrPreview" class="payment-qr admin-qr" src="${d.paymentConfig.qr}" alt="Current payment QR">`:'<img id="cfgQrPreview" class="payment-qr admin-qr" style="display:none">'}<button class="btn btn-primary">Save payment settings</button></form></div><div class="card"><span class="kicker">Receipts</span><h2>Student payment receipts</h2><div class="receipt-list">${payments.map(p=>`<div class="receipt-row"><div><b>${p.id}</b><span>${p.studentName||p.studentId}</span><small>${new Date(p.date).toLocaleString('en-IN')} • ${p.method}</small></div><strong>₹${Number(p.amount).toLocaleString('en-IN')}</strong><button class="btn btn-ghost" onclick="printReceipt('${p.id}')">Receipt</button></div>`).join('')||'<p class="muted">No student payments yet.</p>'}</div></div></div>`}
function savePaymentConfig(e){e.preventDefault();const d=db();d.paymentConfig=d.paymentConfig||{};d.paymentConfig.upi=document.getElementById('cfgUpi').value.trim();d.paymentConfig.merchant=document.getElementById('cfgMerchant').value.trim();if(window._newPaymentQr)d.paymentConfig.qr=window._newPaymentQr;saveDB(d);route();toast('Payment gateway settings updated.')}
function previewPaymentQr(input){const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{window._newPaymentQr=r.result;const img=document.getElementById('cfgQrPreview');if(img){img.src=r.result;img.style.display='block'}};r.readAsDataURL(f)}
function printReceipt(id){const p=(db().payments||[]).find(x=>x.id===id);if(!p)return;const w=window.open('','_blank','width=720,height=760');w.document.write(`<html><head><title>${p.id}</title><style>body{font-family:Arial;padding:40px;color:#13233a}h1{color:#064b9b}.box{border:1px solid #ddd;padding:24px;border-radius:14px}p{display:flex;justify-content:space-between}</style></head><body><h1>SHAKUNTALAM COLLEGE</h1><div class="box"><h2>Payment Receipt</h2><p><span>Receipt</span><b>${p.id}</b></p><p><span>Student</span><b>${p.studentName||p.studentId}</b></p><p><span>Method</span><b>${p.method}</b></p><p><span>Semester(s)</span><b>${(p.semesters||[]).join(', ')}</b></p><p><span>Amount</span><b>₹${Number(p.amount).toLocaleString('en-IN')}</b></p><p><span>Date</span><b>${new Date(p.date).toLocaleString('en-IN')}</b></p><p><span>Status</span><b>${p.status}</b></p></div><script>window.print()<\/script></body></html>`);w.document.close()}
function adminAttendanceV3(){const d=db(),today=todayKey(),submitted=!!attendanceDayStatus(d,today),all=d.students||[],marked=all.filter(x=>['P','A'].includes(d.attendanceLogs?.[x.id]?.[today])).length;return `<div class="card"><div class="attendance-toolbar"><div><span class="kicker">Admin Attendance Control</span><h2>Today's Student Attendance</h2><p class="muted">Admins can mark or change attendance for every student, then submit the complete day.</p></div><div class="attendance-submit-actions"><button class="btn btn-outline" ${submitted?'disabled':''} onclick="markAllAttendanceAdmin()">✓ Mark All Present</button><button class="btn btn-primary" ${submitted||marked<all.length?'disabled':''} onclick="submitAdminAttendanceToday()">Submit Attendance for Today</button></div></div><div class="attendance-submit-status ${submitted?'submitted':''}">${submitted?`✓ Attendance submitted by ${escapeHtml(attendanceDayStatus(d,today).submittedBy||'Admin')} and locked for today.`:`Daily register: <b>${marked}/${all.length}</b> students marked. Complete the register before submitting.`}</div><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Course</th><th>Overall</th><th>Today</th><th>Controls</th></tr></thead><tbody>${all.map(x=>{const st=d.attendanceLogs?.[x.id]?.[today]||'';return `<tr><td><b>${x.name}</b><br><small>${x.id}</small></td><td>${x.course}</td><td><b>${x.attendance}%</b><div class="admin-att-controls"><button onclick="adminAdjustAttendance('${x.id}',1)">+1%</button><button onclick="adminAdjustAttendance('${x.id}',-1)">−1%</button></div></td><td><span class="att-state ${st==='P'?'present':st==='A'?'absent':''}">${st||'Not marked'}</span></td><td><button class="att-action present" ${submitted?'disabled':''} onclick="setDailyAttendanceAdmin('${x.id}','P')">Present</button><button class="att-action absent" ${submitted?'disabled':''} onclick="setDailyAttendanceAdmin('${x.id}','A')">Absent</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No students found.</td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:18px"><div class="attendance-toolbar"><div><span class="kicker">Staff Attendance</span><h2>Today's Teacher Attendance</h2><p class="muted">Admins can mark teacher attendance separately.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Teacher</th><th>Department</th><th>Today</th><th>Controls</th></tr></thead><tbody>${teachers().map(t=>{const st=d.teacherAttendance?.[t.id]?.[today]||'Not marked';return `<tr><td>${t.name}</td><td>${t.department}</td><td>${st}</td><td><button class="att-action present" onclick="setTeacherAttendance('${t.id}','P')">Present</button><button class="att-action absent" onclick="setTeacherAttendance('${t.id}','A')">Absent</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function setDailyAttendanceAdmin(id,state){const d=db(),today=todayKey(),x=d.students.find(s=>s.id===id);if(!x){toast('Student not found.');return}if(d.attendanceMeta?.activeDate!==today||attendanceDayStatus(d,today)){toast("Today's attendance has already been submitted.");return}d.attendanceLogs=d.attendanceLogs||{};d.attendanceLogs[id]=d.attendanceLogs[id]||{};d.attendanceLogs[id][today]=state;recalcAttendance(x,d.attendanceLogs[id]);saveDB(d);route();toast(`${x.name}: ${state==='P'?'Present':'Absent'} for today.`)}
function markAllAttendanceAdmin(){const d=db(),today=todayKey();if(d.attendanceMeta?.activeDate!==today||attendanceDayStatus(d,today)){toast("Today's attendance is already submitted.");return}d.attendanceLogs=d.attendanceLogs||{};d.students.forEach(x=>{d.attendanceLogs[x.id]=d.attendanceLogs[x.id]||{};d.attendanceLogs[x.id][today]='P';recalcAttendance(x,d.attendanceLogs[x.id])});saveDB(d);route();toast('All students marked present for today.')} 
function submitAdminAttendanceToday(){const d=db(),today=todayKey(),all=d.students||[];if(d.attendanceMeta?.activeDate!==today){toast("Today's attendance is already closed.");return}if(all.some(x=>!['P','A'].includes(d.attendanceLogs?.[x.id]?.[today]))){toast('Please mark Present or Absent for every student before submitting.');return}d.attendanceMeta=d.attendanceMeta||{};d.attendanceMeta.submittedDates=d.attendanceMeta.submittedDates||{};const a=currentUser();d.attendanceMeta.submittedDates[today]={submittedBy:a?.name||'Administrator',role:'admin',at:new Date().toISOString()};saveDB(d);route();toast("Today's attendance submitted and locked.")} 
function setTeacherAttendance(id,state){const d=db();d.teacherAttendance=d.teacherAttendance||{};d.teacherAttendance[id]=d.teacherAttendance[id]||{};d.teacherAttendance[id][todayKey()]=state;saveDB(d);route();toast('Teacher attendance updated.')}
function adminAssignmentsV3(){return `<div class="card"><span class="kicker">Academic oversight</span><h2>Assignments</h2><p class="muted">View assignments created by teachers.</p><div class="table-wrap"><table class="table"><thead><tr><th>Title</th><th>Course</th><th>Due</th><th>Teacher</th></tr></thead><tbody>${(db().assignments||[]).map(a=>`<tr><td>${a.title}</td><td>${a.course}</td><td>${a.due}</td><td>${teachers().find(t=>t.id===a.teacherId)?.name||'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No assignments.</td></tr>'}</tbody></table></div></div>`}
function getHomeImageSlides(key,fallback,title){const home=siteConfig().homeImages||{},list=home[`${key}Slides`];return Array.isArray(list)&&list.length?list.filter(x=>x&&x.image):[{image:home[key]||fallback,title}]}
function showHomeImageSlide(key,index){const slides=getHomeImageSlides(key,key==='campus'?img.campus:img.class,key==='campus'?'A place to begin and belong':'Learning that moves beyond the classroom'),wrap=document.querySelector(`[data-home-carousel="${key}"]`);if(!wrap||!slides.length)return;const next=((Number(index)%slides.length)+slides.length)%slides.length;wrap.dataset.index=String(next);const image=wrap.querySelector('img');if(image){image.src=slides[next].image;image.alt=key==='campus'?'Shakuntalam College campus':'Students learning in a classroom'}const title=document.getElementById(key==='campus'?'homeCampusCarouselTitle':'homeClassroomCarouselTitle');if(title)title.textContent=slides[next].title|| (key==='campus'?'A place to begin and belong':'Learning that moves beyond the classroom');wrap.querySelectorAll('.home-carousel-dot').forEach((dot,i)=>dot.classList.toggle('active',i===next))}
function stepHomeImageCarousel(key,delta){const wrap=document.querySelector(`[data-home-carousel="${key}"]`);if(!wrap)return;showHomeImageSlide(key,Number(wrap.dataset.index||0)+Number(delta))}
function startHomeImageCarousels(){window._homeImageCarouselTimers=window._homeImageCarouselTimers||{};['campus','classroom'].forEach(key=>{clearInterval(window._homeImageCarouselTimers[key]);const wrap=document.querySelector(`[data-home-carousel="${key}"]`);if(!wrap)return;const slides=getHomeImageSlides(key,key==='campus'?img.campus:img.class,key==='campus'?'A place to begin and belong':'Learning that moves beyond the classroom');if(slides.length>1)window._homeImageCarouselTimers[key]=setInterval(()=>stepHomeImageCarousel(key,1),5000)})}
function homepageImageEditor(s){const slots=[['campus','Education with purpose',img.campus,'A place to begin and belong'],['classroom','Learning, practice and progress',img.class,'Learning that moves beyond the classroom']];return `<div class="builder-section homepage-carousel-section"><div class="homepage-carousel-section-head"><div><span class="kicker">Homepage imagery</span><h3>Photo carousels</h3><p class="muted">Add and arrange photos for each feature section. Every image is cropped to 4:3.</p></div><span class="carousel-count-chip">2 carousels</span></div><div class="homepage-carousel-editor-grid">${slots.map(([key,label,fallback,defaultTitle])=>{const slides=getHomeImageSlides(key,fallback,defaultTitle);return `<article class="home-carousel-editor"><header class="home-carousel-editor-head"><div><span class="kicker">${key==='campus'?'01':'02'} · Homepage section</span><h4>${label}</h4></div><span class="home-slide-count">${slides.length} photo${slides.length===1?'':'s'}</span></header><div class="home-carousel-slides">${slides.map((slide,i)=>`<div class="home-carousel-admin-row"><div class="home-carousel-thumb"><img src="${slide.image}" alt="${label} photo ${i+1}"><span>PHOTO ${String(i+1).padStart(2,'0')}</span></div><div class="home-carousel-fields"><label>Caption<input value="${escapeHtml(slide.title||defaultTitle)}" data-home-slide-title="${key}:${i}" placeholder="Photo caption"></label><label class="home-carousel-upload">Replace photo <small>4:3 crop</small><input type="file" accept="image/*" onchange="openSiteImageCropper(this,'home-replace-${key}','${i}',4/3)"></label></div><button type="button" class="home-carousel-remove" aria-label="Remove ${label} photo ${i+1}" onclick="removeHomeImageSlide('${key}',${i});return false" ${slides.length<=1?'disabled':''}>×</button></div>`).join('')}</div><label class="home-carousel-add">＋ Add photos<input type="file" accept="image/*" multiple onchange="openSiteImageCropper(this,'home-add-${key}','',4/3)"><small>Select one or more images · crop before saving</small></label></article>`}).join('')}</div><article class="about-page-image-editor"><div><span class="kicker">About page image</span><h4>Feature photo</h4><p class="muted">Change the large campus photo shown on the About page. Crop to 4:3 before publishing.</p><img class="about-page-admin-preview" src="${escapeHtml(s.aboutPageImage||img.campus)}" alt="Current About page photo"></div><label class="home-carousel-upload">Replace photo <small>4:3 crop</small><input type="file" accept="image/*" onchange="openSiteImageCropper(this,'about-page','',4/3)"></label></article></div></div>`}

function leadershipPhotoEditor(s){const photos=s.leadershipImages||{};return `<div class="builder-section leadership-photo-editor"><div class="builder-section-intro"><span class="kicker">Leadership pages</span><h3>Founder &amp; Secretary portraits</h3><p class="muted">Upload square portraits for the Founder Desk and Secretary Desk. Crop with the gridlines before saving.</p></div><div class="leadership-photo-admin-grid">${[['secretary','Secretary','Anil Kumar Singh','AS'],['founder','Founder','Siyaram Singh','SS']].map(([key,label,name,initials])=>`<article class="leadership-photo-admin-card"><div class="leadership-photo-admin-preview">${photos[key]||(key==='founder'?'assets/founder-portrait-default.png':key==='secretary'?'assets/secretary-portrait-default.png':'')?`<img src="${photos[key]||(key==='founder'?'assets/founder-portrait-default.png':key==='secretary'?'assets/secretary-portrait-default.png':'')}" alt="${label} portrait">`:`<span>${initials}</span>`}</div><div><span class="kicker">${label} Desk</span><h4>${name}</h4><label class="home-carousel-upload">${photos[key]||['founder','secretary'].includes(key)?'Replace portrait':'Add portrait'} <small>Square crop · gridlines</small><input type="file" accept="image/*" onchange="openSiteImageCropper(this,'leadership-${key}','',1)"></label></div></article>`).join('')}</div></div>`}
function websiteBuilder(){const s=siteConfig(),slides=Array.isArray(s.heroSlides)?s.heroSlides:[],ribbon=s.ribbonText||'ADMISSIONS 2026–27';return `<div class="card website-ribbon-card"><div><span class="kicker">Homepage announcement</span><h2>Top ribbon message</h2><p class="muted">Edit the scrolling announcement shown above the public website header.</p></div><form class="form" onsubmit="savePortalRibbon(event)"><label>Ribbon text<input id="portalRibbonText" maxlength="120" value="${escapeHtml(ribbon)}" placeholder="Admissions 2026–27 • Applications open" oninput="document.getElementById('websiteRibbonPreview').textContent=this.value"></label><div class="ribbon-preview"><span id="websiteRibbonPreview">${escapeHtml(ribbon)}</span><small>Live preview</small></div><button class="btn btn-primary">Save &amp; Publish Ribbon</button></form></div><div class="builder-v3"><div class="builder-panel builder-editor-only"><div class="builder-head"><div><span class="kicker">Visual editor</span><h2>Homepage Visual Builder</h2><p class="muted">Manage homepage photos and hero content from one editing panel.</p></div><span class="builder-head-mark">✦</span></div><div class="builder-section"><div class="builder-section-intro"><span class="kicker">01 · Main banner</span><h3>Hero image carousel</h3><p class="muted">These images rotate automatically on the homepage. Replace, add, or remove slides; crop each photo to 4:3.</p></div><div class="hero-slide-admin">${slides.map((x,i)=>`<article class="hero-slide-admin-row"><div class="hero-slide-thumb"><img src="${x.image}" alt="Hero slide ${i+1}"><span>SLIDE ${String(i+1).padStart(2,'0')}</span></div><div class="hero-slide-fields"><label>Slide caption<input value="${escapeHtml(x.title||'') }" data-hero-title="${i}" placeholder="Add a short caption"></label><label class="hero-slide-upload">Replace photo <small>4:3 crop</small><input type="file" accept="image/*" onchange="openSiteImageCropper(this,'hero-replace','${i}',4/3)"></label></div><button type="button" class="home-carousel-remove" aria-label="Remove hero slide ${i+1}" onclick="removeHeroSlideV5(${i});return false" ${slides.length<=1?'disabled':''}>×</button></article>`).join('')}</div><label class="home-carousel-add hero-carousel-add">＋ Add hero photos<input type="file" accept="image/*" multiple onchange="openSiteImageCropper(this,'hero-add','',4/3)"><small>Select one or more images · crop before saving</small></label></div>${homepageImageEditor(s)}${leadershipPhotoEditor(s)}<div class="builder-section hero-content-section"><div class="builder-section-intro"><span class="kicker">02 · Homepage message</span><h3>Hero content</h3><p class="muted">Set the heading and supporting text displayed beside the main banner.</p></div><label>Hero heading<input id="wbHeroTitle" value="${escapeHtml(s.heroTitle||'')}"></label><label>Hero description<textarea id="wbHeroText" rows="4">${escapeHtml(s.heroText||'')}</textarea></label><button class="btn btn-primary" onclick="publishSiteV5()">Save &amp; Publish Homepage</button></div></div></div>`}
function persistHeroSlidesV5(){const d=db(),site=d.site||siteDefaults();site.heroSlides=(site.heroSlides||[]).filter(x=>x&&x.image);if(!site.heroSlides.length)site.heroSlides=[{image:img.hero,title:'Academic Session 2026–27'}];site.heroImage=site.heroSlides[0].image;d.site=site;saveDB(d)}
function openSiteImageCropper(input,target,key,ratio){const files=[...(input.files||[])];input.value='';if(!files.length)return;window._siteCropQueue={files,target,key,ratio:Number(ratio)||4/3,index:0};siteCropLoadCurrent()}
function siteCropLoadCurrent(){const q=window._siteCropQueue;if(!q||q.index>=q.files.length){siteCropClose();return}const file=q.files[q.index];const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const stageW=480,stageH=Math.round(stageW/q.ratio);window._siteCropState={image,stageW,stageH,zoom:1,offsetX:0,offsetY:0,drag:null};siteCropRender()};image.onerror=()=>{toast('This image could not be opened.');siteCropClose()};image.src=reader.result};reader.readAsDataURL(file)}
function siteCropRender(){const state=window._siteCropState;if(!state)return;let modal=document.getElementById('siteImageCropModal');if(!modal){modal=document.createElement('div');modal.id='siteImageCropModal';modal.className='site-crop-overlay';document.body.appendChild(modal)}const q=window._siteCropQueue,file=q.files[q.index];modal.innerHTML=`<div class="site-crop-dialog" role="dialog" aria-modal="true" aria-labelledby="siteCropTitle"><div class="site-crop-head"><div><span class="kicker">Image crop</span><h2 id="siteCropTitle">Adjust image before saving</h2><p>${escapeHtml(file.name)} · ${q.index+1} of ${q.files.length} · ${q.ratio===4/3?'Crop area · 4:3':`Crop area · ${q.ratio.toFixed(2)}:1`}</p></div><button type="button" class="close" onclick="siteCropClose()" aria-label="Cancel crop">×</button></div><div class="site-crop-stage-wrap"><canvas id="siteCropCanvas" width="${state.stageW}" height="${state.stageH}" style="aspect-ratio:${state.stageW}/${state.stageH}"></canvas>${q.target.startsWith('leadership-')?'<div class="site-crop-grid" aria-hidden="true"></div>':''}</div><div id="siteCropError" class="site-crop-error" role="alert" hidden></div><div class="site-crop-controls"><label>Zoom <input type="range" min="1" max="3" step="0.01" value="${state.zoom}" oninput="siteCropZoom(this.value)"></label><small>Drag the image to reposition it inside the frame.</small></div><div class="site-crop-actions"><button class="btn btn-ghost" onclick="siteCropClose()">Cancel</button><button class="btn btn-primary" onclick="siteCropSave()">${q.index+1<q.files.length?'Crop &amp; Next':'Crop &amp; Save'}</button></div></div>`;const canvas=modal.querySelector('canvas');canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);state.drag={x:e.clientX,y:e.clientY,ox:state.offsetX,oy:state.offsetY}};canvas.onpointermove=e=>{if(!state.drag)return;const box=canvas.getBoundingClientRect(),factor=state.stageW/box.width;state.offsetX=state.drag.ox+(e.clientX-state.drag.x)*factor;state.offsetY=state.drag.oy+(e.clientY-state.drag.y)*factor;siteCropDraw()};canvas.onpointerup=canvas.onpointercancel=()=>{state.drag=null};siteCropDraw()}
function siteCropDraw(){const s=window._siteCropState;if(!s)return;const c=document.getElementById('siteCropCanvas');if(!c)return;const ctx=c.getContext('2d'),scale=Math.max(s.stageW/s.image.naturalWidth,s.stageH/s.image.naturalHeight)*s.zoom,w=s.image.naturalWidth*scale,h=s.image.naturalHeight*scale;s.offsetX=Math.min(0,Math.max(s.stageW-w,s.offsetX));s.offsetY=Math.min(0,Math.max(s.stageH-h,s.offsetY));ctx.clearRect(0,0,s.stageW,s.stageH);ctx.drawImage(s.image,s.offsetX,s.offsetY,w,h)}
function siteCropZoom(value){const s=window._siteCropState;if(!s)return;const old=Math.max(s.stageW/s.image.naturalWidth,s.stageH/s.image.naturalHeight)*s.zoom,centerX=s.stageW/2,centerY=s.stageH/2,sourceX=(centerX-s.offsetX)/old,sourceY=(centerY-s.offsetY)/old;s.zoom=Number(value);const scale=Math.max(s.stageW/s.image.naturalWidth,s.stageH/s.image.naturalHeight)*s.zoom;s.offsetX=centerX-sourceX*scale;s.offsetY=centerY-sourceY*scale;siteCropDraw()}
async function siteCropSave(){const s=window._siteCropState,q=window._siteCropQueue;if(!s||!q)return;const scale=Math.max(s.stageW/s.image.naturalWidth,s.stageH/s.image.naturalHeight)*s.zoom,sx=-s.offsetX/scale,sy=-s.offsetY/scale,sw=s.stageW/scale,sh=s.stageH/scale,out=document.createElement('canvas'),outW=720,outH=Math.round(outW/q.ratio);out.width=outW;out.height=outH;out.getContext('2d').drawImage(s.image,sx,sy,sw,sh,0,0,outW,outH);const data=out.toDataURL('image/webp',.68);try{const site=siteConfig();let saveResult;if(q.target.startsWith('leadership-')){const person=q.target.slice('leadership-'.length);site.leadershipImages=site.leadershipImages||{};site.leadershipImages[person]=data;saveResult=saveSite(site)}else if(q.target==='about-page'){site.aboutPageImage=data;saveResult=saveSite(site)}else if(q.target==='home'){site.homeImages=site.homeImages||{};site.homeImages[q.key]=data;saveResult=saveSite(site)}else if(q.target.startsWith('home-add-')||q.target.startsWith('home-replace-')){const key=q.target.includes('campus')?'campus':'classroom',slidesKey=`${key}Slides`;site.homeImages=site.homeImages||{};site.homeImages[slidesKey]=Array.isArray(site.homeImages[slidesKey])?site.homeImages[slidesKey]:[{image:site.homeImages[key]||(key==='campus'?img.campus:img.class),title:key==='campus'?'A place to begin and belong':'Learning that moves beyond the classroom'}];if(q.target.startsWith('home-replace-')){const i=Number(q.key);if(site.homeImages[slidesKey][i])site.homeImages[slidesKey][i].image=data}else site.homeImages[slidesKey].push({image:data,title:`${key==='campus'?'Campus':'Learning'} photo ${site.homeImages[slidesKey].length+1}`});site.homeImages[key]=site.homeImages[slidesKey][0].image;saveResult=saveSite(site)}else{site.heroSlides=Array.isArray(site.heroSlides)?site.heroSlides:[];if(q.target==='hero-replace'){const i=Number(q.key);if(site.heroSlides[i])site.heroSlides[i].image=data}else site.heroSlides.push({image:data,title:`Campus highlight ${site.heroSlides.length+1}`});site.heroImage=site.heroSlides[0]?.image||data;saveResult=saveSite(site)}}catch(error){const message=error?.name==='QuotaExceededError'?'Browser storage is full. Remove older or larger uploads, then try this photo again.':'The photo could not be saved. Try another image or a smaller file.';siteCropShowError(message);return}if(saveResult===false){const compacted=await window._dbImageCompaction;if(!compacted){siteCropShowError('Storage is still full after compressing saved photos. Remove older gallery or carousel images, then try again.');return}}q.index++;if(q.index<q.files.length){siteCropLoadCurrent();return}const target=q.target;window._siteCropQueue=null;window._siteCropState=null;siteCropClose();route();toast(target.startsWith('leadership-')?'Leadership portrait cropped and saved.':target==='about-page'?'About page image cropped and saved.':target.startsWith('home-')?'Homepage carousel image cropped and saved.':target==='home'?'Homepage image cropped and saved.':target==='hero-replace'?'Hero image cropped and replaced.':'Hero images cropped and added.')}
function siteCropShowError(message){const el=document.getElementById('siteCropError');if(el){el.textContent=message;el.hidden=false}}
function siteCropClose(){document.getElementById('siteImageCropModal')?.remove();window._siteCropQueue=null;window._siteCropState=null}
function readHeroFileAs34(file,done){const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const tw=900,th=1200,srcRatio=im.width/im.height,target=tw/th;let sw,sh,sx,sy;if(srcRatio>target){sh=im.height;sw=Math.round(sh*target);sx=Math.round((im.width-sw)/2);sy=0}else{sw=im.width;sh=Math.round(sw/target);sx=0;sy=Math.round((im.height-sh)/2)}const c=document.createElement('canvas');c.width=tw;c.height=th;const ctx=c.getContext('2d');ctx.drawImage(im,sx,sy,sw,sh,0,0,tw,th);done(c.toDataURL('image/jpeg',.9))};im.src=r.result};r.readAsDataURL(file)}
function addHeroSlidesV5(input){const files=[...(input.files||[])];if(!files.length)return;const site=siteConfig();site.heroSlides=Array.isArray(site.heroSlides)?site.heroSlides:[];let left=files.length;files.forEach((file)=>readHeroFileAs34(file,data=>{site.heroSlides.push({image:data,title:`Campus highlight ${site.heroSlides.length+1}`});left--;if(left===0){saveSite(site);route();toast(`${files.length} hero image${files.length>1?'s':''} added and cropped to 3:4.`)}}));input.value=''}
function replaceHeroSlideV5(input,index){const file=input.files?.[0];if(!file)return;readHeroFileAs34(file,data=>{const site=siteConfig();site.heroSlides=site.heroSlides||[];if(site.heroSlides[index])site.heroSlides[index].image=data;saveSite(site);route();toast('Hero image replaced and cropped to 3:4.');})}
function removeHeroSlideV5(index){const d=db(),site=d.site||(d.site=siteDefaults()),slides=Array.isArray(site.heroSlides)?site.heroSlides:[],i=Number(index);if(!Number.isInteger(i)||i<0||i>=slides.length)return;if(slides.length<=1){toast('Keep at least one hero image.');return}slides.splice(i,1);site.heroSlides=slides;site.heroImage=slides[0]?.image||img.hero;d.site=site;saveDB(d);window._heroCarouselIndex=0;route();toast('Hero image removed.')}
function removeHomeImageSlide(key,index){const site=siteConfig(),home=site.homeImages||(site.homeImages={}),slidesKey=`${key}Slides`,slides=Array.isArray(home[slidesKey])?home[slidesKey]:[{image:home[key]||(key==='campus'?img.campus:img.class),title:key==='campus'?'A place to begin and belong':'Learning that moves beyond the classroom'}],i=Number(index);if(!Number.isInteger(i)||i<0||i>=slides.length)return;if(slides.length<=1){toast('Keep at least one image in this carousel.');return}slides.splice(i,1);home[slidesKey]=slides;home[key]=slides[0].image;saveSite(site);route();toast('Homepage carousel image removed.')}
function publishSiteV5(){const site=siteConfig();site.heroTitle=document.getElementById('wbHeroTitle')?.value||site.heroTitle;site.heroText=document.getElementById('wbHeroText')?.value||site.heroText;site.primary=document.getElementById('wbPrimary')?.value||site.primary;site.accent=document.getElementById('wbAccent')?.value||site.accent;document.querySelectorAll('[data-hero-title]').forEach(el=>{const i=Number(el.dataset.heroTitle);if(site.heroSlides?.[i])site.heroSlides[i].title=el.value.trim()||`Campus highlight ${i+1}`});site.homeImages=site.homeImages||{};document.querySelectorAll('[data-home-slide-title]').forEach(el=>{const [key,indexText]=el.dataset.homeSlideTitle.split(':');const i=Number(indexText),slides=site.homeImages[`${key}Slides`];if(Array.isArray(slides)&&slides[i])slides[i].title=el.value.trim()||`${key==='campus'?'Campus':'Learning'} photo ${i+1}`});site.heroImage=site.heroSlides?.[0]?.image||site.heroImage||img.hero;saveSite(site);route();toast('Homepage hero carousel and content published.')}
function publishSiteV4(){const s=siteConfig();s.heroTitle=document.getElementById('wbHeroTitle').value;s.heroText=document.getElementById('wbHeroText').value;s.primary=document.getElementById('wbPrimary').value;s.accent=document.getElementById('wbAccent').value;saveSite(s);route();toast('Homepage content and theme saved.');}
function home(){const s=siteConfig(),im=s.homeImages||{},campusSlides=getHomeImageSlides('campus',img.campus,'A place to begin and belong'),classroomSlides=getHomeImageSlides('classroom',img.class,'Learning that moves beyond the classroom');return layout(`<main><section class="hero hero-brand"><div class="container hero-grid"><div class="hero-copy"><h1>${escapeHtml(s.heroTitle||'KNOWLEDGE. CHARACTER. OPPORTUNITY.')}</h1><p>${escapeHtml(s.heroText||'')}</p><div class="hero-actions"><a class="btn btn-gold" href="#/admissions">Apply for Admission →</a><a class="btn btn-light-outline" href="#/departments">Explore Departments</a></div></div><div class="hero-card"><button class="hero-arrow hero-prev" type="button" aria-label="Previous hero image" onclick="nextHeroSlideV7(-1)">‹</button><img id="heroCarouselImage" src="${(s.heroSlides?.[0]?.image)||im.hero||s.heroImage||img.hero}" alt="Shakuntalam College"><button class="hero-arrow hero-next" type="button" aria-label="Next hero image" onclick="nextHeroSlideV7(1)">›</button><div class="hero-card-caption"><b>${escapeHtml(s.heroSlides?.[0]?.title||'Shakuntalam College')}</b></div></div></div></section><section class="section menu-section"><div class="container"><div class="section-head"><div><span class="kicker">College information</span><h2>Explore every part of Shakuntalam College.</h2></div><p>Admissions, academics, departments, examination, infrastructure, events, notices and student services.</p></div><div class="mega-links">${[['Admission','Admissions, eligibility and application.','01','/admissions'],['Administration','Leadership, offices and institutional services.','02','/administration'],['Academics','Programs, assessment and support.','03','/academics'],['Department','Teacher Education, Management and Industrial Training.','04','/departments'],['Centre & Cell','Student welfare and support cells.','05','/centre-cell'],['Examination','Schedules, assessment and results.','06','/examination'],['Notice','Latest academic announcements.','07','/notices'],['Infrastructure','Library, labs, workshops and facilities.','08','/infrastructure'],['Events','Seminars, workshops and campus activities.','09','/events'],['Students Zone','Portal, fees, attendance, results and notices.','10','/students-zone']].map(x=>`<a class="mega-link" href="#${x[3]}"><span class="mega-no">${x[2]}</span><span><b>${x[0]}</b><small>${x[1]}</small></span><span>→</span></a>`).join('')}</div></div></section><section class="section home-feature home-purpose"><div class="container two-col home-feature-grid"><div class="home-feature-copy"><span class="kicker">About Shakuntalam</span><h2>Education with purpose.</h2><p class="lead">A connected academic environment for teacher education, management, computing and industrial skills.</p><p>Founded by Devi Shakuntalam Pratishthan in 2009, Shakuntalam brings learning and practical preparation together. Students are encouraged to build strong subject knowledge, confidence and a sense of responsibility as they prepare for their next step.</p><div class="home-feature-points"><div><b>01</b><span><strong>Learn with direction</strong><small>Explore programs shaped around knowledge, practice and opportunity.</small></span></div><div><b>02</b><span><strong>Grow with guidance</strong><small>Develop through faculty support and a welcoming learning community.</small></span></div></div><a class="btn btn-outline" href="#/about">Discover our story →</a></div><figure class="home-feature-visual"><div class="home-feature-carousel-frame" data-home-carousel="campus"><img class="home-image" id="homeCampusCarouselImage" src="${campusSlides[0].image}" alt="Shakuntalam College campus"><button type="button" class="home-carousel-arrow previous" aria-label="Previous campus image" onclick="stepHomeImageCarousel('campus',-1)">‹</button><button type="button" class="home-carousel-arrow next" aria-label="Next campus image" onclick="stepHomeImageCarousel('campus',1)">›</button><div class="home-carousel-dots">${campusSlides.map((_,i)=>`<button type="button" class="home-carousel-dot ${i===0?'active':''}" aria-label="Show campus image ${i+1}" onclick="showHomeImageSlide('campus',${i})"></button>`).join('')}</div></div><figcaption class="home-feature-caption"><b id="homeCampusCarouselTitle">${escapeHtml(campusSlides[0].title||'A place to begin and belong')}</b><span id="homeCampusCarouselCopy">Building opportunities for learners in Sasaram, Bihar.</span></figcaption></figure></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Latest notices</span><h2>Notice board</h2></div><a class="btn btn-outline" href="#/notices">All notices</a></div><div class="notice-list">${noticesData().slice(0,5).map((n,i)=>noticeCard(n,i)).join('')}</div></div></section><section class="section home-feature home-experience"><div class="container two-col home-feature-grid"><figure class="home-feature-visual"><div class="home-feature-carousel-frame" data-home-carousel="classroom"><img class="home-image" id="homeClassroomCarouselImage" src="${classroomSlides[0].image}" alt="Students learning in a classroom"><button type="button" class="home-carousel-arrow previous" aria-label="Previous classroom image" onclick="stepHomeImageCarousel('classroom',-1)">‹</button><button type="button" class="home-carousel-arrow next" aria-label="Next classroom image" onclick="stepHomeImageCarousel('classroom',1)">›</button><div class="home-carousel-dots">${classroomSlides.map((_,i)=>`<button type="button" class="home-carousel-dot ${i===0?'active':''}" aria-label="Show classroom image ${i+1}" onclick="showHomeImageSlide('classroom',${i})"></button>`).join('')}</div></div><figcaption class="home-feature-caption"><b id="homeClassroomCarouselTitle">${escapeHtml(classroomSlides[0].title||'Learning that moves beyond the classroom')}</b><span id="homeClassroomCarouselCopy">Build understanding through teaching, discussion and practical work.</span></figcaption></figure><div class="home-feature-copy"><span class="kicker">Student experience</span><h2>Learning, practice and progress.</h2><p class="lead">Make the most of college life with academic guidance, practical experiences and student services that support your progress.</p><p>From assignments and attendance to semester results and notices, the student portal brings essential information together. In the classroom, workshops and campus community, learners can strengthen their skills and take an active role in their education.</p><div class="home-experience-points"><span><b>Academic support</b><small>Programs, assignments and semester information</small></span><span><b>Practical learning</b><small>Classroom, workshop and collaborative experiences</small></span><span><b>Student services</b><small>Attendance, results, notices and portal access</small></span></div><a class="btn btn-primary" href="#/students-zone">Explore Students Zone →</a></div></div></section><section class="section programs-section"><div class="container"><div class="section-head homepage-section-head"><div><span class="kicker">Study at Shakuntalam</span><h2>Find the course that moves you forward.</h2><p>Explore our departments and programs. Course progression is organized by department, course and semester.</p></div></div><div class="program-grid-ref"><article class="program-card-ref"><span class="program-badge-ref">NCTE · VKSU</span><h3>Department of Teachers Education</h3><p>Prepare to inspire the next generation through thoughtful, practice-based teacher education.</p><small>B.Ed. · D.El.Ed.</small><a href="#/department/teachers-education">Explore department →</a></article><article class="program-card-ref"><span class="program-badge-ref">AICTE · VKSU</span><h3>Department of Management</h3><p>Build business acumen, digital confidence and the communication skills employers value.</p><small>BBA · BCA</small><a href="#/department/management">Explore department →</a></article><article class="program-card-ref"><span class="program-badge-ref">NCVT</span><h3>Department of Industrial Training</h3><p>Learn in-demand technical skills through workshop practice and career-oriented training.</p><small>Electrician · Fitter</small><a href="#/department/industrial-training">Explore department →</a></article><article class="program-card-ref"><span class="program-badge-ref upcoming">Upcoming</span><h3>Department of Nursing Education</h3><p>A new pathway in compassionate, practical nursing education is on the horizon.</p><small>ANM · Coming soon</small><a href="#/contact">Stay informed →</a></article></div><p class="recognition-note">BBA &amp; BCA recognized by AICTE &amp; NCTE and affiliated to VKSU, Ara. B.Ed. affiliated to VKSU, Ara; D.El.Ed. affiliated to Bihar Board, Patna and recognized by NCTE, ERC Bhubaneswar.</p></div></section><section class="section story-section"><div class="container"><span class="kicker">Our foundation</span><h2>Rooted in values.<br>Ready for tomorrow.</h2><p>Founded by Devi Shakuntalam Pratisthan in 2009, Shakuntalam College is a growing educational community committed to opportunity, practical learning and personal growth. Across our three campuses, students are encouraged to think boldly and contribute meaningfully.</p><p>From teacher education and management to skilled technical training, our programs connect classroom learning with the world beyond it.</p><div class="story-values"><b>✓ &nbsp; Experienced faculty</b><b>✓ &nbsp; Practical learning</b><b>✓ &nbsp; Supportive community</b><b>✓ &nbsp; Industry-focused skills</b></div></div></section><section class="section authority-section"><div class="container"><div class="section-head homepage-section-head"><div><span class="kicker">Official education authorities</span><h2>Education Authorities &amp; Affiliations</h2><p>Explore the universities, regulatory councils and education boards that recognize, regulate or affiliate our programmes.</p></div></div><div class="authority-grid"><a class="authority-card" href="https://www.ugc.gov.in/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>UGC</span><img src="${im.ugc||'https://en.wikipedia.org/wiki/Special:FilePath/UGC_India_Logo.png'}" alt="UGC logo" loading="lazy" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></span><strong>University Grants Commission</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://vksuexams.com/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>VKSU</span><img src="${im.vksu||'assets/vksu-logo.png'}" alt="Veer Kunwar Singh University logo" loading="lazy" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></span><strong>Veer Kunwar Singh University</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://www.aicte.gov.in/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>AICTE</span><img src="${im.aicte||'https://www.dypatilonline.com/images/logo/aicte.png'}" alt="AICTE logo" loading="lazy" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></span><strong>All India Council for Technical Education</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://par.ncte.gov.in/website/index.aspx" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>NCTE</span><img src="${im.ncte||'https://eastwestedu.org/bed/admin/uploads/affiliation_image/1.jpg'}" alt="NCTE logo" loading="lazy" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></span><strong>National Council for Teacher Education</strong><small>Visit official website ↗</small></a><a class="authority-card" href="https://www.biharboardonline.org/" target="_blank" rel="noopener noreferrer"><span class="authority-mark"><span class="authority-fallback" hidden>BSEB</span><img src="${im.bseb||'https://en.wikipedia.org/wiki/Special:FilePath/BSEB_LOGO.svg'}" alt="BSEB logo" loading="lazy" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></span><strong>Bihar School Examination Board</strong><small>Visit official website ↗</small></a></div></div></section></main>`) }
function studentContent(s){const me=currentUser(),x=students().find(a=>a.id===me?.id)||me;if(/^result-\d+$/.test(s))return studentResultsPage(x,Number(s.split('-')[1]));if(s==='profile')return studentProfileV4(x);if(s==='fees')return studentFeesV3(x);if(s==='attendance')return studentAttendance(x);if(s==='assignments')return studentAssignments(x);if(s==='notices')return studentNotices();if(s==='results')return studentResultsHub(x);return `<div class="dash-grid"><div class="metric"><b>${x.attendance}%</b><small>Overall attendance</small></div><div class="metric"><b>${noticesData().length}</b><small>College notices</small></div><div class="metric"><b>${paidTotal(x)}</b><small>Paid this session</small></div><div class="metric"><b>${todaySubjectNotice(x).length}</b><small>Absence alerts today</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Welcome back</span><h2>${escapeHtml(x.name)}</h2><p class="muted">${escapeHtml(x.course)} · Semester ${x.semester} · Section ${escapeHtml(x.section||'A')}</p><a class="btn btn-primary" href="#/portal/student/profile">Open Profile →</a></div><div class="card"><span class="kicker">Notice centre</span><h2>${todaySubjectNotice(x).length?'Attendance alert':'No attendance alert'}</h2><a class="btn btn-outline" href="#/portal/student/notices">Open Notices →</a></div></div>`}
function teacherContent(s){const t=currentTeacher(),mine=students().filter(x=>allowedCourses(t).includes(x.course));if(s==='profile')return teacherProfileV4(t);if(s==='attendance')return teacherAttendance();if(s==='students')return `<div class="card"><h2>My Department Students</h2><p class="muted">Only students from <b>${escapeHtml(t?.department||'your department')}</b> are shown.</p><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Course</th><th>Semester</th><th>Attendance</th></tr></thead><tbody>${mine.map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.course)}</td><td>${x.semester}</td><td>${x.attendance}%</td></tr>`).join('')}</tbody></table></div></div>`;if(s==='assignments')return teacherAssignmentsV3(mine);if(s==='results')return teacherResults(mine);return `<div class="dash-grid"><div class="metric"><b>${mine.length}</b><small>Department students</small></div><div class="metric"><b>${Math.round(mine.reduce((a,x)=>a+x.attendance,0)/(mine.length||1))}%</b><small>Department attendance</small></div><div class="metric"><b>${assignmentsForTeacher(t).length}</b><small>Assignments</small></div><div class="metric"><b>${todayKey()}</b><small>Attendance date</small></div></div><div class="feature-grid"><div class="card"><h2>Subject Attendance</h2><p>Submit each subject once. Submitted teacher attendance is locked.</p><a class="btn btn-primary" href="#/portal/teacher/attendance">Open Attendance →</a></div><div class="card"><h2>Faculty Profile</h2><p>Maintain your faculty details and photo.</p><a class="btn btn-outline" href="#/portal/teacher/profile">Open Profile →</a></div></div>`}
function side(role,active){const items=role==='admin'?['dashboard','students','teachers','admins','admissions','events','website','attendance','assignments','notices','payments','settings']:role==='teacher'?['dashboard','profile','attendance','assignments','results']:['dashboard','profile','attendance','fees','assignments','results','notices'];return `<aside class="side portal-sidebar-${role}"><div class="side-orb orb-a"></div><div class="side-orb orb-b"></div><a class="brand" href="#/"><img class="brand-logo" src="${_finalLogo}" alt="logo"><span class="brand-copy"><strong>SHAKUNTALAM</strong><small>COLLEGE</small><em>ESTD 2009</em></span></a><nav>${items.map(i=>`<a class="${i===active?'active':''}" href="#/portal/${role}/${i}"><span class="side-icon">${icon(i)}</span><span>${titleCase(i)}</span></a>`).join('')}</nav><div class="side-clock">${currentDateLabel()}<br><b id="portalClock">${new Date().toLocaleTimeString('en-IN')}</b></div><button class="btn btn-ghost side-signout" onclick="clearSession();location.hash='/'">↪ Sign out</button></aside>`}
function adminPaymentsV3(){const d=db(),payments=d.payments||[],cfg=d.paymentConfig||{},fees=cfg.semesterFees||{};return `<div class="dash-grid"><div class="metric"><b>₹${payments.reduce((a,p)=>a+Number(p.amount||0),0).toLocaleString('en-IN')}</b><small>Total collections</small></div><div class="metric"><b>${payments.length}</b><small>Transactions</small></div><div class="metric"><b>${escapeHtml(cfg.upi||'shakuntalam@upi')}</b><small>Active UPI</small></div><div class="metric"><b>Editable</b><small>Payable fees</small></div></div><div class="feature-grid"><div class="card"><span class="kicker">Gateway</span><h2>Payment settings</h2><form class="form" onsubmit="savePaymentConfig(event)"><label>UPI address<input id="cfgUpi" value="${escapeHtml(cfg.upi||'shakuntalam@upi')}" required></label><label>Merchant name<input id="cfgMerchant" value="${escapeHtml(cfg.merchant||'Shakuntalam College')}"></label><label>QR image<input id="cfgQr" type="file" accept="image/*" onchange="previewPaymentQr(this)"></label>${cfg.qr?`<img id="cfgQrPreview" class="payment-qr admin-qr" src="${cfg.qr}">`:'<img id="cfgQrPreview" class="payment-qr admin-qr" style="display:none">'}<button class="btn btn-primary">Save Gateway</button></form></div><div class="card"><span class="kicker">Semester Fees</span><h2>Edit payable amount</h2><form class="form" onsubmit="saveFeeAmounts(event)">${depts.map(c=>`<div class="fee-config-course"><b>${escapeHtml(c)}</b><div class="form-grid">${(fees[c]||[0,0,0,0,0,0]).map((v,i)=>`<label>Sem ${i+1}<input type="number" min="0" id="fee_${slug(c)}_${i+1}" value="${Number(v)||0}"></label>`).join('')}</div></div>`).join('')}<button class="btn btn-primary">Save Payable Fees</button></form></div></div><div class="card" style="margin-top:18px"><h2>Payment receipts</h2><div class="receipt-list">${payments.map(p=>`<div class="receipt-row"><div><b>${escapeHtml(p.id)}</b><span>${escapeHtml(p.studentName||p.studentId)}</span><small>${new Date(p.date).toLocaleString('en-IN')} · ${escapeHtml(p.method)}</small></div><strong>₹${Number(p.amount||0).toLocaleString('en-IN')}</strong><button class="btn btn-ghost" onclick="printReceipt('${p.id}')">Receipt</button></div>`).join('')||'<p class="muted">No payments yet.</p>'}</div></div>`}
function saveFeeAmounts(e){e.preventDefault();const d=db();d.paymentConfig=d.paymentConfig||{};d.paymentConfig.semesterFees=d.paymentConfig.semesterFees||{};depts.forEach(c=>{d.paymentConfig.semesterFees[c]=Array.from({length:6},(_,i)=>Number(document.getElementById(`fee_${slug(c)}_${i+1}`).value)||0)});saveDB(d);route();toast('Payable fee amounts updated. Students will see the new amounts.');}
function semesterFees(x){const d=db(),arr=d.paymentConfig?.semesterFees?.[x.course];if(Array.isArray(arr))return arr.map((amount,i)=>({sem:i+1,amount:Number(amount)||0}));return subjectsForCourse(x.course).map((_,i)=>({sem:i+1,amount:10000}));}
function studentFeesV3(x){const d=db(),paid=x.feeLedger||{},fees=semesterFees(x);return `<div class="fee-shell"><div class="fee-head"><div><span class="kicker">Academic Fee</span><h2>Semester-wise fee payment</h2><p class="muted">Payable amounts are controlled by the administrator.</p></div><div class="student-chip">${escapeHtml(x.course)} · Sem ${x.semester}</div></div><div class="fee-table"><div class="fee-row fee-header"><div>Select</div><div>Semester</div><div>Fee BreakUp</div><div>Payable</div><div>Status</div></div>${fees.map(f=>{const isPaid=paid[f.sem]==='Paid';return `<div class="fee-row"><div><input class="fee-check" type="checkbox" data-sem="${f.sem}" data-amount="${f.amount}" ${isPaid?'disabled':''} onchange="updateFeeTotal()"></div><div><b>Semester ${f.sem}</b><small>Academic fee</small></div><div><button class="breakup-btn" onclick="toggleFeeBreakup(this,${f.sem},${f.amount})">Show Fee BreakUp</button><div class="fee-breakup-dropdown"><div>Tuition Fee <b>₹${Math.round(f.amount*.8).toLocaleString('en-IN')}</b></div><div>Development / Services <b>₹${Math.round(f.amount*.2).toLocaleString('en-IN')}</b></div></div></div><div>₹${f.amount.toLocaleString('en-IN')}</div><div><span class="tag ${isPaid?'green':'orange'}">${isPaid?'Paid':'Payable'}</span></div></div>`}).join('')}<div class="fee-total"><span>Total selected</span><strong id="feeTotal">₹0</strong></div></div><div class="pay-action-row"><div><span>Total</span><strong id="feeTotal2">₹0</strong></div><button class="pay-now-btn" onclick="openStudentGatewayV3()">Pay Now</button></div><div class="card paid-history"><h3>Payment history</h3>${(d.payments||[]).filter(p=>p.studentId===x.id).slice(0,8).map(p=>`<div class="payment-history-row"><span><b>${escapeHtml(p.id)}</b><small>${new Date(p.date).toLocaleString('en-IN')}</small></span><span>${escapeHtml(p.method)}</span><strong>₹${Number(p.amount||0).toLocaleString('en-IN')}</strong><span class="tag green">${escapeHtml(p.status)}</span></div>`).join('')||'<p class="muted">No payments recorded yet.</p>'}</div></div><div class="modal" id="gatewayModal"><div class="gateway-box"><div class="gateway-top"><div><span class="kicker">Shakuntalam College</span><h2>Fee Payment Gateway</h2></div><button class="close" onclick="closeGateway()">×</button></div><div class="gateway-total">Total <strong id="gatewayTotal">₹0</strong></div><div id="gatewayBody"></div></div></div>`}
function openStudentGatewayV3(){const checks=[...document.querySelectorAll('.fee-check:checked')];if(!checks.length){toast('Select a payable semester first.');return}const total=checks.reduce((a,x)=>a+Number(x.dataset.amount),0);window._selectedFeeSems=checks.map(x=>Number(x.dataset.sem));const gt=document.getElementById('gatewayTotal'),gm=document.getElementById('gatewayModal');if(!gt||!gm){toast('Payment gateway could not open. Please refresh the Student Fee page.');return}gt.textContent='₹'+total.toLocaleString('en-IN');gm.classList.add('show');gatewayMethodV3('choose')}
function gatewayMethodV3(mode){const total=document.getElementById('gatewayTotal')?.textContent||'₹0',cfg=db().paymentConfig||{},body=document.getElementById('gatewayBody');if(!body)return;if(mode==='choose'){body.innerHTML=`<div class="new-gateway-methods"><button onclick="gatewayMethodV3('upi')"><span class="gicon">⚡</span><div><b>UPI</b><small>${escapeHtml(cfg.upi||'shakuntalam@upi')}</small></div><span>→</span></button><button onclick="gatewayMethodV3('card')"><span class="gicon">▣</span><div><b>Cards</b><small>Credit / debit card</small></div><span>→</span></button><button onclick="gatewayMethodV3('net')"><span class="gicon">▤</span><div><b>NetBanking</b><small>Choose bank</small></div><span>→</span></button></div>`;return}if(mode==='upi'){body.innerHTML=`<div class="new-upi"><div class="pay-amount"><span>Amount to pay</span><strong>${total}</strong></div><div class="upi-id-box"><span>College UPI</span><b>${escapeHtml(cfg.upi||'shakuntalam@upi')}</b><button onclick="navigator.clipboard?.writeText('${String(cfg.upi||'shakuntalam@upi').replace(/'/g,"\\'")}');toast('UPI ID copied')">Copy</button></div>${cfg.qr?`<img class="payment-qr" src="${cfg.qr}" alt="College QR">`:''}<div class="upi-choice"><button onclick="completeDemoPaymentV3('UPI App')">Open UPI App</button><button onclick="completeDemoPaymentV3('UPI')">I have paid</button></div><small class="muted">Demo mode: no real money is transferred.</small></div>`;return}if(mode==='card'){body.innerHTML=`<form class="new-payment-form" onsubmit="completeDemoPaymentV3('Card',event)"><h3>Card payment</h3><input placeholder="Card number" required><div class="form-grid"><input placeholder="MM / YY" required><input placeholder="CVV" required></div><input placeholder="Cardholder name" required><button class="pay-now-btn">Pay ${total}</button></form>`;return}body.innerHTML=`<form class="new-payment-form" onsubmit="completeDemoPaymentV3('NetBanking',event)"><h3>NetBanking</h3><select required><option value="">Choose your bank</option><option>SBI</option><option>HDFC Bank</option><option>ICICI Bank</option><option>Bank of Baroda</option></select><button class="pay-now-btn">Continue to bank</button></form>`}
function publicDepartment(slug){
  const data={
    "teachers-education":{
      title:"Department of Teachers Education",
      summary:"Build the knowledge, confidence and classroom skills to guide the next generation of learners.",
      overview:"Explore how children learn, how thoughtful lessons are designed and how supportive classrooms take shape. The department brings educational ideas together with practical teaching experience and reflective practice. Students develop a strong foundation for responsible, engaging work in education.",
      courses:[
        {name:"B.Ed.",description:"Develop teaching methods, lesson planning and a deeper understanding of learners. Connect educational theory with supervised classroom practice and reflection. Prepare to create inclusive, engaging learning experiences."},
        {name:"D.El.Ed.",description:"Build core skills for supporting children in the elementary years. Study foundational teaching methods, child development and classroom practice. Strengthen the confidence to make learning clear, active and welcoming."}
      ]
    },
    management:{
      title:"Department of Management",
      summary:"Turn curiosity into practical business, leadership and digital skills for a changing workplace.",
      overview:"The department connects business fundamentals with communication, decision-making and digital fluency. Students explore how organisations work while building the confidence to solve practical problems. Learning encourages initiative, collaboration and an understanding of the opportunities shaping modern careers.",
      courses:[
        {name:"BBA",description:"Build a broad understanding of business, management, marketing and finance. Strengthen communication, teamwork and decision-making through applied learning. Develop a foundation for entrepreneurship and further study in business."},
        {name:"BCA",description:"Learn the fundamentals of computing, programming and software development. Develop logical problem-solving skills through practical digital work. Build a base for technology careers and continued learning in computing."}
      ]
    },
    "industrial-training":{
      title:"Department of Industrial Training",
      summary:"Learn by doing through focused trade instruction, workshop practice and a strong culture of safety.",
      overview:"Training combines technical concepts with hands-on work using tools, equipment and workshop processes. Students build safe working habits, accuracy and confidence by practising tasks step by step. The department prepares learners with practical trade foundations for technical workplaces.",
      courses:[
        {name:"Electrician",description:"Study electrical fundamentals, wiring practices and the safe use of tools and equipment. Develop practical skills through workshop exercises and guided troubleshooting. Build a foundation for entry-level electrical trade work."},
        {name:"Fitter",description:"Learn measurement, fitting, assembly and workshop processes used in technical trades. Practise accuracy, tool handling and safe working methods. Develop practical foundations for fitting and maintenance environments."}
      ]
    }
  }[slug];
  if(!data)return page("Department not found","Choose a department to explore its programs.",`<section class="section"><div class="container"><a class="btn btn-primary" href="#/departments">Browse departments</a></div></section>`);
  return page(data.title,data.summary,`<section class="section department-detail"><div class="container"><article class="department-intro"><span class="kicker">Department overview</span><h2 class="department-overview-title">Learning with purpose</h2><p class="lead">${data.overview}</p><div class="department-principles"><span>Academic foundations</span><span>Practical experience</span><span>Career preparation</span></div></article><div class="section-head department-course-heading"><div><span class="kicker">Programs</span><h2>Courses in this department</h2><p>Choose a pathway to explore course information, eligibility and student services.</p></div><a class="back-link" href="#/departments">← All departments</a></div><div class="department-course-grid">${data.courses.map((course,index)=>`<article class="card department-course-card"><span class="pill">COURSE 0${index+1}</span><h3>${course.name}</h3><p class="muted">${course.description}</p><a class="btn btn-primary" href="#/course/${encodeURIComponent(course.name)}">View ${course.name} course →</a></article>`).join("")}</div></div></section>`)
}
function route(){const path=location.hash.replace(/^#/,'')||'/';let content='';if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/mission')content=mission();else if(path==='/departments')content=departments();else if(path==='/academics')content=academics();else if(path==='/administration')content=administration();else if(path==='/leadership')content=leadership();else if(path==='/leadership/founder')content=leadershipDesk('founder');else if(path==='/leadership/secretary')content=leadershipDesk('secretary');else if(path==='/leadership/principal')content=leadershipDesk('principal');else if(path==='/leadership/governing-body')content=leadershipDesk('governing-body');else if(path==='/centre-cell')content=centreCell();else if(path==='/examination')content=examination();else if(path==='/infrastructure')content=infrastructure();else if(path==='/events')content=events();else if(path==='/students-zone')content=studentsZone();else if(path==='/faculty')content=faculty();else if(path==='/student-welfare')content=studentWelfare();else if(path==='/admission-status')content=admissionStatus();else if(path.startsWith('/department/'))content=publicDepartment(decodeURIComponent(path.split('/')[2]));else if(path.startsWith('/course/'))content=course(decodeURIComponent(path.split('/')[2]));else if(path==='/notices')content=notices();else if(path==='/facilities')content=facilities();else if(path==='/gallery')content=gallery();else if(path==='/contact')content=contact();else if(path==='/admissions')content=admissions();else if(path==='/payment')content=publicPaymentGuard();else if(path.startsWith('/portal/')){const p=path.split('/').filter(Boolean),sess=currentUser(),wanted=p[1]||'student';if(!sess||sess.role!==wanted){content=page('Portal login required','Please sign in with your Shakuntalam College account.',`<section class="section"><div class="container card"><h2>Secure portal</h2><p class="muted">Sign in to access this area.</p><button class="btn btn-primary" onclick="openLogin()">Open Portal Login</button></div></section>`)}else content=portal(wanted,p[2]||'dashboard')}else content=home();app.innerHTML=content+loginModal();if(path.includes('/portal/admin/students'))renderStudentTable();startClock();window.scrollTo(0,0)}
